INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('1', '見蘭牛！お洒落な雰囲気で、美味しい焼肉を安全', '見蘭牛！お洒落な雰囲気で、美味しい焼肉を安全に。', '<h3>施工内容</h3>\n<p>今回の施工事例では、無煙ロースター18台の設置後、長期にわたって安全かつ安定した運転を維持するための定期メンテナンス体制についてご報告いたします。</p>\n<h4>定期点検と検査の取り組み</h4>\n<p>設置完了後も、当社は定期的に以下の検査・点検を実施し、常に機器が最適な状態で稼働できるよう努めています。</p>\n<ul><li><strong>火力検査</strong><br>ロースターの燃焼状態を定期的に確認し、常に適正な火力での運転が行われるよう点検を行っています。これにより、燃焼効率の低下や異常発生の早期発見が可能となります。</li> <li><strong>風速測定</strong><br>各ロースター周辺の風速を正確に測定し、適切な風量が維持されているかを確認。これにより、内部の温度分布や運転環境の最適化を図っています。</li></ul>\n<h4>ダクト内清掃とFAN交換の判断・提案</h4>\n<p>また、機器の内部状態を維持するために、ダクト内清掃やFAN交換のタイミングについても、定期的な検査を通じて最適な時期を判断しています。お客様の安全・安心を第一に、必要なメンテナンスを事前にご提案し、無用なトラブルを未然に防ぐ体制を整えています。</p>\n<h4>安心のサポート体制</h4>\n<p>設置後も最新の検査機器を活用し、各種測定データに基づいた的確なメンテナンスを実施。お客様には常に最良の状態でご利用いただけるよう、万全のサポート体制を提供しています。これにより、運転中のトラブルを防止し、安心・安全な環境づくりに貢献しています。</p>', '山口県萩市', '2018-02-14', 'published', '見蘭牛！お洒落な雰囲気で、美味しい焼肉を安全に。｜施工事例【株式会社野田】', '今回の施工事例では、無煙ロースター18台の設置後、長期にわたって安全かつ安定した運転を維持するための定期メンテナンス体制についてご報告いたします。設置完了後も、当社は定期的に以下の検査・点検を実施し、常に機器が最適な状…', '4513', '0', '830', '2025-03-06 16:31:12', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('2', '角ダクトこだわり編', '角ダクトこだわり編', '<h3>施工内容</h3>\n<p>今回ご紹介するのは、地下階の限られたスペースに合わせて製作・施工した空調ダクト事例です。梁や配管などの障害物を避けながら、複雑な角度と曲面を組み合わせることで、効率的かつ安全な空気の流れを実現しています。<strong>当社は、このようなマニアックな角ダクトも製作します。</strong><br>高い加工技術と現場での柔軟な対応力を活かし、特殊形状にも対応できるオーダーメイド製作が可能です。今後も培ってきたノウハウをもとに、お客様のニーズに合った最適な空調ソリューションを提供してまいります。</p>', '山口県', '2018-03-02', 'published', '角ダクトこだわり編｜施工事例【株式会社野田】', '今回ご紹介するのは、地下階の限られたスペースに合わせて製作・施工した空調ダクト事例です。梁や配管などの障害物を避けながら、複雑な角度と曲面を組み合わせることで、効率的かつ安全な空気の流れを実現しています。当社は、このよ…', '4518', '0', '2425', '2025-03-21 00:37:39', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('3', '地元密着型スーパー惣菜コーナーの厨房大型フー', '地元密着型スーパー惣菜コーナーの厨房大型フード　', '<h3>施工内容</h3>\n<p>今回の事例では、惣菜調理場の厨房フード・ダクト工事を担当させていただきました。変形大型フードを含む合計四基のフードを設置し、天井をできるだけ高く確保するために露出配管で施工しています。ガスコンロやスチコンなど火器の使用が多い環境のため、十分な換気量を確保できるように換気計算を実施。その結果をもとにフードやダクト、FANの選定・製作を行い、作業効率と安全性の向上を実現しました。</p>', '福岡県糟屋郡', '2018-04-06', 'published', '地元密着型スーパー惣菜コーナーの厨房大型フード　｜施工事例【株式会社野田】', '今回の事例では、惣菜調理場の厨房フード・ダクト工事を担当させていただきました。変形大型フードを含む合計四基のフードを設置し、天井をできるだけ高く確保するために露出配管で施工しています。ガスコンロやスチコンなど火器の使用…', '4521', '0', '2437', '2025-03-21 00:44:26', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('4', 'お洒落なカフェのお洒落な厨房フード', 'お洒落なカフェのお洒落な厨房フード', '<h3>施工内容</h3>\n<p>天井高が低い現場のため、通常のフード形状では十分な排気性能と作業スペースの確保が難しく、変形ソリッドフードを設計・製作・施工いたしました。限られた空間に合わせて角度やサイズを調整し、十分な換気量を確保しながらも調理の邪魔にならない形状を実現しています。厨房の環境や火器の配置に合わせたオーダーメイドの施工で、快適かつ安全な調理空間づくりに貢献いたしました。</p>', '広島市中区', '2018-04-23', 'published', 'お洒落なカフェのお洒落な厨房フード｜施工事例【株式会社野田】', '天井高が低い現場のため、通常のフード形状では十分な排気性能と作業スペースの確保が難しく、変形ソリッドフードを設計・製作・施工いたしました。限られた空間に合わせて角度やサイズを調整し、十分な換気量を確保しながらも調理の邪…', '4525', '0', '2442', '2025-03-21 00:55:43', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('5', '無煙ロースター火災', '無煙ロースター火災', '<h3>施工内容</h3>\n<p>現地調査と復旧工事をご依頼いただきました。当社は無煙ロースターの取付からダクト工事まで一貫して対応可能であり、ダクト経路などの設備状況を的確に把握できるため、迅速な状況判断が可能です。火災発生後は内装業者とも連携し、一日で仮復旧を完了させることができました。<br><strong>日ごろからのメンテナンスが重要です。是非ご相談ください。</strong></p>', '', '2018-05-23', 'published', '無煙ロースター火災｜施工事例【株式会社野田】', '現地調査と復旧工事をご依頼いただきました。当社は無煙ロースターの取付からダクト工事まで一貫して対応可能であり、ダクト経路などの設備状況を的確に把握できるため、迅速な状況判断が可能です。火災発生後は内装業者とも連携し、一…', '4528', '0', '2455', '2025-03-21 01:08:30', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('6', '和食店、洗練されたデザインフード', '和食店、洗練されたデザインフード', '<h3>施工内容</h3>\n<p>フード外装に銅板を貼り付けることで、装飾効果を高め、高級感のある店内演出を実現しました。酒蔵の街としても有名な東広島市西条に位置する店舗で、冬場の寒気が厳しいため、給気工事にも十分配慮して空調バランスを整えています。銅板の美しい色合いが店内の雰囲気を引き立て、特別感を演出する施工事例となりました。</p>', '広島県東広島市', '2018-06-08', 'published', '和食店、洗練されたデザインフード｜施工事例【株式会社野田】', 'フード外装に銅板を貼り付けることで、装飾効果を高め、高級感のある店内演出を実現しました。酒蔵の街としても有名な東広島市西条に位置する店舗で、冬場の寒気が厳しいため、給気工事にも十分配慮して空調バランスを整えています。銅…', '4533', '0', '2463', '2025-03-21 01:15:07', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('7', '牛丼の吉野家　ダクト改修工事', '牛丼の吉野家　ダクト改修工事', '<h3>施工内容</h3>\n<p>吉野家様のダクト改修工事を、福岡県内の各店舗（原店・那珂川店・築港店・港店・粕屋仲原店・箱崎店・春吉店・原田店・黒崎店・片野店・小倉中井店 等）にて承りました。<br>設計図面に忠実に施工を行い、効率的な排気環境を整備することで、店舗運営をしっかりとサポートしております。</p>', '福岡県', '2018-07-13', 'published', '牛丼の吉野家　ダクト改修工事｜施工事例【株式会社野田】', '吉野家様のダクト改修工事を、福岡県内の各店舗（原店・那珂川店・築港店・港店・粕屋仲原店・箱崎店・春吉店・原田店・黒崎店・片野店・小倉中井店等）にて承りました。設計図面に忠実に施工を行い、効率的な排気環境を整備することで…', '4537', '0', '2472', '2025-03-21 01:30:57', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('8', '箱型フードから上引きクリアフードへ', '箱型フードから上引きクリアフードへ', '<h3>施工内容</h3>\n<p>既存の箱型フードから上引きクリアフードへの交換に伴い、ダクトおよびFANの交換工事を実施しました。天井高が低い現場のため、圧迫感を軽減するよう薄型の角ダクトを採用しながらも、排煙性能をしっかり確保。<br>また、<strong>毎度の事ですが風量計算を行い、ダクト・FANを選定施工</strong>しているため、暑いシーズンでも排煙と冷房の両面で効果を発揮できるよう設計されています。従来の箱型フードに比べて冷房負荷が大幅に軽減し、店内の快適性が向上しました。</p>', '佐賀県', '2018-08-21', 'published', '箱型フードから上引きクリアフードへ｜施工事例【株式会社野田】', '既存の箱型フードから上引きクリアフードへの交換に伴い、ダクトおよびFANの交換工事を実施しました。天井高が低い現場のため、圧迫感を軽減するよう薄型の角ダクトを採用しながらも、排煙性能をしっかり確保。また、毎度の事ですが…', '4541', '0', '2479', '2025-03-21 01:36:27', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('9', 'しゃぶ葉-熊本合志店様の新店ダクト工事', 'しゃぶ葉 熊本合志店様の新店ダクト工事', '<h3>施工内容</h3>\n<p>しゃぶ葉様大型店舗における<strong>厨房フード、客席給気のダクト工事です。</strong><br>天井内に角ダクト・排煙FANを仕込み、<strong>断熱工事</strong>を施しています。天井が仕上がり次第、<strong>厨房フードを設置</strong>し、給気グリル器具等を取り付け予定です。<br>また、<strong>大型店舗ということもあり、何社もの業者が入るため、綿密な工程会議</strong>を行い、工期を遅らせないよう努めています。</p>', '熊本県合志市', '2018-09-04', 'published', 'しゃぶ葉 熊本合志店様の新店ダクト工事｜施工事例【株式会社野田】', 'しゃぶ葉様大型店舗における厨房フード、客席給気のダクト工事です。天井内に角ダクト・排煙FANを仕込み、断熱工事を施しています。天井が仕上がり次第、厨房フードを設置し、給気グリル器具等を取り付け予定です。また、大型店舗と…', '4545', '0', '2488', '2025-03-21 01:43:13', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('10', '飯塚市のホルモンセンター2階の改装工事', '飯塚市のホルモンセンター2階の改装工事', '<h3>施工内容</h3>\n<p>煙の排煙効率を最優先に考慮し、ダクト工事を施工しました。上引きフードを採用することで、焼肉調理時の煙を効果的に排出し、店内環境を快適に保ちます。<br>また、お店の雰囲気づくりにもこだわり、照明・畳・内装・トイレなどを、タッグを組んでいる大工さんと綿密に打ち合わせを行いながら決定しました。焼肉店としての機能性と、居心地の良い空間づくりを両立させる施工事例となっています。</p>', '福岡県飯塚市', '2018-09-28', 'published', '飯塚市のホルモンセンター2階の改装工事｜施工事例【株式会社野田】', '煙の排煙効率を最優先に考慮し、ダクト工事を施工しました。上引きフードを採用することで、焼肉調理時の煙を効果的に排出し、店内環境を快適に保ちます。また、お店の雰囲気づくりにもこだわり、照明・畳・内装・トイレなどを、タッグ…', '4550', '0', '2495', '2025-03-21 01:49:03', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('11', '希代の豚骨ラーメン店　博多一双！！', '希代の豚骨ラーメン店　博多一双！！', '<h3>施工内容</h3>\n<p>本店では、店内に匂いが充満する課題を抱えており、既に複数社による改修工事が行われていましたが、十分な改善が見られませんでした。当社では、既存FANをそのまま活用しつつ、ダクトの設計を見直すことで、排煙・排臭効果を大幅に向上（体感で200％アップ）させ、店内の匂い問題を解消いたしました。</p>\n<p>本店の改善実績をご評価いただき、中洲店およびセントラルキッチンにおいても、同様に排煙・排熱対策を実施。特にセントラルキッチンでは、排熱不足による高温環境が課題となっていたため、FANやダクトの新規設計・取替工事を行い、効率的な排煙と排熱を実現しました。</p>\n<p>当社は、調理時の煙対策を専門とするダクト施工会社として、既存設備の活用や設計の工夫により、排煙・排臭・排熱の問題を効果的に解消し、快適な調理・接客環境を提供しております。</p>', '福岡市博多区', '2018-10-23', 'published', '希代の豚骨ラーメン店　博多一双！！｜施工事例【株式会社野田】', '本店では、店内に匂いが充満する課題を抱えており、既に複数社による改修工事が行われていましたが、十分な改善が見られませんでした。当社では、既存FANをそのまま活用しつつ、ダクトの設計を見直すことで、排煙・排臭効果を大幅に…', '4554', '0', '2503', '2025-03-21 01:55:48', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('12', 'コインランドリー施工', 'コインランドリー施工', '<h3>施工内容</h3>\n<p>大型乾燥機の排気を効率的に行うため、<strong>全てステンレスダクト</strong>を使用して施工いたしました。高温・高湿度に対応できるよう、素材や接合部に至るまでこだわり抜いた設計を行い、目に見えない部分にも高い品質を追求しています。大手チェーン店様ならではの厳しい基準に応えるべく、安全性と耐久性を両立させた排気システムを構築しました。結果として、快適で清潔な店内環境づくりに貢献しております。</p>', '福岡県大野城市', '2018-11-19', 'published', 'コインランドリー施工｜施工事例【株式会社野田】', '大型乾燥機の排気を効率的に行うため、全てステンレスダクトを使用して施工いたしました。高温・高湿度に対応できるよう、素材や接合部に至るまでこだわり抜いた設計を行い、目に見えない部分にも高い品質を追求しています。大手チェー…', '4557', '0', '2528', '2025-03-21 11:09:45', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('13', '手作り排煙設備から上引きクリアフードへの取替', '手作り排煙設備から上引きクリアフードへの取替工事', '<h3>施工内容</h3>\n<p>既存の手作り排煙設備では、油漏れやFANの能力低下によって排煙が十分に行えず、店内環境に影響が生じていました。そこで当社では、上引きクリアフードへの取替工事を実施し、排煙効率の向上と快適な店内づくりを目指しました。</p>\n<p>本施工では、お店の雰囲気を損なわないよう、照明位置とのバランスを考慮したデザインを採用し、さらに排煙効果を高めるための給気工事も同時に行っています。また、隣地との境界が狭いという制約条件を踏まえ、外部FANの配置を入念に打ち合わせたうえで設置しました。</p>\n<p>従来のダクト設備における油漏れやFANの能力低下による排煙不足を解消すると同時に、クリアフードによる洗練された空間を演出。さらに、網焼き台を性能の良いものへ交換したことで、お客様からの評判も上々です。今回の工事によって、排煙能力の大幅な向上と店内環境の改善を実現いたしました。</p>', '福岡県', '2018-12-21', 'published', '手作り排煙設備から上引きクリアフードへの取替工事｜施工事例【株式会社野田】', '既存の手作り排煙設備では、油漏れやFANの能力低下によって排煙が十分に行えず、店内環境に影響が生じていました。そこで当社では、上引きクリアフードへの取替工事を実施し、排煙効率の向上と快適な店内づくりを目指しました。本施…', '4561', '0', '2542', '2025-03-21 11:16:43', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('14', '幻の壱岐牛！焼肉弦様-壱岐', '幻の壱岐牛！焼肉弦様-壱岐', '<h3>施工内容</h3>\n<p>文化芸術村の跡地という歴史ある建物を活かしつつ、新たに無煙ロースター8台の設置とダクト工事一式を行いました。店内の雰囲気に合わせた天板を選定することで、落ち着きと上質感を兼ね備えた空間を演出しています。</p>\n<p>当社では、<strong>200種類以上の天板化粧板</strong>をご用意しており、あらゆる店舗イメージに合わせたコーディネートが可能です。今回の施工では、歴史ある建物の趣きを損なわないよう配慮しながら、逆に天板の選定によって空間に新たな魅力をプラスしました。</p>\n<p>無煙ロースターとダクト工事の組み合わせにより、煙や臭いを効果的に排出し、快適な飲食環境を実現。お客様がゆったりと食事を楽しめるよう、歴史的建造物の持つ雰囲気と現代的な機能性を両立させています。</p>', '長崎県壱岐市', '2019-01-10', 'published', '幻の壱岐牛！焼肉弦様-壱岐｜施工事例【株式会社野田】', '文化芸術村の跡地という歴史ある建物を活かしつつ、新たに無煙ロースター8台の設置とダクト工事一式を行いました。店内の雰囲気に合わせた天板を選定することで、落ち着きと上質感を兼ね備えた空間を演出しています。当社では、200…', '4566', '0', '2550', '2025-03-21 11:21:27', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('15', '新規オープン焼肉店-無煙ロースター12台設置・ダ', '新規オープン焼肉店 無煙ロースター12台設置・ダクト工事一式', '<h3>施工内容</h3>\n<p>新たにオープンした焼肉店において、<strong>無煙ロースター12台の設置とダクト工事一式</strong>を担当いたしました。お肉が美味しく焼けるよう火力検査はもちろんのこと、当社独自のノウハウを活かしたダクト設計と風速測定を行い、<strong>煙を極力出さずに美味しく焼き上げる</strong>環境を実現しています。これにより、お客様の満足度向上につながる快適な店内を実現しました。</p>\n<p>本店舗は、古民家の廃材などを利用した<strong>温かみのある内外装</strong>が特徴で、見た目にもこだわり抜いた仕上がりとなっています。ダクトの貫通部などは、単に隠すだけでなく、<strong>デザイン性を重視してあえて見せる</strong>ことで、存在感を活かした仕上がりに。店舗全体の雰囲気と融合した排煙システムが、味わい深い空間づくりに大きく貢献しています。</p>', '福岡市西区', '2019-02-19', 'published', '新規オープン焼肉店 無煙ロースター12台設置・ダクト工事一式｜施工事例【株式会社野田】', '新たにオープンした焼肉店において、無煙ロースター12台の設置とダクト工事一式を担当いたしました。お肉が美味しく焼けるよう火力検査はもちろんのこと、当社独自のノウハウを活かしたダクト設計と風速測定を行い、煙を極力出さずに…', '4571', '0', '2557', '2025-03-21 11:28:04', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('16', '長崎壱岐-磯焼・焼肉-深山苑-新型火山石無煙ロー', '長崎壱岐-磯焼・焼肉 深山苑 新型火山石無煙ロースター導入', '<h3>施工内容</h3>\n<p>壱岐で新鮮な海鮮料理を提供することで有名な「大幸物産（わたつみ）」がプロデュースする、BBQハウスをコンセプトにした磯焼・焼肉のお店「深山苑」に、当社の新型火山石無煙ロースターを導入いただきました。</p>\n<p>福岡市から高速船で約1時間強とアクセスも良く、観光やレジャーの合間に気軽に立ち寄ることができます。無煙ロースターの採用により、煙の立ち上りを抑え、冷暖房完備の快適な店内で新感覚のBBQをお楽しみいただけます。</p>\n<p>また、当社の新型火山石無煙ロースターには、<strong>最高級の遠赤外線効果が得られると言われる富士山火山石</strong>を採用。こだわりの一夜干しや海鮮、焼肉をよりふっくらと焼き上げることができると、大変ご好評をいただいております。壱岐の美しい景色と新鮮な食材を存分に味わいながら、特別なひとときをぜひお過ごしください。</p>', '長崎県壱岐市', '2019-03-13', 'published', '長崎壱岐-磯焼・焼肉 深山苑 新型火山石無煙ロースター導入｜施工事例【株式会社野田】', '壱岐で新鮮な海鮮料理を提供することで有名な「大幸物産（わたつみ）」がプロデュースする、BBQハウスをコンセプトにした磯焼・焼肉のお店「深山苑」に、当社の新型火山石無煙ロースターを導入いただきました。福岡市から高速船で約…', '4576', '0', '2567', '2025-03-21 11:35:54', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('17', '博多区住吉に移転オープン「焼肉牛光様」-新型火', '博多区住吉に移転オープン「焼肉牛光様」 新型火山石無煙ロースター導入工事', '<h3>施工内容</h3>\n<p>博多区住吉へ移転オープンされた「焼肉牛光様」にて、当社の新型火山石無煙ロースター工事を行いました。富士山火山石による最高級の遠赤外線効果で、お肉をふっくらジューシーに焼き上げることができます。</p>\n<p>店内はシックで洗練された大人の雰囲気が漂い、少人数から利用できる完全個室も完備。カップルでの大人デートはもちろん、ワンランク上の焼肉を楽しみたい方にもおすすめです。落ち着いた内装の中で、思う存分“美味い焼肉”を堪能してみてはいかがでしょうか。</p>', '福岡市博多区', '2019-04-04', 'published', '博多区住吉に移転オープン「焼肉牛光様」 新型火山石無煙ロースター導入工事｜施工事例【株式会社野田】', '博多区住吉へ移転オープンされた「焼肉牛光様」にて、当社の新型火山石無煙ロースター工事を行いました。富士山火山石による最高級の遠赤外線効果で、お肉をふっくらジューシーに焼き上げることができます。店内はシックで洗練された大…', '4581', '0', '2575', '2025-03-21 11:39:47', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('18', '福岡県-ホルモン・焼肉-まんぷく様（甘木駅前）', '福岡県-ホルモン・焼肉 まんぷく様（甘木駅前） ダクト工事', '<h3>施工内容</h3>\n<p>甘木駅前に位置し、地元のお客様に愛されている「ホルモン・焼肉 まんぷく様」の排煙ダクト工事を行いました。近隣事務所への影響を考慮し、ビルの屋上まで排煙ダクトを立ち上げることで、周辺環境に配慮した設計となっています。</p>\n<p>店内では、当社施工の<strong>上引きフード</strong>を採用し、煙の多く出るホルモンを調理する際でも、煙や臭いを最小限に抑えることに成功。気軽に立ち寄れる雰囲気を保ちながら、快適な店内環境を実現しました。お客様に美味しく安心してお食事を楽しんでいただけるよう、これからも丁寧な施工とアフターサポートを心掛けてまいります。</p>', '福岡県朝倉市', '2019-04-22', 'published', '福岡県-ホルモン・焼肉 まんぷく様（甘木駅前） ダクト工事｜施工事例【株式会社野田】', '甘木駅前に位置し、地元のお客様に愛されている「ホルモン・焼肉まんぷく様」の排煙ダクト工事を行いました。近隣事務所への影響を考慮し、ビルの屋上まで排煙ダクトを立ち上げることで、周辺環境に配慮した設計となっています。店内で…', '4586', '0', '2577', '2025-03-21 11:43:39', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('19', '炭火焼肉「萬まる」九州一号店（福工大駅前）-上', '炭火焼肉「萬まる」九州一号店（福工大駅前） 上引きフード施工', '<h3>施工内容</h3>\n<p>福工大駅前にオープンした「萬まる」九州一号店様では、全席に当社施工の<strong>上引きフード</strong>を導入し、煙が気にならない快適な空間を実現しました。店内で本格的な炭火焼肉を楽しんでいただけるよう、しっかりと煙を吸気・排気するだけでなく、<strong>配管を隠さずにあえてスタイリッシュに見せる</strong>デザインにもこだわっています。屋外の配管に至るまで丁寧に施工し、機能性とデザイン性を両立させた上質な店内環境をお届けいたします。</p>', '福岡市東区', '2019-05-21', 'published', '炭火焼肉「萬まる」九州一号店（福工大駅前） 上引きフード施工｜施工事例【株式会社野田】', '福工大駅前にオープンした「萬まる」九州一号店様では、全席に当社施工の上引きフードを導入し、煙が気にならない快適な空間を実現しました。店内で本格的な炭火焼肉を楽しんでいただけるよう、しっかりと煙を吸気・排気するだけでなく…', '4591', '0', '2587', '2025-03-21 11:47:11', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('20', '福岡西新「焼肉ガブクロ」-ダクト工事', '福岡西新「焼肉ガブクロ」 ダクト工事', '<h3>施工内容</h3>\n<p>宮崎牛にこだわるご夫婦が営む「焼肉ガブクロ」様では、従来の換気効率が悪く、店内に煙や臭いがこもりがちでした。そこで当社が<strong>ダクトの経路変更</strong>と<strong>排煙ファンの交換</strong>を行うことで、換気能力を大幅に改善。コロナ禍においても安心してご利用いただける、快適な店内環境を実現いたしました。宮崎出身のオーナーならではのこだわりが詰まった、美味しい宮崎牛を存分にお楽しみいただけます。</p>', '福岡市早良区', '2019-06-27', 'published', '福岡西新「焼肉ガブクロ」 ダクト工事｜施工事例【株式会社野田】', '宮崎牛にこだわるご夫婦が営む「焼肉ガブクロ」様では、従来の換気効率が悪く、店内に煙や臭いがこもりがちでした。そこで当社がダクトの経路変更と排煙ファンの交換を行うことで、換気能力を大幅に改善。コロナ禍においても安心してご…', '4595', '0', '2594', '2025-03-21 11:50:24', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('21', '北九州を中心に複数店舗を展開するめいげつ様の', '北九州を中心に複数店舗を展開するめいげつ様の新店舗', '<h3>施工内容</h3>\n<p>黒色と木目を基調とした落ち着いた店内で、「美味しい焼肉を低価格で！」をモットーに、地域のお客様に愛されるお店づくりを目指しています。<br>当社施工の<strong>上引きフード</strong>を採用し、排煙・換気対策も万全。心地よい空間でゆったりと焼肉を楽しめる店舗となりました。</p>', '福岡県北九州市', '2019-07-23', 'published', '北九州を中心に複数店舗を展開するめいげつ様の新店舗｜施工事例【株式会社野田】', '黒色と木目を基調とした落ち着いた店内で、「美味しい焼肉を低価格で！」をモットーに、地域のお客様に愛されるお店づくりを目指しています。当社施工の上引きフードを採用し、排煙・換気対策も万全。心地よい空間でゆったりと焼肉を楽…', '4600', '0', '2605', '2025-03-21 11:56:24', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('22', '横浜家系ラーメン-春吉屋-西新店-厨房ダクト・換', '横浜家系ラーメン 春吉屋 西新店 厨房ダクト・換気扇 新設工事', '<h3>施工内容</h3>\n<p>横浜家系ラーメンで注目を集める「春吉屋」西新店様にて、<strong>厨房ダクト・換気扇の新設工事</strong>を担当いたしました。濃厚な豚骨醤油ベースのスープが特徴のラーメン店では、豚骨特有の匂い対策が重要となるため、<strong>換気効率を綿密に計算し、排煙・排臭を徹底</strong>しています。<br>さらに、天神3丁目店様、新宮店様の改修工事も合わせて行い、お客様が快適にラーメンを楽しめる空間づくりをサポートいたしました。</p>', '福岡市早良区', '2019-08-08', 'published', '横浜家系ラーメン 春吉屋 西新店 厨房ダクト・換気扇 新設工事｜施工事例【株式会社野田】', '横浜家系ラーメンで注目を集める「春吉屋」西新店様にて、厨房ダクト・換気扇の新設工事を担当いたしました。濃厚な豚骨醤油ベースのスープが特徴のラーメン店では、豚骨特有の匂い対策が重要となるため、換気効率を綿密に計算し、排煙…', '4605', '0', '2614', '2025-03-21 12:00:12', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('23', '福岡市中央区-集塵機（消煙機）による煙対策-焼鳥', '福岡市中央区-集塵機（消煙機）による煙対策-焼鳥八朔様', '<h3>施工内容</h3>\n<p>周辺住民からの煙に対する苦情が頻発し、福岡県の環境課の指導のもと、店内から漏れる煙を抑制するための<strong>集塵機設置工事</strong>を行いました。施工前には住民説明会に参加し、集塵機の仕組みや期待できる効果について丁寧にご説明。施工後は、周辺エリアにおける煙に関する苦情が<strong>大幅に減少</strong>し、地域の方々にも安心していただける環境づくりに貢献できました。</p>', '福岡市中央区', '2019-09-17', 'published', '福岡市中央区-集塵機（消煙機）による煙対策-焼鳥八朔様｜施工事例【株式会社野田】', '周辺住民からの煙に対する苦情が頻発し、福岡県の環境課の指導のもと、店内から漏れる煙を抑制するための集塵機設置工事を行いました。施工前には住民説明会に参加し、集塵機の仕組みや期待できる効果について丁寧にご説明。施工後は、…', '4610', '0', '2622', '2025-03-21 12:04:42', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('24', 'ファン交換による換気能力改善工事', 'ファン交換による換気能力改善工事', '<h3>施工内容</h3>\n<p>コロナ禍において、店内の換気対策は非常に重要となっています。そこで当社では、既存設備の換気能力を向上させるために、<strong>ファン交換</strong>を実施しました。新しいファンの導入により、店内の空気循環を効率化し、より安心・安全な環境づくりに貢献しています。</p>', '山口県下松市', '2019-10-02', 'published', 'ファン交換による換気能力改善工事｜施工事例【株式会社野田】', 'コロナ禍において、店内の換気対策は非常に重要となっています。そこで当社では、既存設備の換気能力を向上させるために、ファン交換を実施しました。新しいファンの導入により、店内の空気循環を効率化し、より安心・安全な環境づくり…', '4613', '0', '2627', '2025-03-21 12:08:21', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('25', '人気ラーメン店「一双」様が手掛ける新業態のラ', '人気ラーメン店「一双」様が手掛ける新業態のラーメン食堂', '<h3>施工内容</h3>\n<p>連日大行列ができる超人気ラーメン店「一双」様の新たな業態としてオープンしたラーメン食堂にて、ダクト換気扇工事を担当いたしました。一双様のダクト換気扇工事に続き、今回もご依頼をいただき感謝申し上げます。</p>\n<p>本店舗は、“新しいけれどどこか懐かしい（ネオノスタルジック）”をコンセプトに、醤油ラーメンや塩ラーメンを中心に提供。炒飯や唐揚げも人気メニューとして好評を博しています。当社の施工によって、厨房内の排煙・換気を効率的に行い、快適な調理環境をサポートいたしました。今後もお客様に愛される店舗づくりに貢献できるよう、丁寧な工事とアフターフォローを心掛けてまいります。</p>', '福岡市西区', '2019-11-11', 'published', '人気ラーメン店「一双」様が手掛ける新業態のラーメン食堂｜施工事例【株式会社野田】', '連日大行列ができる超人気ラーメン店「一双」様の新たな業態としてオープンしたラーメン食堂にて、ダクト換気扇工事を担当いたしました。一双様のダクト換気扇工事に続き、今回もご依頼をいただき感謝申し上げます。本店舗は、“新しい…', '4616', '0', '2633', '2025-03-21 12:11:46', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('26', '焼き鳥とワイン-萬鳥様（薬院店・祇園店）-消煙機', '焼き鳥とワイン 萬鳥様（薬院店・祇園店） 消煙機導入', '<h3>施工内容</h3>\n<p>中央区薬院にある「焼き鳥とワイン 萬鳥」様には<strong>ND-1800</strong>、博多区祇園町にある「焼き鳥とワイン 萬鳥」様には<strong>ND-3000</strong>の消煙機を導入していただきました。両店舗ともマンションなどの住居が隣接する立地で、焼き鳥を調理する際に発生する煙が多く、近隣住民とのトラブルに発展する恐れがありました。そこで、<strong>問題が大きくなる前に事前対策として消煙機を設置</strong>し、煙を効果的に処理しています。</p>\n<p>当社では、<strong>アフターサービスも万全</strong>の体制を整えており、定期的なフィルター洗浄サービスや本体保守サービスをご利用いただけます。また、<strong>レンタルサービス</strong>も受け付けておりますので、導入をご検討中の方はお気軽にお問い合わせください。</p>', '福岡市', '2019-11-26', 'published', '焼き鳥とワイン 萬鳥様（薬院店・祇園店） 消煙機導入｜施工事例【株式会社野田】', '中央区薬院にある「焼き鳥とワイン萬鳥」様にはND-1800、博多区祇園町にある「焼き鳥とワイン萬鳥」様にはND-3000の消煙機を導入していただきました。両店舗ともマンションなどの住居が隣接する立地で、焼き鳥を調理する…', '4622', '0', '2643', '2025-03-21 12:16:05', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('27', '福岡市中央区-厨房ダクト換気扇工事', '福岡市中央区-厨房ダクト換気扇工事', '<h3>施工内容</h3>\n<p>集合ビル内に位置するため、屋外への排気ファン設置が困難な現場において、天井内に排気ファンを設置し、断熱処理・給気工事・火災防止工事を同時に実施いたしました。天井空間を活用した排気システムの設計により、ビル内でも効率的な換気環境を実現しております。天井内排気ファンの設置では、ビル構造上、屋外にファンを設置できない制約を克服するため、排気経路を最適化して十分な換気性能を確保しています。ダクトには断熱処理を施し、結露や熱損失のリスクを軽減し、給気ガラリを設置して排気とのバランスを取りながら新鮮な空気を効率的に取り込めるよう工夫しています。さらに、フード内にグリスフィルターを設置し、油煙を捕集することで火災リスクを低減し、安全面にも十分配慮した設計を行いました。当社は、集合ビルなど制約のある環境でも、天井空間を活用した排気システムの設計・施工に豊富な実績を有しており、今後も蓄積したノウハウを活かして効率的かつ安全な厨房環境の構築をサポートしてまいります。</p>', '福岡市中央区', '2019-12-19', 'published', '福岡市中央区-厨房ダクト換気扇工事｜施工事例【株式会社野田】', '集合ビル内に位置するため、屋外への排気ファン設置が困難な現場において、天井内に排気ファンを設置し、断熱処理・給気工事・火災防止工事を同時に実施いたしました。天井空間を活用した排気システムの設計により、ビル内でも効率的な…', '4625', '1', '2649', '2025-03-21 12:21:53', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('28', '山口県岩国市-鉄板焼き専門店-厨房内ダクト換気扇', '山口県岩国市 鉄板焼き専門店 厨房内ダクト換気扇新設工事', '<h3>施工内容</h3>\n<p>錦帯橋が有名な山口県岩国市に、オープン予定のお肉メインの鉄板焼き専門店にて、厨房内のダクト換気扇新設工事を行いました。鉄板焼きは煙や臭いが多く発生するため、排煙対策が特に重要となります。そこで、天井内スペースを有効活用し、給気システムを導入することで効率的な排煙を実現しました。今後も、地元の名所を訪れる観光客や地域のお客様に、快適な店内環境で美味しい鉄板焼きを楽しんでいただけるよう、サポートしてまいります。</p>', '山口県岩国市', '2020-01-15', 'published', '山口県岩国市 鉄板焼き専門店 厨房内ダクト換気扇新設工事｜施工事例【株式会社野田】', '錦帯橋が有名な山口県岩国市に、オープン予定のお肉メインの鉄板焼き専門店にて、厨房内のダクト換気扇新設工事を行いました。鉄板焼きは煙や臭いが多く発生するため、排煙対策が特に重要となります。そこで、天井内スペースを有効活用…', '4630', '0', '2657', '2025-03-21 12:25:41', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('29', '離島の有機野菜とジビエを使ったお店の厨房フー', '離島の有機野菜とジビエを使ったお店の厨房フード工事', '<h3>施工内容</h3>\n<p><strong>広島県の離島にある有機野菜とジビエを提供するお店</strong>にて、天井内ダクトの施工を行いました。防火対策としてダンパーを設置し、ダクトの断熱処理も含めて1日で完了。限られた施工期間のなかで、迅速かつ丁寧に仕上げることで、安全性と快適性を両立させた店内環境を実現しました。</p>', '広島県', '2020-02-25', 'published', '離島の有機野菜とジビエを使ったお店の厨房フード工事｜施工事例【株式会社野田】', '広島県の離島にある有機野菜とジビエを提供するお店にて、天井内ダクトの施工を行いました。防火対策としてダンパーを設置し、ダクトの断熱処理も含めて1日で完了。限られた施工期間のなかで、迅速かつ丁寧に仕上げることで、安全性と…', '4635', '0', '2665', '2025-03-22 10:20:57', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('30', '福岡市中央区大手門の上引きフード設計施工【ホ', '福岡市中央区大手門の上引きフード設計施工【ホルモン酒場 六べこ様】', '<h3>施工内容</h3>\n<p>店舗リニューアルオープンに伴い、カウンター席を増設したことで、クリアフードを追加導入していただきました。鮮度の良いお肉を提供する福岡で一番元気な居酒屋として、より快適な店内環境を整えるため、排気能力を高めるファンへの交換を実施。さらに、当社の消煙機を活用し、近隣への煙対策も万全に行っています。新しく生まれ変わったカウンター席では、活気ある雰囲気の中で、鮮度抜群のお肉を存分にお楽しみいただけます。</p>', '福岡市中央区', '2020-03-10', 'published', '福岡市中央区大手門の上引きフード設計施工【ホルモン酒場 六べこ様】｜施工事例【株式会社野田】', '店舗リニューアルオープンに伴い、カウンター席を増設したことで、クリアフードを追加導入していただきました。鮮度の良いお肉を提供する福岡で一番元気な居酒屋として、より快適な店内環境を整えるため、排気能力を高めるファンへの交…', '4639', '0', '2808', '2025-03-22 10:25:42', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('31', '福岡市東区-ベトナム風アジアンカフェの厨房フー', '福岡市東区-ベトナム風アジアンカフェの厨房フード工事', '<h3>施工内容</h3>\n<p>福岡市東区にて、新たにオープン予定のベトナム風アジアンカフェの厨房排煙設備工事を担当させていただきました。</p>\n<p>今回の施工では、厨房内に2カ所の排煙フードを設置し、併せて排煙ファンの新設も行いました。調理時に発生する油煙や熱気をしっかりと排出するため、フードにはグリスフィルターを備え、各所にダンパーを取り付けることで、効率的かつ安全な換気を実現しています。</p>\n<p>さらに、万が一の火災を想定し、壁面には不燃材の板を施工。防火対策としても万全の環境を整えました。</p>\n<p>当社では、アジア料理店など油煙量が多い業態においても、最適な換気設計と丁寧な施工で、快適かつ安心な厨房環境づくりをお手伝いしております。</p>', '福岡市東区', '2020-04-03', 'published', '福岡市東区-ベトナム風アジアンカフェの厨房フード工事｜施工事例【株式会社野田】', '福岡市東区にて、新たにオープン予定のベトナム風アジアンカフェの厨房排煙設備工事を担当させていただきました。今回の施工では、厨房内に2カ所の排煙フードを設置し、併せて排煙ファンの新設も行いました。調理時に発生する油煙や熱…', '4643', '0', '2820', '2025-03-22 11:23:12', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('32', '福岡市中央区大濠にある串揚げ居酒屋の厨房フー', '福岡市中央区大濠にある串揚げ居酒屋の厨房フード工事', '<h3>施工内容</h3>\n<p>福岡市中央区大濠に新たにオープンする串揚げ居酒屋の厨房フード設備工事を担当いたしました。2台のフードをそれぞれ別々の経路で排煙し、店舗裏手へ排出する設計とすることで、正面側には煙が行かないよう配慮しています。複雑なダクトレイアウトにも対応し、安全かつ効率的な排煙を実現しました。</p>', '福岡市中央区', '2020-05-08', 'published', '福岡市中央区大濠にある串揚げ居酒屋の厨房フード工事｜施工事例【株式会社野田】', '福岡市中央区大濠に新たにオープンする串揚げ居酒屋の厨房フード設備工事を担当いたしました。2台のフードをそれぞれ別々の経路で排煙し、店舗裏手へ排出する設計とすることで、正面側には煙が行かないよう配慮しています。複雑なダク…', '4648', '0', '2822', '2025-03-22 11:26:25', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('33', '愛媛県新居浜市-【炭火焼肉-萬まる様】-上引きフ', '愛媛県新居浜市 【炭火焼肉 萬まる様】 上引きフード工事', '<h3>施工内容</h3>\n<p>愛媛県新居浜市に新規オープンした「炭火焼肉 萬まる」様では、お肉だけでなく炊き立ての土鍋ご飯や自家製メニューも楽しめるアットホームな雰囲気が魅力です。店内は全室個室が特徴で、各部屋に上引きフード（支給品）を導入することで、煙を極力抑えつつ美味しく焼ける環境を実現し、お客様の満足度を高めています。排煙ダクトは屋上へ立ち上げる設計とし、近隣への煙トラブル対策も万全です。こうした設計を柔軟に行えることも、当社の強みのひとつです。</p>', '愛媛県新居浜市', '2020-05-27', 'published', '愛媛県新居浜市 【炭火焼肉 萬まる様】 上引きフード工事｜施工事例【株式会社野田】', '愛媛県新居浜市に新規オープンした「炭火焼肉萬まる」様では、お肉だけでなく炊き立ての土鍋ご飯や自家製メニューも楽しめるアットホームな雰囲気が魅力です。店内は全室個室が特徴で、各部屋に上引きフード（支給品）を導入することで…', '4653', '0', '2830', '2025-03-22 11:47:04', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('34', '福岡県行橋市の人気ベーカーリーの厨房フード工', '福岡県行橋市の人気ベーカーリーの厨房フード工事　', '<h3>施工内容</h3>\n<p>福岡県行橋市にある人気ベーカリーの増設に伴い、厨房設備工事を担当させていただきました。食パンを中心に多彩な種類を提供されており、そのこだわりから常に高い人気を誇るお店です。今回の増設工事では、フードや排気ダクト、給排気ファンの設置を行い、パン作りに適した環境を整備。効率的な換気と衛生面の向上を図ることで、お店のこだわり抜いたパン作りをさらにサポートする体制を整えました。</p>', '福岡県行橋市', '2020-06-17', 'published', '福岡県行橋市の人気ベーカーリーの厨房フード工事　｜施工事例【株式会社野田】', '福岡県行橋市にある人気ベーカリーの増設に伴い、厨房設備工事を担当させていただきました。食パンを中心に多彩な種類を提供されており、そのこだわりから常に高い人気を誇るお店です。今回の増設工事では、フードや排気ダクト、給排気…', '4658', '0', '2845', '2025-03-22 11:56:47', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('35', '長崎県-厨房フード工事【焼きトン永様】　', '長崎県-厨房フード工事【焼きトン永様】　', '<h3>施工内容</h3>\n<p>長崎にある人気ホルモン焼屋「焼きトン 永」様の新店舗にて、炭火焼ホルモンを快適に提供するため、排煙フードの増設工事を行いました。カウンター席を中心としたアットホームな雰囲気の中、お客様との会話を楽しんでいただけるよう、排気音を抑えるために静穏タイプのファンを採用し、さらに風切り音を抑制する消音BOXも施工しています。こうした対策により、ホルモンを焼く際の煙や臭いを効果的に排出しながらも、店内の静かな空間を保つことができ、施工後の仕上がりにご満足いただきました。</p>', '長崎県長崎市', '2020-07-13', 'published', '長崎県-厨房フード工事【焼きトン永様】　｜施工事例【株式会社野田】', '長崎にある人気ホルモン焼屋「焼きトン永」様の新店舗にて、炭火焼ホルモンを快適に提供するため、排煙フードの増設工事を行いました。カウンター席を中心としたアットホームな雰囲気の中、お客様との会話を楽しんでいただけるよう、排…', '4663', '0', '2853', '2025-03-22 12:01:05', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('36', 'trial（スーパーセンター）の総菜厨房移設工事', 'TRIAL（スーパーセンター）の総菜厨房移設工事', '<h3>施工内容</h3>\n<p>総菜部門の移設に伴い、既存の厨房フードを再利用しつつ、新たなダクト経路を設計いたしました。限られたスペースを有効活用しながらも、排煙ファンをリニューアルすることで、排煙機能を大幅に向上。今後も快適かつ衛生的な調理環境を維持できるよう、最適なシステムを構築しています。</p>', '福岡県', '2020-08-21', 'published', 'TRIAL（スーパーセンター）の総菜厨房移設工事｜施工事例【株式会社野田】', '総菜部門の移設に伴い、既存の厨房フードを再利用しつつ、新たなダクト経路を設計いたしました。限られたスペースを有効活用しながらも、排煙ファンをリニューアルすることで、排煙機能を大幅に向上。今後も快適かつ衛生的な調理環境を…', '4668', '0', '2868', '2025-03-24 11:19:02', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('37', '福岡市中央区のラーメン店-厨房フード工事', '福岡市中央区のラーメン店-厨房フード工事', '<h3>施工内容</h3>\n<p>福岡市中央区にあるラーメン店にて、居抜き物件の厨房排気不足を解消するため、<strong>厨房フードのサイズや排気風量、給気経路の見直し</strong>を行いました。店内に熱気がこもりやすい状況を改善するため、既存フードやダクトを最大限に活用しながら、追加施工という形でコストを抑えつつも排気効率を大幅に向上。結果として、厨房環境の快適性と衛生面が向上し、従業員の作業効率とお客様の満足度向上にも貢献しています。</p>', '福岡市中央区', '2020-09-07', 'published', '福岡市中央区のラーメン店-厨房フード工事｜施工事例【株式会社野田】', '福岡市中央区にあるラーメン店にて、居抜き物件の厨房排気不足を解消するため、厨房フードのサイズや排気風量、給気経路の見直しを行いました。店内に熱気がこもりやすい状況を改善するため、既存フードやダクトを最大限に活用しながら…', '4672', '0', '2870', '2025-03-24 11:22:01', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('38', '佐賀県唐津市の食堂-厨房フード工事', '佐賀県唐津市の食堂-厨房フード工事', '<h3>施工内容</h3>\n<p>唐津の食堂にて、食器洗浄機用のフードおよび厨房排気フード、さらに給気工事を実施いたしました。効率的な排気と適切な給気を両立させることで、調理スペースの熱気や油煙をしっかりと排出し、厨房環境の快適性と衛生面を大幅に向上させています。</p>', '佐賀県唐津市', '2020-10-14', 'published', '佐賀県唐津市の食堂-厨房フード工事｜施工事例【株式会社野田】', '唐津の食堂にて、食器洗浄機用のフードおよび厨房排気フード、さらに給気工事を実施いたしました。効率的な排気と適切な給気を両立させることで、調理スペースの熱気や油煙をしっかりと排出し、厨房環境の快適性と衛生面を大幅に向上さ…', '4677', '0', '2878', '2025-03-24 11:25:46', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('39', '広島市西区のスタイリッシュな焼肉店ー排煙ダク', '広島市西区のスタイリッシュな焼肉店ー排煙ダクト工事', '<h3>施工内容</h3>\n<p>内装業者様からのご依頼を受け、打ち合わせから施工まで一貫して担当いたしました。7月にオープンしたこちらの焼肉店は、スタッフがお客様の目の前で焼き上げ、最高の状態で提供する新しいスタイルが魅力です。照明を抑え目にし、テーブル上をスポットライトで演出することで、料理により集中できる空間づくりを実現しています。今回は排煙ダクトだけでなく、店内の気流を考慮して給気設備も併せて設置することで、快適性と安全性の両立を図りました。</p>', '広島市西区', '2020-11-05', 'published', '広島市西区のスタイリッシュな焼肉店ー排煙ダクト工事｜施工事例【株式会社野田】', '内装業者様からのご依頼を受け、打ち合わせから施工まで一貫して担当いたしました。7月にオープンしたこちらの焼肉店は、スタッフがお客様の目の前で焼き上げ、最高の状態で提供する新しいスタイルが魅力です。照明を抑え目にし、テー…', '4682', '0', '2886', '2025-03-24 11:28:42', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('40', '福岡市中央区西中州の焼き鳥-厨房フード工事', '福岡市中央区西中州の焼き鳥-厨房フード工事', '<h3>施工内容</h3>\n<p>福岡市中央区西中洲に新たにオープンした焼鳥店にて、焼鳥専用フード「SKY」を導入しました。超省エネタイプのフードを採用することで、エアコン効率が格段に向上し、店内の快適性を高めています。従来のフードよりも排煙と冷房負荷のバランスを最適化する設計が特徴で、焼鳥調理時の煙を効率的に排出しながらも、冷房効果のロスを最小限に抑えることが可能です。今回の施工によって、スタッフとお客様の双方が過ごしやすい環境が整い、焼鳥の美味しさをより一層引き立てる店舗づくりに貢献いたしました。</p>', '福岡市中央区', '2020-11-19', 'published', '福岡市中央区西中州の焼き鳥-厨房フード工事｜施工事例【株式会社野田】', '福岡市中央区西中洲に新たにオープンした焼鳥店にて、焼鳥専用フード「SKY」を導入しました。超省エネタイプのフードを採用することで、エアコン効率が格段に向上し、店内の快適性を高めています。従来のフードよりも排煙と冷房負荷…', '4687', '0', '2895', '2025-03-24 11:33:12', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('41', '福岡市東区箱崎駅前の食堂-厨房フード工事', '福岡市東区箱崎駅前の食堂-厨房フード工事', '<h3>施工内容</h3>\n<p>福岡市東区箱崎駅前に新たにオープンする食堂にて、最新のカウンターフードを導入しました。排煙効率が非常に高く、焼き台の設置場所を選ばないという特徴を持ち、一般的なフードに比べてエアコンの効きも大幅に向上しています。さらに、併せて厨房フードの施工も行い、効率的かつ快適な調理環境を実現しました。</p>', '福岡市東区', '2021-01-12', 'published', '福岡市東区箱崎駅前の食堂-厨房フード工事｜施工事例【株式会社野田】', '福岡市東区箱崎駅前に新たにオープンする食堂にて、最新のカウンターフードを導入しました。排煙効率が非常に高く、焼き台の設置場所を選ばないという特徴を持ち、一般的なフードに比べてエアコンの効きも大幅に向上しています。さらに…', '4692', '0', '2909', '2025-03-24 11:37:08', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('42', '福岡県飯塚市の焼肉店-ファン工事', '福岡県飯塚市の焼肉店-ファン工事', '<h3>施工内容</h3>\n<p>福岡県飯塚市にある焼肉店の老朽化したファン交換工事を行いました。二階建てハイツの1階に位置するため、近隣住民への煙対策として排気口を屋根上まで立ち上げる設計を採用。長年培ってきた施工ノウハウを活かし、1日で工事を完了させることができました。近隣への影響を最小限に抑えながらも、安全性と排煙効率をしっかり確保した事例となっています。</p>', '福岡県飯塚市', '2021-02-02', 'published', '福岡県飯塚市の焼肉店-ファン工事｜施工事例【株式会社野田】', '福岡県飯塚市にある焼肉店の老朽化したファン交換工事を行いました。二階建てハイツの1階に位置するため、近隣住民への煙対策として排気口を屋根上まで立ち上げる設計を採用。長年培ってきた施工ノウハウを活かし、1日で工事を完了さ…', '4697', '0', '2913', '2025-03-24 11:39:53', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('43', '福岡市有名ラーメン店-【博多一双様】厨房ダクト', '福岡市有名ラーメン店 【博多一双様】厨房ダクト換気施工', '<h3>施工内容</h3>\n<p>福岡の有名豚骨ラーメン店「博多一双 祇園店」にて、店内の暑さや厨房ダクトの吸い込み不良を改善するための工事を行いました。事前の風速・風量測定の結果、既存ファンの劣化による能力低下が原因と判明。そこで、店内厨房フードに合った<strong>適正風速・適正風量</strong>を新たに設計し、排煙ファンを交換しました。工事完了後は、厨房内の排煙性能が大幅に向上し、店内環境が大きく改善されています。</p>', '福岡市博多区', '2021-02-26', 'published', '福岡市有名ラーメン店 【博多一双様】厨房ダクト換気施工｜施工事例【株式会社野田】', '福岡の有名豚骨ラーメン店「博多一双祇園店」にて、店内の暑さや厨房ダクトの吸い込み不良を改善するための工事を行いました。事前の風速・風量測定の結果、既存ファンの劣化による能力低下が原因と判明。そこで、店内厨房フードに合っ…', '4701', '0', '2925', '2025-03-24 11:43:27', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('44', '福岡市早良区西新の焼き鳥店-ダクト工事', '福岡市早良区西新の焼き鳥店-ダクト工事', '<h3>施工内容</h3>\n<p>居抜き店舗の既存ダクトをそのまま利用していたところ、排気不良や店内の煙こもり、エアコンの効きの悪さなどのトラブルが発生していました。原因を調査した結果、ダクトの設計に問題があり、気流の向き・風量・風速を再検討。排気ファンを新たに導入するとともに、客席の煙対策として設置されていた換気扇を給気口に変更し、店内の気流を安定させました。これにより、効率的な排煙と冷暖房効果の向上を同時に実現しています。</p>', '福岡市早良区', '2021-03-17', 'published', '福岡市早良区西新の焼き鳥店-ダクト工事｜施工事例【株式会社野田】', '居抜き店舗の既存ダクトをそのまま利用していたところ、排気不良や店内の煙こもり、エアコンの効きの悪さなどのトラブルが発生していました。原因を調査した結果、ダクトの設計に問題があり、気流の向き・風量・風速を再検討。排気ファ…', '4705', '0', '2928', '2025-03-24 11:47:27', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('45', '福岡県大川市の養護施設-厨房排気工事', '福岡県大川市の養護施設-厨房排気工事', '<h3>施工内容</h3>\n<p>福岡県大川市にある介護施設の調理場排気に関して、近隣住民から「騒音がうるさい」「臭いが気になる」というクレームが寄せられていました。そこで、壁面に設置していたファンを屋根上へ移設し、騒音を軽減。さらに、排気の吹出し方向を建物の反対側に向けることで、臭いの拡散を最小限に抑える対策を実施しました。<br>当社ならではのスピード施工により、1日で工事を完了。近隣とのトラブルを回避し、施設利用者やスタッフの皆様が安心して過ごせる環境づくりに貢献しています。</p>', '福岡県大川市', '2021-04-14', 'published', '福岡県大川市の養護施設-厨房排気工事｜施工事例【株式会社野田】', '福岡県大川市にある介護施設の調理場排気に関して、近隣住民から「騒音がうるさい」「臭いが気になる」というクレームが寄せられていました。そこで、壁面に設置していたファンを屋根上へ移設し、騒音を軽減。さらに、排気の吹出し方向…', '4710', '0', '2936', '2025-03-24 11:51:22', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('46', '北九州市八幡西区の人気焼肉店-クリアフード工事', '北九州市八幡西区の人気焼肉店-クリアフード工事', '<h3>施工内容</h3>\n<p>黒崎にある味とコスパで人気の焼肉店にて、店内に煙が充満しやすい・エアコンの効きが悪い・吸い込み器具が大きくてお客様同士の視界を妨げる・近隣から排煙に対するクレームがある、といった4つの課題を解決するための改修工事を行いました。調査の結果、既存の大きな吸い込み口が基準設置条件を守っておらず、煙を十分に処理できていないことが判明。そこで、当社のクリアフードを導入していただくことで「店内に煙が充満する」「エアコンの効きが悪い」「視界を妨げる」といった問題を解消し、外部ダクトを屋根上まで立ち上げることで、近隣からのクレームにも対応しました。今回の施工により、店内環境と近隣との関係を同時に改善することができました。</p>', '北九州市八幡西区', '2021-05-11', 'published', '北九州市八幡西区の人気焼肉店-クリアフード工事｜施工事例【株式会社野田】', '黒崎にある味とコスパで人気の焼肉店にて、店内に煙が充満しやすい・エアコンの効きが悪い・吸い込み器具が大きくてお客様同士の視界を妨げる・近隣から排煙に対するクレームがある、といった4つの課題を解決するための改修工事を行い…', '4712', '0', '2941', '2025-03-24 11:53:55', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('47', '福岡県北九州市門司区の新しいパン屋さん-厨房フ', '福岡県北九州市門司区の新しいパン屋さん-厨房フード工事', '<h3>施工内容</h3>\n<p>門司に新たにオープン予定のベーカリーにて、ユニークな丸型フードやデザイン性を重視した変形フードを活用し、こだわりの調理パンやサンドイッチを提供できる店内空間を演出しました。排気経路には網フィルターを設置し、クリーンな排気を実現するよう配慮。排気ファンは複数台に分割することで、万が一の故障リスクを分散しながら効率的な排気機能を維持しています。これにより、デザイン性と機能性を両立した快適なベーカリー空間を創り上げました。</p>', '北九州市門司区', '2021-05-26', 'published', '福岡県北九州市門司区の新しいパン屋さん-厨房フード工事｜施工事例【株式会社野田】', '門司に新たにオープン予定のベーカリーにて、ユニークな丸型フードやデザイン性を重視した変形フードを活用し、こだわりの調理パンやサンドイッチを提供できる店内空間を演出しました。排気経路には網フィルターを設置し、クリーンな排…', '4717', '0', '2949', '2025-03-24 11:57:24', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('48', '広島県の老舗有名焼肉店-厨房ダクト・排煙ファン', '広島県の老舗有名焼肉店-厨房ダクト・排煙ファン工事', '<h3>施工内容</h3>\n<p>15年以上使用されていたダクトおよび排煙ファンの老朽化と、長年の使用による油分の付着により、排気能力が低下していました。これまでは定期的な清掃で対応されていましたが、劣化が進んでいることから、ダクトと排煙ファンを一新。新たな設備に交換することで、厨房の排煙効率と衛生面を大幅に改善し、より快適な調理環境を整えることができました。</p>', '広島県', '2021-06-21', 'published', '広島県の老舗有名焼肉店-厨房ダクト・排煙ファン工事｜施工事例【株式会社野田】', '15年以上使用されていたダクトおよび排煙ファンの老朽化と、長年の使用による油分の付着により、排気能力が低下していました。これまでは定期的な清掃で対応されていましたが、劣化が進んでいることから、ダクトと排煙ファンを一新。…', '4722', '0', '2957', '2025-03-24 12:00:37', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('49', '福岡県宗像市の新しい鶏焼肉「ｔａｋｕ様」クリ', '福岡県宗像市の新しい鶏焼肉「ＴＡＫＵ様」クリアフード工事', '<h3>施工内容</h3>\n<p>宗像に新しくオープンする鶏焼肉「TAKU」にて、当社のクリアフードを導入しました。テーブルで鶏肉を焼きながら楽しむスタイルに合わせ、ダクト経路を分割し、小型ファンを複数台配置することで、故障リスクを最小限に抑える独自設計を採用しています。煙をしっかり排気しながらも快適な空間を維持できるよう、細部までこだわった施工を行いました。</p>', '福岡県宗像市', '2021-07-13', 'published', '福岡県宗像市の新しい鶏焼肉「ＴＡＫＵ様」クリアフード工事｜施工事例【株式会社野田】', '宗像に新しくオープンする鶏焼肉「TAKU」にて、当社のクリアフードを導入しました。テーブルで鶏肉を焼きながら楽しむスタイルに合わせ、ダクト経路を分割し、小型ファンを複数台配置することで、故障リスクを最小限に抑える独自設…', '4727', '0', '2965', '2025-03-24 12:03:18', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('50', '福岡県福津市の新規開業焼き鳥店-厨房設備工事', '福岡県福津市の新規開業焼き鳥店-厨房設備工事', '<h3>施工内容</h3>\n<p>福岡県福津市に新たに開業する焼鳥店にて、厨房焼き場のフード施工を担当いたしました。排気口まで距離がある現場条件を考慮し、自由な場所に設置できるシロッコファンを採用。排気口は屋根上へ立ち上げる設計とし、周囲への煙被害を防止することで近隣対策も万全です。今後も安全かつ快適な調理環境を維持し、お客様に美味しい焼鳥を提供できるようサポートいたします。</p>', '福岡県福津市', '2021-08-26', 'published', '福岡県福津市の新規開業焼き鳥店-厨房設備工事｜施工事例【株式会社野田】', '福岡県福津市に新たに開業する焼鳥店にて、厨房焼き場のフード施工を担当いたしました。排気口まで距離がある現場条件を考慮し、自由な場所に設置できるシロッコファンを採用。排気口は屋根上へ立ち上げる設計とし、周囲への煙被害を防…', '4732', '0', '2973', '2025-03-24 12:06:12', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('51', '福岡市博多区中洲川端の新規開店焼き鳥店-焼き鳥', '福岡市博多区中洲川端の新規開店焼き鳥店-焼き鳥専用フード工事', '<h3>施工内容</h3>\n<p><strong>福岡市博多区中州川端に新規オープンする焼鳥店</strong>にて、空調ダクト工事とともに、当社の最新焼き鳥専用フード（SKYフード）を導入いただきました。従来の厨房フードに比べて非常にコンパクトで、対面接客に最適なカウンター式排煙システムを採用。ピンポイントで煙を排気できるため、冷暖房効率が向上し、手元で煙を吸い込まない健康的な調理環境を実現しています。さらに、小さなファンで対応できる設計のため、電気代の節約などさまざまなメリットも期待できます。新しい焼鳥店のオープンに向け、より快適かつ魅力的な空間づくりをサポートいたしました。</p>', '福岡市博多区', '2021-09-22', 'published', '福岡市博多区中洲川端の新規開店焼き鳥店-焼き鳥専用フード工事｜施工事例【株式会社野田】', '福岡市博多区中州川端に新規オープンする焼鳥店にて、空調ダクト工事とともに、当社の最新焼き鳥専用フード（SKYフード）を導入いただきました。従来の厨房フードに比べて非常にコンパクトで、対面接客に最適なカウンター式排煙シス…', '4737', '0', '2985', '2025-03-24 12:08:43', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('52', '福岡市博多区春吉-博多水炊き「鳥千代様」厨房フ', '福岡市博多区春吉-博多水炊き「鳥千代様」厨房フード工事', '<h3>施工内容</h3>\n<p>福岡市博多区春吉に新規オープンする博多水炊き「鳥千代」様より、厨房フード工事をご依頼いただきました。排気音をできるだけ抑えるため、ダクトとファンの接続部にBOXを設置し、店内の騒音対策に配慮した設計となっています。これにより、調理環境の快適性とお客様が過ごしやすい空間づくりの両立を実現しました。</p>', '福岡市博多区', '2021-10-15', 'published', '福岡市博多区春吉-博多水炊き「鳥千代様」厨房フード工事｜施工事例【株式会社野田】', '福岡市博多区春吉に新規オープンする博多水炊き「鳥千代」様より、厨房フード工事をご依頼いただきました。排気音をできるだけ抑えるため、ダクトとファンの接続部にBOXを設置し、店内の騒音対策に配慮した設計となっています。これ…', '4740', '0', '2993', '2025-03-24 12:11:38', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('53', '福岡県古賀市の新規居酒屋-厨房フード', '福岡県古賀市の新規居酒屋-厨房フード', '<h3>施工内容</h3>\n<p>古賀市に開店予定のお店にて、熱源が多い厨房に対応するため、幅3,500mmのフードを2分割して作成・設置しました。排煙の偏りを防ぐため、3カ所に排煙口を設けることで効率的な換気を実現。さらに、排煙ファンとの距離が近いことから、騒音対策としてファン接続部をBOX施工し、周囲への騒音を軽減しています。</p>', '福岡県古賀市', '2021-11-12', 'published', '福岡県古賀市の新規居酒屋-厨房フード｜施工事例【株式会社野田】', '古賀市に開店予定のお店にて、熱源が多い厨房に対応するため、幅3,500mmのフードを2分割して作成・設置しました。排煙の偏りを防ぐため、3カ所に排煙口を設けることで効率的な換気を実現。さらに、排煙ファンとの距離が近いこ…', '4745', '0', '2996', '2025-03-24 12:14:29', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('54', '福岡県飯塚市-かほ兵衛の台所フードコート2店舗', '福岡県飯塚市-かほ兵衛の台所フードコート2店舗-厨房フード工事', '<h3>施工内容</h3>\n<p>「KAHO TERRAS」内にある「かほ兵衛の台所フードコート」に新たにオープンした2店舗、<strong>山賊からあげ様</strong>と<strong>牛牛うどん様</strong>の厨房排煙フードを施工させていただきました。どちらも地元で有名な「本家山賊鍋」様が手掛ける新業態で、揚げたての唐揚げや人気の肉うどんを提供しています。<br>フードコート内の限られたスペースに対応するため、排気音を極力抑え、騒音を軽減する設計を採用。接客動線を確保しながらも効率的な排気システムを両立し、快適な環境でお客様に美味しいメニューを楽しんでいただけるよう配慮いたしました。</p>', '福岡県飯塚市', '2021-11-25', 'published', '福岡県飯塚市-かほ兵衛の台所フードコート2店舗-厨房フード工事｜施工事例【株式会社野田】', '「KAHOTERRAS」内にある「かほ兵衛の台所フードコート」に新たにオープンした2店舗、山賊からあげ様と牛牛うどん様の厨房排煙フードを施工させていただきました。どちらも地元で有名な「本家山賊鍋」様が手掛ける新業態で、…', '4747', '0', '3002', '2025-03-24 12:17:43', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('55', '福岡市中央区高砂に新規開店の焼肉店　上引きフ', '福岡市中央区高砂に新規開店の焼肉店　上引きフード工事', '<h3>施工内容</h3>\n<p>福岡県福岡市中央区高砂に新たにオープンする焼肉店にて、客席排煙設備・客席換気設備・調理場排煙フード一式の施工を担当いたしました。<br>とくに厨房フードについては、通常の施工を行うと冷蔵庫に隣接するため、上部に熱がこもる問題が発生する恐れがありました。そこで、冷蔵庫側のフード面をメッシュ加工にすることで熱ごもりを解消し、効率的な排気を実現。<br>このように、弊社独自のノウハウを活かして、お客様の現場条件に合わせた最適なご提案・施工を行っています。</p>', '福岡市中央区', '2021-12-17', 'published', '福岡市中央区高砂に新規開店の焼肉店　上引きフード工事｜施工事例【株式会社野田】', '福岡県福岡市中央区高砂に新たにオープンする焼肉店にて、客席排煙設備・客席換気設備・調理場排煙フード一式の施工を担当いたしました。とくに厨房フードについては、通常の施工を行うと冷蔵庫に隣接するため、上部に熱がこもる問題が…', '4752', '0', '3010', '2025-03-24 12:43:17', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('56', '福岡県北九州市小倉に開店予定の飲食店　ダクト', '福岡県北九州市小倉に開店予定の飲食店　ダクト工事', '<h3>施工内容</h3>\n<p>福岡県北九州市小倉に新たに開店予定の飲食店で、ダクト工事を担当しています。天井造作前の段階でダクトを天井内に収めるための施工を行い、断熱処理もしっかり施すことで防火対策を万全にしています。さらに、天井内に排煙ファンを設置するため、厨房排煙専用のストレートファンを採用。上部抜きの排煙フードも設置予定で、通常よりも各段に優れた排煙効率を実現する計画です。</p>', '北九州市', '2022-02-04', 'published', '福岡県北九州市小倉に開店予定の飲食店　ダクト工事｜施工事例【株式会社野田】', '福岡県北九州市小倉に新たに開店予定の飲食店で、ダクト工事を担当しています。天井造作前の段階でダクトを天井内に収めるための施工を行い、断熱処理もしっかり施すことで防火対策を万全にしています。さらに、天井内に排煙ファンを設…', '4757', '1', '3026', '2025-03-24 12:45:45', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('57', '広島県焼肉店火災後の工事', '広島県焼肉店火災後の工事', '<h3>施工内容</h3>\n<p>広島にある焼肉店にて、日々のメンテナンス不足が原因でダクト内火災が発生しました。被害箇所の既存ダクトを撤去し、新しいダクトへ付け替える施工を実施。ダクト火災は、フィルター清掃や分解清掃といった日々のメンテナンスを適切に行うことで、ほぼ防ぐことが可能です。今回の工事後は、再発防止のためにメンテナンス方法を詳しく記載したマニュアルをお渡しし、安全な運営をサポートしています。</p>', '広島県', '2022-02-25', 'published', '広島県焼肉店火災後の工事｜施工事例【株式会社野田】', '広島にある焼肉店にて、日々のメンテナンス不足が原因でダクト内火災が発生しました。被害箇所の既存ダクトを撤去し、新しいダクトへ付け替える施工を実施。ダクト火災は、フィルター清掃や分解清掃といった日々のメンテナンスを適切に…', '4760', '0', '3028', '2025-03-24 12:47:54', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('58', '福岡市中央区高砂の有名鶏焼肉店-客席排煙システ', '福岡市中央区高砂の有名鶏焼肉店-客席排煙システム・客席換気工事', '<h3>施工内容</h3>\n<p>福岡市中央区高砂にある有名鶏焼肉店にて、客席排煙システムと客席換気工事を行いました。<br>一般的な焼肉店で用いられる上引きフードを採用し、各テーブルごとに排煙を行うことで、煙や臭いが効率的に排出されるように設計。また、給気には天井内チャンバーを使用し、点検口部分を吹き出し口として活用することで店内全体の換気を実現しています。<br>さらに、吹き出し口にはノンドラフト仕様を採用し、お客様に直接風が当たらないよう配慮。快適な空間づくりと効果的な排煙を両立させる施工事例となりました。</p>', '福岡市中央区', '2022-03-24', 'published', '福岡市中央区高砂の有名鶏焼肉店-客席排煙システム・客席換気工事｜施工事例【株式会社野田】', '福岡市中央区高砂にある有名鶏焼肉店にて、客席排煙システムと客席換気工事を行いました。一般的な焼肉店で用いられる上引きフードを採用し、各テーブルごとに排煙を行うことで、煙や臭いが効率的に排出されるように設計。また、給気に…', '4761', '0', '3032', '2025-03-24 12:50:21', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('59', '福岡県糸島市志摩芥屋のコンテナカフェ-厨房フー', '福岡県糸島市志摩芥屋のコンテナカフェ-厨房フード工事', '<h3>施工内容</h3>\n<p>福岡県糸島市の芥屋海水浴場に隣接するコンテナカフェにて、厨房フードの工事を行いました。海辺の環境ゆえ周辺に虫が多く、外部のウェザーカバーには通常より細かい網目の製品を採用。さらに、油汚れなどによる目詰まりを防ぐため、<strong>取り外して洗浄できる構造</strong>に加工し、メンテナンス性を高めています。海水浴客が多く訪れるシーズンにも快適に営業できるよう、細部まで配慮した施工事例となりました。</p>', '福岡県糸島市', '2022-04-18', 'published', '福岡県糸島市志摩芥屋のコンテナカフェ-厨房フード工事｜施工事例【株式会社野田】', '福岡県糸島市の芥屋海水浴場に隣接するコンテナカフェにて、厨房フードの工事を行いました。海辺の環境ゆえ周辺に虫が多く、外部のウェザーカバーには通常より細かい網目の製品を採用。さらに、油汚れなどによる目詰まりを防ぐため、取…', '4766', '0', '3040', '2025-03-24 12:52:39', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('60', '有名博多ラーメン店「一双」本店-排煙ダクト立ち', '有名博多ラーメン店「一双」本店 排煙ダクト立ち上げ工事', '<h3>施工内容</h3>\n<p>近隣からの臭いに関するクレームを解消するため、従来は店舗正面へ直接排気していた構造を、ビル屋上までダクトを立ち上げる方式に変更しました。これにより、周辺道路への臭いの拡散を防止し、快適な街並みづくりに貢献。また、定休日がない繁盛店のため、夜間に施工を行い、営業への影響を最小限に抑えました。</p>', '福岡市博多区', '2022-05-20', 'published', '有名博多ラーメン店「一双」本店 排煙ダクト立ち上げ工事｜施工事例【株式会社野田】', '近隣からの臭いに関するクレームを解消するため、従来は店舗正面へ直接排気していた構造を、ビル屋上までダクトを立ち上げる方式に変更しました。これにより、周辺道路への臭いの拡散を防止し、快適な街並みづくりに貢献。また、定休日…', '4769', '0', '3046', '2025-03-24 12:56:16', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('61', '北九州市黒崎の人気焼肉店　「寿楽園様」　移転', '北九州市黒崎の人気焼肉店　「寿楽園様」　移転工事', '<h3>施工内容</h3>\n<p>大型店舗への移転に伴い、外部ダクトの立ち上げ（高所作業）から、既存排煙フードの移設工事、店内ダクト工事まで一括して担当させていただきました。延べ6日間という短い施工期間で完了したのは、全体工程を一括管理することでスムーズかつコストを抑えた対応が可能だったためです。移転後もお客様に快適な焼肉環境を提供できるよう、安全・効率的な排煙設備を整備いたしました。</p>', '北九州市八幡西区', '2022-06-13', 'published', '北九州市黒崎の人気焼肉店　「寿楽園様」　移転工事｜施工事例【株式会社野田】', '大型店舗への移転に伴い、外部ダクトの立ち上げ（高所作業）から、既存排煙フードの移設工事、店内ダクト工事まで一括して担当させていただきました。延べ6日間という短い施工期間で完了したのは、全体工程を一括管理することでスムー…', '4773', '0', '3053', '2025-03-24 12:59:08', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('62', '熊本市の焼鳥店　焼鳥専用フード工事', '熊本市の焼鳥店　焼鳥専用フード工事', '<h3>施工内容</h3>\n<p>従来のフードに比べて省スペース化を実現し、作業スペースの確保と排気効率の向上を両立。また、電気集塵機により排煙中の油分をしっかり除去し、近隣への煙トラブルを未然に防ぐ対策も万全です。焼鳥調理に最適化されたシステムで、スタッフの作業効率とお客様の快適性が一段と高まりました。</p>', '熊本県熊本市', '2022-07-13', 'published', '熊本市の焼鳥店　焼鳥専用フード工事｜施工事例【株式会社野田】', '従来のフードに比べて省スペース化を実現し、作業スペースの確保と排気効率の向上を両立。また、電気集塵機により排煙中の油分をしっかり除去し、近隣への煙トラブルを未然に防ぐ対策も万全です。焼鳥調理に最適化されたシステムで、ス…', '4778', '0', '3062', '2025-03-24 13:02:23', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('63', '北九州市小倉に新規開店の飲食店　厨房フード工', '北九州市小倉に新規開店の飲食店　厨房フード工事', '<h3>施工内容</h3>\n<p><strong>北九州市小倉の飲食店様</strong>よりご依頼いただき、オーダーメイドの厨房フードを製作・設置しました。限られたスペースを最大限に活用し、外部にはスリムタイプのカバーを採用することで、外観の美観にも配慮したすっきりとした仕上がりを実現しています。<br>当社では、少し特殊なご要望にも柔軟に対応できるよう、最適なプランをご提案し、お客様の理想を形にするお手伝いをいたします。</p>', '北九州市', '2022-07-22', 'published', '北九州市小倉に新規開店の飲食店　厨房フード工事｜施工事例【株式会社野田】', '北九州市小倉の飲食店様よりご依頼いただき、オーダーメイドの厨房フードを製作・設置しました。限られたスペースを最大限に活用し、外部にはスリムタイプのカバーを採用することで、外観の美観にも配慮したすっきりとした仕上がりを実…', '4783', '1', '3070', '2025-03-24 13:04:49', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('64', '福岡県田川市の新規開店のコーヒーショップ　排', '福岡県田川市の新規開店のコーヒーショップ　排気ダクト工事', '<h3>施工内容</h3>\n<p><strong>福岡県田川市に新たにオープンするコーヒーショップ</strong>にて、焙煎機の設置と排気ダクト工事を担当しました。焙煎時に発生するチャフ（焙煎ゴミ）がダクト内部に付着しやすいため、将来的な清掃がスムーズに行えるよう、メンテナンス性を考慮した経路設計を採用。コーヒー店の設備施工や排気ダクトに関するご相談は、ぜひ当社にお任せください。</p>', '福岡県田川市', '2022-09-06', 'published', '福岡県田川市の新規開店のコーヒーショップ　排気ダクト工事｜施工事例【株式会社野田】', '福岡県田川市に新たにオープンするコーヒーショップにて、焙煎機の設置と排気ダクト工事を担当しました。焙煎時に発生するチャフ（焙煎ゴミ）がダクト内部に付着しやすいため、将来的な清掃がスムーズに行えるよう、メンテナンス性を考…', '4786', '0', '3076', '2025-03-24 13:07:22', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('65', '広島県の新規開店予定の大型焼肉店-床下ダクト工', '広島県の新規開店予定の大型焼肉店-床下ダクト工事', '<h3>施工内容</h3>\n<p>広島県東広島市西条に新しく開店予定の大型焼肉店様からのご依頼です。<br>今回はロースター設置前の床下ダクト及び天井内換気の仕込み工事です。<br>防火対策のためしっかりと断熱処理をし、ロースター接続部分に自社設計のオリジナルBOXを使用することで抵抗値の軽減を実現しております。<br>これにより効率良く排煙出来るようになりますので、煙の臭い対策などにもつながります。</p>', '広島県東広島市', '2022-09-15', 'published', '広島県の新規開店予定の大型焼肉店-床下ダクト工事｜施工事例【株式会社野田】', '広島県東広島市西条に新しく開店予定の大型焼肉店様からのご依頼です。今回はロースター設置前の床下ダクト及び天井内換気の仕込み工事です。防火対策のためしっかりと断熱処理をし、ロースター接続部分に自社設計のオリジナルBOXを…', '4791', '0', '3084', '2025-03-24 13:10:04', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('66', '福岡市西区姪浜に新規開店予定の焼鳥店-ダクト立', '福岡市西区姪浜に新規開店予定の焼鳥店-ダクト立ち上げ工事', '<h3>施工内容</h3>\n<p><strong>福岡市西区姪浜に開店予定の焼鳥屋さん</strong>にて、小料理屋の居抜き店舗を活用し、<strong>調理場フードのサイズ変更</strong>や排煙設備の容量変更を行いました。上層階が住居、隣が病院という立地条件から、<strong>屋上までダクトを立ち上げて排煙</strong>するように設計し、周囲への煙対策を徹底。さらに、一部の既存ダクトやグリスフィルターを再利用することで、<strong>コストを抑えながら</strong>快適で安全な調理環境を実現しています。</p>', '福岡市西区', '2022-10-21', 'published', '福岡市西区姪浜に新規開店予定の焼鳥店-ダクト立ち上げ工事｜施工事例【株式会社野田】', '福岡市西区姪浜に開店予定の焼鳥屋さんにて、小料理屋の居抜き店舗を活用し、調理場フードのサイズ変更や排煙設備の容量変更を行いました。上層階が住居、隣が病院という立地条件から、屋上までダクトを立ち上げて排煙するように設計し…', '4795', '0', '3092', '2025-03-24 13:12:39', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('67', '宮崎市中心部にあるステーキ店岡崎牧場様の業態', '宮崎市中心部にあるステーキ店岡崎牧場様の業態変更工事', '<h3>施工内容</h3>\n<p>ステーキ店から焼肉店へリニューアルするにあたり、ダクト工事を担当させていただきました。既存の内装との調和を図るため、ダクトを塗装して違和感のない仕上がりに。また、排気容量の増加に合わせて給気箇所を追加し、スムーズな換気の流れを実現しています。<br>当社では今回のようなステーキ店から焼肉店への業態変更はもちろん、居酒屋から焼肉店へのリニューアルなど、さまざまなケースに柔軟に対応いたします。ぜひ一度ご相談ください。</p>', '宮崎県宮崎市', '2022-11-22', 'published', '宮崎市中心部にあるステーキ店岡崎牧場様の業態変更工事｜施工事例【株式会社野田】', 'ステーキ店から焼肉店へリニューアルするにあたり、ダクト工事を担当させていただきました。既存の内装との調和を図るため、ダクトを塗装して違和感のない仕上がりに。また、排気容量の増加に合わせて給気箇所を追加し、スムーズな換気…', '4799', '0', '3100', '2025-03-24 13:15:56', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('68', '福岡市東区多の津のアクリル加工工場-排気ダクト', '福岡市東区多の津のアクリル加工工場-排気ダクト工事', '<h3>施工内容</h3>\n<p>福岡市東区多の津にあるアクリル加工工場にて、機械用排気ダクト工事を行いました。支給品のファンを使用し、壁沿いにダクトを設置することで作業スペースを確保しつつ、一カ所からまとめて屋外へ排気するように設計。効率的な排気システムと動線の両立を実現しています。</p>', '福岡市東区', '2022-12-06', 'published', '福岡市東区多の津のアクリル加工工場-排気ダクト工事｜施工事例【株式会社野田】', '福岡市東区多の津にあるアクリル加工工場にて、機械用排気ダクト工事を行いました。支給品のファンを使用し、壁沿いにダクトを設置することで作業スペースを確保しつつ、一カ所からまとめて屋外へ排気するように設計。効率的な排気シス…', '4804', '0', '3108', '2025-03-24 13:18:25', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('69', '福岡市中央区有名食堂グループ本店-厨房ダクト工', '福岡市中央区有名食堂グループ本店-厨房ダクト工事', '<h3>施工内容</h3>\n<p><strong>福岡県福岡市中央区に本店を構える有名食堂グループのセントラルキッチン兼店舗</strong>において、厨房ダクト工事を担当しました。事前に綿密な打ち合わせを行い、仕込み動線や調理工程に合わせてダクト経路を効率よく配置。お客様のご希望のレイアウトに沿った設備をご提供でき、調理作業のスムーズ化と快適な厨房環境づくりに貢献しています。</p>', '福岡市中央区', '2023-01-11', 'published', '福岡市中央区有名食堂グループ本店-厨房ダクト工事｜施工事例【株式会社野田】', '福岡県福岡市中央区に本店を構える有名食堂グループのセントラルキッチン兼店舗において、厨房ダクト工事を担当しました。事前に綿密な打ち合わせを行い、仕込み動線や調理工程に合わせてダクト経路を効率よく配置。お客様のご希望のレ…', '4809', '0', '3116', '2025-03-24 13:21:02', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('70', '佐賀県伊万里市新規開店カフェ-ダクト工事　', '佐賀県伊万里市新規開店カフェ-ダクト工事　', '<h3>施工内容</h3>\n<p><strong>佐賀県伊万里市に新たにオープンする、コーヒー豆焙煎機を併設したカフェ</strong>にて、天井内ダクト工事を施工しました。強制給気側には<strong>消音タイプのダクト</strong>を使用し、排気側には<strong>断熱処理</strong>を施すことで防火対策を強化。また、<strong>給気開口面積を大きめに確保</strong>することで、風速を抑え、店内にやわらかな風が流れるよう設計しています。焙煎機が稼働するカフェにおいても、快適な空間づくりと安全性を両立した施工事例となりました。</p>', '佐賀県伊万里市', '2023-02-01', 'published', '佐賀県伊万里市新規開店カフェ-ダクト工事　｜施工事例【株式会社野田】', '佐賀県伊万里市に新たにオープンする、コーヒー豆焙煎機を併設したカフェにて、天井内ダクト工事を施工しました。強制給気側には消音タイプのダクトを使用し、排気側には断熱処理を施すことで防火対策を強化。また、給気開口面積を大き…', '4814', '0', '3124', '2025-03-24 13:24:15', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('71', '福岡市中央区薬院「福岡春巻き-ぶる様」厨房フー', '福岡市中央区薬院「福岡春巻き ぶる様」厨房フード工事', '<h3>施工内容</h3>\n<p><strong>福岡市中央区 薬院大通駅近くの「福岡春巻き ぶる」様</strong>より、調理場の油煙が上手く排気されないというお悩みでご相談をいただきました。調査の結果、既存フードの形状が浅すぎて機能を十分に発揮できていないこと、そして排煙ファンの容量不足が原因であることが判明。そこで、フードを再設計・作り替えし、基準計算式に基づいた適切な容量の排煙ファンへ交換しました。<br>さらに、ダクト経路の一部をフレキシブルダクトからスパイラルダクトに変更することで、排気効率を大幅に向上。油煙や臭いが溜まりにくい、快適な調理環境を実現しています。油煙排気に関するお困りごとは、ぜひ当社にご相談ください。</p>', '福岡市中央区', '2023-03-09', 'published', '福岡市中央区薬院「福岡春巻き ぶる様」厨房フード工事｜施工事例【株式会社野田】', '福岡市中央区薬院大通駅近くの「福岡春巻きぶる」様より、調理場の油煙が上手く排気されないというお悩みでご相談をいただきました。調査の結果、既存フードの形状が浅すぎて機能を十分に発揮できていないこと、そして排煙ファンの容量…', '4819', '0', '3137', '2025-03-24 13:26:58', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('72', '広島県尾道市「中華そば永潤様」厨房フード工事', '広島県尾道市「中華そば永潤様」厨房フード工事', '<h3>施工内容</h3>\n<p><strong>尾道で大人気の「中華そば 永潤」様</strong>が移転に伴い、<strong>厨房排煙工事</strong>のご依頼をいただきました。当社オリジナルの<strong>ラーメン店専用フード</strong>と、基準計算式に基づく風量計算によって、効率的かつ安定した排気システムを実現。絶品の尾道ラーメンをさらに美味しく、快適な店内でお召し上がりいただけるようサポートいたしました。<br>ぜひ、行列ができる「中華そば 永潤」様の新店舗へ足を運んでみてください。</p>', '広島県尾道市', '2023-04-07', 'published', '広島県尾道市「中華そば永潤様」厨房フード工事｜施工事例【株式会社野田】', '尾道で大人気の「中華そば永潤」様が移転に伴い、厨房排煙工事のご依頼をいただきました。当社オリジナルのラーメン店専用フードと、基準計算式に基づく風量計算によって、効率的かつ安定した排気システムを実現。絶品の尾道ラーメンを…', '4824', '0', '3140', '2025-03-24 13:29:26', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('73', '北九州市黒崎「炭火焼肉-八輪-様」　移転に伴う設', '北九州市黒崎「炭火焼肉 八輪 様」　移転に伴う設備工事', '<h3>施工内容</h3>\n<p><strong>黒崎駅近くに移転リニューアルオープンする「炭火焼肉 八輪」様</strong>では、店舗規模の拡大に伴い、既存の上引きフード6台を移設すると同時に、新たに6台を追加設置する工事を行いました。上階にはオフィスが入居しているため、屋上まで排煙ダクトを立ち上げることで煙対策を万全にし、排気量の増加に合わせて自然吸気の追加工事も実施。これにより、店内の空気の流れをスムーズに保ち、快適な焼肉環境を実現しています。</p>', '北九州市八幡西区', '2023-04-24', 'published', '北九州市黒崎「炭火焼肉 八輪 様」　移転に伴う設備工事｜施工事例【株式会社野田】', '黒崎駅近くに移転リニューアルオープンする「炭火焼肉八輪」様では、店舗規模の拡大に伴い、既存の上引きフード6台を移設すると同時に、新たに6台を追加設置する工事を行いました。上階にはオフィスが入居しているため、屋上まで排煙…', '4828', '0', '3203', '2025-03-25 02:04:18', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('74', '焼肉マイスター-かなchan-様（古賀市）-排煙ファンリ', '焼肉マイスター かなChan 様（古賀市） 排煙ファンリフレッシュ工事', '<h3>施工内容</h3>\n<p>古賀市にある「焼肉マイスター かなChan」様の排煙ファンを分解・清掃し、リフレッシュ工事を行いました。長年の使用によりファン内部に油が溜まり、排気能力が低下。さらに油の粘度が高いため、油抜きドレンからの排出が滞っていました。今回、ファンを分解して羽根に付着した汚れをしっかり除去したことで、設置当初の風量が復活し、快適な排気環境を取り戻すことができました。</p>', '福岡県古賀市', '2023-05-15', 'published', '焼肉マイスター かなChan 様（古賀市） 排煙ファンリフレッシュ工事｜施工事例【株式会社野田】', '古賀市にある「焼肉マイスターかなChan」様の排煙ファンを分解・清掃し、リフレッシュ工事を行いました。長年の使用によりファン内部に油が溜まり、排気能力が低下。さらに油の粘度が高いため、油抜きドレンからの排出が滞っていま…', '4832', '0', '3210', '2025-03-25 02:07:44', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('75', '福岡市中央区春吉「焼肉-牛喜-様」給排気工事', '福岡市中央区春吉「焼肉 牛喜 様」給排気工事', '<h3>施工内容</h3>\n<p><strong>福岡市中央区春吉にオープンした「焼肉 牛喜」様 別館</strong>にて、焼肉上引きフード・厨房フード・店内換気など、給排気工事一式を担当させていただきました。落ち着いた雰囲気の店内で、こだわり抜いた焼肉をゆっくりと楽しめる人気店です。ぜひ足を運んでみてください。</p>', '福岡市中央区', '2023-06-06', 'published', '福岡市中央区春吉「焼肉 牛喜 様」給排気工事｜施工事例【株式会社野田】', '福岡市中央区春吉にオープンした「焼肉牛喜」様別館にて、焼肉上引きフード・厨房フード・店内換気など、給排気工事一式を担当させていただきました。落ち着いた雰囲気の店内で、こだわり抜いた焼肉をゆっくりと楽しめる人気店です。ぜ…', '4837', '0', '3218', '2025-03-25 02:10:28', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('76', '黒崎駅前にリニューアルオープンした「炭火焼肉', '黒崎駅前にリニューアルオープンした「炭火焼肉 八輪」様の給気追加工事', '<h3>施工内容</h3>\n<p>居抜き店舗への移転に際し、上引きフードや厨房排気を増設した一方で給気は既存のまま営業を開始されましたが、やはり給気不足が懸念されていたため、今回の追加工事を実施。天井内チャンバーを経由させることで、温度や風速の安定性を高めつつ、点検口を吹き出し口として活用する自然給気方式を採用しました。また、ノンドラ仕様を用いることで、お客様に直接風が当たらないよう配慮。排気ばかりに注目されがちなダクト工事ですが、しっかりとした給気設備こそ、快適な店内環境には欠かせません。</p>', '北九州市八幡西区', '2023-07-14', 'published', '黒崎駅前にリニューアルオープンした「炭火焼肉 八輪」様の給気追加工事｜施工事例【株式会社野田】', '居抜き店舗への移転に際し、上引きフードや厨房排気を増設した一方で給気は既存のまま営業を開始されましたが、やはり給気不足が懸念されていたため、今回の追加工事を実施。天井内チャンバーを経由させることで、温度や風速の安定性を…', '4842', '0', '3231', '2025-03-25 02:13:34', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('77', '福岡市東区にある焼鳥店-ダクト経路変更工事', '福岡市東区にある焼鳥店 ダクト経路変更工事', '<h3>施工内容</h3>\n<p>焼き鳥を焼く煙がフードから逃げて店内が真っ白になるとのお悩みを受け、既存の排気ダクトを背抜きの2口仕様に変更しました。従来はフードの横面に接続され、片側から排気する設計だったため、排煙ファンまでの経路を短縮し、静圧を抑えながらより大きな風量で排気できるように改善。さらに、グリスフィルターを導入し、面での排煙を実現することで、店内の排気効率が大幅に向上しました。</p>', '福岡市東区', '2023-08-08', 'published', '福岡市東区にある焼鳥店 ダクト経路変更工事｜施工事例【株式会社野田】', '焼き鳥を焼く煙がフードから逃げて店内が真っ白になるとのお悩みを受け、既存の排気ダクトを背抜きの2口仕様に変更しました。従来はフードの横面に接続され、片側から排気する設計だったため、排煙ファンまでの経路を短縮し、静圧を抑…', '4846', '0', '3239', '2025-03-25 11:09:34', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('78', '福岡市博多区【ベーカリー】フード工事', '福岡市博多区【ベーカリー】フード工事', '<h3>施工内容</h3>\n<p><strong>福岡市博多区雑餉隈に新規オープン予定のパン屋さん</strong>にて、ベーカリーオーブンから発生する熱気を効率的に排気するため、大きめのフードと上抜きダクトを採用しました。さらに、静圧の高いシロッコファンを用いることで、多少複雑なダクト経路でも力強く排気が可能な設計となっています。これにより、パン作りに適した快適な厨房環境を実現し、焼きたての美味しさをお客様に提供できるようサポートしています。</p>', '福岡市博多区', '2023-08-30', 'published', '福岡市博多区【ベーカリー】フード工事｜施工事例【株式会社野田】', '福岡市博多区雑餉隈に新規オープン予定のパン屋さんにて、ベーカリーオーブンから発生する熱気を効率的に排気するため、大きめのフードと上抜きダクトを採用しました。さらに、静圧の高いシロッコファンを用いることで、多少複雑なダク…', '4851', '0', '3241', '2025-03-25 11:11:46', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('79', '福岡県春日市【宮崎地鶏焼き鳥専門店】厨房フー', '福岡県春日市【宮崎地鶏焼き鳥専門店】厨房フード工事', '<h3>施工内容</h3>\n<p><strong>福岡県春日市に新規オープン予定のテイクアウト専門・宮崎地鶏焼き鳥専門店</strong>にて、居ぬき店舗を活用した排気設備の改修工事を行いました。既存フードを加工し、排気風量を大幅にアップさせることで、煙の多い宮崎地鶏料理にも対応。さらに、排気吹き出し口を立ち上げる設計とすることで、周辺住宅への影響を最小限に抑え、安心して営業できる環境を整えました。</p>', '福岡県春日市', '2023-09-26', 'published', '福岡県春日市【宮崎地鶏焼き鳥専門店】厨房フード工事｜施工事例【株式会社野田】', '福岡県春日市に新規オープン予定のテイクアウト専門・宮崎地鶏焼き鳥専門店にて、居ぬき店舗を活用した排気設備の改修工事を行いました。既存フードを加工し、排気風量を大幅にアップさせることで、煙の多い宮崎地鶏料理にも対応。さら…', '4856', '0', '3251', '2025-03-25 11:15:00', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('80', '福岡市中央区【薪焼料理店】煙対策工事', '福岡市中央区【薪焼料理店】煙対策工事', '<h3>施工内容</h3>\n<p><strong>福岡市中央区にある薪焼き料理店様</strong>から、上層階への煙の影響を早急に解消したいというご要望を受け、電気集塵機の導入を提案・設置いたしました。薪特有のヤニを効果的に除去できるため、排気がクリアになり、苦情の原因となっていた煙の問題が大幅に改善。お客様からも大変ご満足いただけました。</p>', '福岡市中央区', '2023-10-31', 'published', '福岡市中央区【薪焼料理店】煙対策工事｜施工事例【株式会社野田】', '福岡市中央区にある薪焼き料理店様から、上層階への煙の影響を早急に解消したいというご要望を受け、電気集塵機の導入を提案・設置いたしました。薪特有のヤニを効果的に除去できるため、排気がクリアになり、苦情の原因となっていた煙…', '4861', '0', '3260', '2025-03-25 11:17:40', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('81', '某大手ピザチェーン店様-ピザ窯用排気設備工事', '某大手ピザチェーン店様 ピザ窯用排気設備工事', '<h3>施工内容</h3>\n<p>ピザ窯の高い熱量に対応するため、特にフード内の排気口位置に細心の注意を払い、熱源から適切な距離を保つよう設計しました。排気フードの材質や耐熱性能を厳選し、厨房内の空気の流れを最適化することで、従業員の皆様が安心して作業できる環境を実現しています。<br>安全基準を厳守し、高温作業にも耐えうる設備を整えられたことで、お客様からもご好評をいただきました。今後も、お客様のニーズに応える安全かつ効率的な施工を続けてまいります。</p>', '福岡県八女市', '2023-11-16', 'published', '某大手ピザチェーン店様 ピザ窯用排気設備工事｜施工事例【株式会社野田】', 'ピザ窯の高い熱量に対応するため、特にフード内の排気口位置に細心の注意を払い、熱源から適切な距離を保つよう設計しました。排気フードの材質や耐熱性能を厳選し、厨房内の空気の流れを最適化することで、従業員の皆様が安心して作業…', '4866', '0', '3268', '2025-03-25 11:25:02', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('82', '福岡市【居酒屋店舗】排煙ダクト工事', '福岡市【居酒屋店舗】排煙ダクト工事', '<h3>施工内容</h3>\n<p>福岡市の居酒屋様、排煙ダクト工事完了しました! <br>✅ 最新の排煙システムで効率的な煙排出<br>✅ 消防法規制もクリアした安全設計<br>✅ 店舗の雰囲気を損なわない美しい仕上がり<br>いつも来店するお客様からも「店内の空気が変わった！」と大好評いただいています。</p>\n<p>焼肉店や居酒屋など、煙対策でお困りの飲食店オーナー様、ビルオーナー様、お気軽にご相談ください。<br>私たち野田は、店舗設計事務所様や施工会社様とも連携し、クライアント様の成功をサポートいたします。</p>', '福岡市', '2023-12-13', 'published', '福岡市【居酒屋店舗】排煙ダクト工事｜施工事例【株式会社野田】', '福岡市の居酒屋様、排煙ダクト工事完了しました!✅最新の排煙システムで効率的な煙排出✅消防法規制もクリアした安全設計✅店舗の雰囲気を損なわない美しい仕上がりいつも来店するお客様からも「店内の空気が変わった！」と大好評いた…', '4870', '0', '3279', '2025-03-25 11:32:15', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('83', '福岡県宗像市【ホルモン焼肉店舗】排煙ダクト工', '福岡県宗像市【ホルモン焼肉店舗】排煙ダクト工事', '<h3>施工内容</h3>\n<p>福岡県宗像市にNEWオープンのホルモン焼肉店様の排煙ダクト工事が完了しました！✨</p>\n<p>スタイリッシュな店内に映える、美しい仕上がりの排煙ダクトをご覧ください。</p>\n<p>特徴：<br>✅業務用ダクトを耐久性のある亜鉛鉄板のスパイラルダクトで施工<br>✅ デザイン性と機能性を両立<br>✅ 徹底した防火・安全設計<br>✅ メンテナンス性を考慮した施工</p>\n<p>焼肉店特有の濃い煙もしっかり排出できる設計で、快適な店内環境を実現します。</p>\n<p>私たちは20年以上、焼肉店や居酒屋など、煙の多い飲食店の排煙設備を手がけてきました。新規開業から既存店のリニューアルまで、幅広くご対応させていただきます。</p>', '福岡県宗像市', '2024-01-24', 'published', '福岡県宗像市【ホルモン焼肉店舗】排煙ダクト工事｜施工事例【株式会社野田】', '福岡県宗像市にNEWオープンのホルモン焼肉店様の排煙ダクト工事が完了しました！✨スタイリッシュな店内に映える、美しい仕上がりの排煙ダクトをご覧ください。特徴：✅業務用ダクトを耐久性のある亜鉛鉄板のスパイラルダクトで施工…', '4872', '0', '3282', '2025-03-25 11:44:15', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('84', '福岡市中央区【新規焼肉店舗】排煙ダクト工事', '福岡市中央区【新規焼肉店舗】排煙ダクト工事', '<h3>施工内容</h3>\n<p>【工事進捗報告】福岡市中央区・新規焼肉店様の排煙ダクト仕込み完了！</p>\n<p>複雑な天井裏の配管も、綺麗に納めることができました✨<br>内装工事の邪魔にならないよう、細部まで配慮した施工を心がけています。</p>', '福岡市中央区', '2024-02-19', 'published', '福岡市中央区【新規焼肉店舗】排煙ダクト工事｜施工事例【株式会社野田】', '【工事進捗報告】福岡市中央区・新規焼肉店様の排煙ダクト仕込み完了！複雑な天井裏の配管も、綺麗に納めることができました✨内装工事の邪魔にならないよう、細部まで配慮した施工を心がけています。', '4875', '0', '3288', '2025-03-25 11:48:37', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('85', '福岡市中央区【新規飲食店】排気ダクト工事', '福岡市中央区【新規飲食店】排気ダクト工事', '<h3>施工内容</h3>\n<p>福岡市中央区の新規飲食店様にて、排気ダクト工事が完了いたしました✨</p>\n<p>飲食店の命綱とも言える換気・排煙設備。<br>特に焼肉店や居酒屋など、油煙が多い店舗では<br>適切な設計・施工が店舗運営の要となります。</p>', '福岡市中央区', '2024-03-12', 'published', '福岡市中央区【新規飲食店】排気ダクト工事｜施工事例【株式会社野田】', '福岡市中央区の新規飲食店様にて、排気ダクト工事が完了いたしました✨飲食店の命綱とも言える換気・排煙設備。特に焼肉店や居酒屋など、油煙が多い店舗では適切な設計・施工が店舗運営の要となります。', '4877', '1', '3293', '2025-03-25 11:50:53', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('86', '福岡県大野城市　排煙ダクト工事', '福岡県大野城市　排煙ダクト工事', '<h3>施工内容</h3>\n<p>福岡県大野城市のお客様店舗排煙ダクト工事、完工致しました！<br><br>今回の施工事例。<br>屋内外の両方で徹底した品質にこだわった排煙設備を構築しました。</p>\n<p>【施工のポイント】<br>1️⃣ 外観の美観を損なわないスッキリとした取付け<br>2️⃣ 消防法規制に準拠した安全な設計・施工<br>3️⃣ アルミ製断熱材による確実な保温処理<br>4️⃣ 耐久性の高いダクトサポートで揺れにも安心<br>飲食店の快適な空間づくりに欠かせない排煙設備。</p>', '福岡県大野城市', '2024-03-28', 'published', '福岡県大野城市　排煙ダクト工事｜施工事例【株式会社野田】', '福岡県大野城市のお客様店舗排煙ダクト工事、完工致しました！今回の施工事例。屋内外の両方で徹底した品質にこだわった排煙設備を構築しました。【施工のポイント】1️⃣外観の美観を損なわないスッキリとした取付け2️⃣消防法規制…', '4879', '1', '3301', '2025-03-25 11:53:00', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('87', '広島県東広島市【焼肉店舗】排煙ダクトリニュー', '広島県東広島市【焼肉店舗】排煙ダクトリニューアル工事', '<h3>施工内容</h3>\n<p>広島県東広島市の焼肉店様 リニューアル完了！ <br>今回は焼肉店様の排煙ダクトリニューアル工事を担当。</p>\n<p>排煙効率が悪い傘タイプフードから、効率の良い筒タイプフードに変更することで、機能的な設計で店舗と調和した、落ち着きのある空間に仕上がりました。</p>\n<p>職人による確かな施工技術と、20年以上の実績で培った設計ノウハウで、安全性と意匠性を両立。<br>焼肉店・居酒屋など、煙の出る店舗の開業・改装をお考えの方、ぜひお気軽にご相談ください！</p>', '広島県東広島市', '2024-04-23', 'published', '広島県東広島市【焼肉店舗】排煙ダクトリニューアル工事｜施工事例【株式会社野田】', '広島県東広島市の焼肉店様リニューアル完了！今回は焼肉店様の排煙ダクトリニューアル工事を担当。排煙効率が悪い傘タイプフードから、効率の良い筒タイプフードに変更することで、機能的な設計で店舗と調和した、落ち着きのある空間に…', '4881', '0', '3303', '2025-03-25 11:55:53', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('88', '筑紫野市【大型居酒屋チェーン】外部吹き出し工', '筑紫野市【大型居酒屋チェーン】外部吹き出し工事', '<h3>施工内容</h3>\n<p>筑紫野市の大型居酒屋チェーン様、外部吹き出し工事が完了しました！<br>店舗の外観を損なわないスタイリッシュな外部吹き出し口の設置と、パワフルな排気能力を両立。<br>通常は、ヒアリングのうえ風量計算してファン、吹出口等を選出するのですが、今回ケースでは全国チェーンとして、既定のチェーン仕様に基づく店舗様からの支給品により施工を行いました。</p>\n<p>このようなチェーン店舗様の施工実績も豊富で、統一した設備基準にも対応可能です。</p>\n<p>新規出店やリニューアルをご検討中の方は、ぜひご相談ください！</p>', '福岡県筑紫野市', '2024-05-22', 'published', '筑紫野市【大型居酒屋チェーン】外部吹き出し工事｜施工事例【株式会社野田】', '筑紫野市の大型居酒屋チェーン様、外部吹き出し工事が完了しました！店舗の外観を損なわないスタイリッシュな外部吹き出し口の設置と、パワフルな排気能力を両立。通常は、ヒアリングのうえ風量計算してファン、吹出口等を選出するので…', '4883', '0', '3308', '2025-03-25 11:58:36', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('89', '福岡市中央区【寿司居酒屋】排煙ダクト設計・施', '福岡市中央区【寿司居酒屋】排煙ダクト設計・施工', '<h3>施工内容</h3>\n<p>福岡市中央区の新規出店案件、ダクト工事完了しました！<br>今回は寿司居酒屋様の新規出店に伴う排煙ダクト設計・施工を担当させていただきました。<br>寿司カウンターでの会話を楽しめる空間づくりをテーマに、低騒音・高性能な換気システムを実現。</p>\n<p>職人の技と会話を楽しむ、上質な空間づくりにこだわりました。</p>\n<p>徹底的な理想店舗の実現を目指して現場調査と綿密な打ち合わせにより、店舗の特性に合わせた最適なダクトプランをご提案。</p>', '福岡市中央区', '2024-06-17', 'published', '福岡市中央区【寿司居酒屋】排煙ダクト設計・施工｜施工事例【株式会社野田】', '福岡市中央区の新規出店案件、ダクト工事完了しました！今回は寿司居酒屋様の新規出店に伴う排煙ダクト設計・施工を担当させていただきました。寿司カウンターでの会話を楽しめる空間づくりをテーマに、低騒音・高性能な換気システムを…', '4888', '0', '3313', '2025-03-25 12:00:46', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('90', '宮崎市【焼肉店】ダクト施工', '宮崎市【焼肉店】ダクト施工', '<h3>施工内容</h3>\n<p>宮崎市内の焼肉店様、ダクト工事完了のご報告です！<br>確かな換気システムは、お客様に安心して焼肉を楽しんでいただくための必須アイテム。今回は自然給気と強制給気の両方を設置し、店内の快適性を最大限に高めました。</p>\n<p>特長：<br>自然給気＆強制給気のダブル設置<br>虫網完備で衛生面も万全<br>スタイリッシュな内装に合わせたダクトデザイン</p>\n<p>飲食店の換気設備でお悩みの方は、ぜひお気軽にご相談ください！</p>', '宮崎県宮崎市', '2024-07-01', 'published', '宮崎市【焼肉店】ダクト施工｜施工事例【株式会社野田】', '宮崎市内の焼肉店様、ダクト工事完了のご報告です！確かな換気システムは、お客様に安心して焼肉を楽しんでいただくための必須アイテム。今回は自然給気と強制給気の両方を設置し、店内の快適性を最大限に高めました。特長：自…', '4890', '0', '3318', '2025-03-25 12:04:50', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('91', '宮崎市【大型店舗】排煙ダクト設置', '宮崎市【大型店舗】排煙ダクト設置', '<h3>施工内容</h3>\n<p>宮崎市大型店舗様 施工事例のご紹介<br>焼肉店様の排煙ダクト設置工事が完了しました！<br><br>今回のポイント：<br>▫️炭火炉からの高温排気に対応したフレッシュエアー導入<br>▫️海に近い立地を考慮した塩害対策用ファンカバー設置<br>▫️安全性と耐久性を重視した設計施工<br>飲食店の命綱となる換気設備。<br>特に炭火を使用する焼肉店では、<br>お客様の快適さと従業員の安全を両立する<br>確かな設計・施工が必要不可欠です。</p>', '宮崎県宮崎市', '2024-07-26', 'published', '宮崎市【大型店舗】排煙ダクト設置｜施工事例【株式会社野田】', '宮崎市大型店舗様施工事例のご紹介焼肉店様の排煙ダクト設置工事が完了しました！今回のポイント：▫️炭火炉からの高温排気に対応したフレッシュエアー導入▫️海に近い立地を考慮した塩害対策用ファンカバー設置▫️安全性と耐久性を…', '4893', '0', '3330', '2025-03-25 12:08:26', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('92', '宮崎県日南市【焼き鳥店】排煙ダクト設計・施工', '宮崎県日南市【焼き鳥店】排煙ダクト設計・施工', '<h3>施工内容</h3>\n<p>宮崎県日南市の焼き鳥店様の施工事例をご紹介<br>厨房内の天井が低い店舗での排煙ダクト設置のご依頼。<br>ダクトがスタッフの動線を妨げない設計で、快適な作業環境を実現しました✨</p>\n<p>特徴：<br>▫️天井高に合わせた最適なダクトレイアウト<br>▫️スタッフの作業効率を考慮した配置<br>▫️炭火使用に対応した防火ダンパー(FD)設置<br>▫️安全性と実用性を両立した設計</p>\n<p>飲食店の命綱となる換気設備。<br>プロの目線で、店舗環境に合わせた最適なソリューションをご提案いたします。</p>', '宮崎県日南市', '2024-09-05', 'published', '宮崎県日南市【焼き鳥店】排煙ダクト設計・施工｜施工事例【株式会社野田】', '宮崎県日南市の焼き鳥店様の施工事例をご紹介厨房内の天井が低い店舗での排煙ダクト設置のご依頼。ダクトがスタッフの動線を妨げない設計で、快適な作業環境を実現しました✨特徴：▫️天井高に合わせた最適なダクトレイアウト▫️スタ…', '4895', '0', '3332', '2025-03-25 12:10:54', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('93', '岡山県津山市【焼肉店】排煙ダクト施工', '岡山県津山市【焼肉店】排煙ダクト施工', '<h3>施工内容</h3>\n<p>岡山県津山市の焼肉店様にて、排煙ダクト工事が無事完了しました！</p>\n<p>昨年、不慮の火災が発生し、営業継続が危ぶまれる状況でしたが、防火装置が作動し全焼を免れました。<br>今回の工事では、安全性を最優先に、新たな防火装置を慎重に検討し、万全の対策を施しました。</p>', '岡山県津山市', '2024-10-02', 'published', '岡山県津山市【焼肉店】排煙ダクト施工｜施工事例【株式会社野田】', '岡山県津山市の焼肉店様にて、排煙ダクト工事が無事完了しました！昨年、不慮の火災が発生し、営業継続が危ぶまれる状況でしたが、防火装置が作動し全焼を免れました。今回の工事では、安全性を最優先に、新たな防火装置を慎重…', '4898', '0', '3338', '2025-03-25 12:14:20', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('94', '大阪市中央区【飲食店】排煙ダクト工事', '大阪市中央区【飲食店】排煙ダクト工事', '<h3>施工内容</h3>\n<p>大阪中心部の駅近飲食店街にあるお店にて、排煙ダクト工事が無事完了しました！</p>\n<p>今回の工事では、施設運営の高い安全性要件を満たすため、最上級の防火ダンパーを採用しました。<br>駅近の飲食店街は防火対策が特に重要です。当社は、煙の多い焼肉店や居酒屋をはじめ、飲食店の排煙ダクト工事を専門とし、お客様の安全を最優先に施工を行っています。</p>\n<p>飲食店のオーナー様、施工会社様、内装設計の事業者様、防火対策や排煙ダクト工事でお困りの際はぜひご相談ください！<br>安心して営業を続けられる環境を提供いたします。</p>', '大阪市中央区', '2024-10-28', 'published', '大阪市中央区【飲食店】排煙ダクト工事｜施工事例【株式会社野田】', '大阪中心部の駅近飲食店街にあるお店にて、排煙ダクト工事が無事完了しました！今回の工事では、施設運営の高い安全性要件を満たすため、最上級の防火ダンパーを採用しました。駅近の飲食店街は防火対策が特に重要です。当社は、煙の多…', '4913', '0', '3366', '2025-03-25 12:16:56', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('95', '福岡県北九州市【ラーメン店】排煙ダクト工事', '福岡県北九州市【ラーメン店】排煙ダクト工事', '<h3>施工内容</h3>\n<p>当社がダクト工事を担当した全国300店舗超の人気ラーメン店がついに福岡にオープンしました！</p>\n<p>清潔で快適な空間<br>当社施工のダクトシステムで空気環境を徹底サポート✨<br>「美味しいラーメン」に集中できる明るく開放的な店内です！</p>', '福岡県北九州市', '2024-11-25', 'published', '福岡県北九州市【ラーメン店】排煙ダクト工事｜施工事例【株式会社野田】', '当社がダクト工事を担当した全国300店舗超の人気ラーメン店がついに福岡にオープンしました！清潔で快適な空間当社施工のダクトシステムで空気環境を徹底サポート✨「美味しいラーメン」に集中できる明るく開放的な店内です！', '4922', '0', '3383', '2025-03-25 12:20:02', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('96', '【製麺所】粉塵＆虫対策工事', '【製麺所】粉塵＆虫対策工事', '<h3>施工内容</h3>\n<p>製麺所さま向け・粉塵＆虫対策工事が完了しました！<br><br>製麺工程でどうしても発生する湯気や粉塵の飛散対策として、大規模な厨房換気設備を導入しました</p>\n<p>特に今回は製麺所ということもあり、大型の茹で機から出る大量の蒸気や粉塵に対応できるよう、大風量タイプの排煙設備を設置しています！</p>\n<p>✅ 湯気や粉塵を強力吸引でスッキリ解消！</p>\n<p>✅もちろん食品工場ですので給気口には虫や埃が入らないよう細部まで徹底対策</p>\n<p>✅ 衛生面や食品品質を守るこだわりの設計施工です！</p>\n<p>焼肉店や居酒屋など煙が気になる飲食店オーナー様、内装設計会社さまもお気軽にご相談ください✨</p>\n<p>快適な厨房環境づくりをサポートいたします</p>', '福岡県', '2024-12-10', 'published', '【製麺所】粉塵＆虫対策工事｜施工事例【株式会社野田】', '製麺所さま向け・粉塵＆虫対策工事が完了しました！製麺工程でどうしても発生する湯気や粉塵の飛散対策として、大規模な厨房換気設備を導入しました特に今回は製麺所ということもあり、大型の茹で機から出る大量の蒸気や粉塵…', '4936', '0', '3387', '2025-03-25 12:23:29', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('97', '福岡県中間市【焼肉店】排煙ダクト工事', '福岡県中間市【焼肉店】排煙ダクト工事', '<h3>施工内容</h3>\n<p>今回、福岡県中間市の焼肉店様にて、排煙ダクト工事が無事完了しました！<br>オーナー様は、周辺地域で火災が多発していることを危惧され、「念には念を」との思いで当社にご相談をいただきました。</p>\n<p>工事では、万が一の火災に備え、断熱材を巻きつけることで延焼を防ぐ対策を施しました。</p>\n<p>当社は、煙の多い焼肉店や居酒屋をはじめ、飲食店の排煙ダクト工事を専門としています。</p>\n<p>火災リスクを軽減し、お客様が安心して営業を続けられる環境を提供します！</p>', '福岡県中間市', '2025-01-23', 'published', '福岡県中間市【焼肉店】排煙ダクト工事｜施工事例【株式会社野田】', '今回、福岡県中間市の焼肉店様にて、排煙ダクト工事が無事完了しました！オーナー様は、周辺地域で火災が多発していることを危惧され、「念には念を」との思いで当社にご相談をいただきました。工事では、万が一の火災に備え、断熱材を…', '4948', '0', '3413', '2025-03-25 12:26:43', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('98', '福岡市南区【コインランドリー】排煙ダクト工事', '福岡市南区【コインランドリー】排煙ダクト工事', '<h3>施工内容</h3>\n<p>今回はコインランドリー専門の工務店様からご依頼いただき、<br>2日間の短期施工で無事にダクト工事を完了しました</p>\n<p>コインランドリーのような特殊な施設でも、<br>これまでの経験とノウハウを活かしてスムーズに対応<br>もちろん、焼肉店や居酒屋など“煙の多い”飲食店の排煙ダクトもお任せください</p>', '福岡市南区', '2025-02-12', 'published', '福岡市南区【コインランドリー】排煙ダクト工事｜施工事例【株式会社野田】', '今回はコインランドリー専門の工務店様からご依頼いただき、2日間の短期施工で無事にダクト工事を完了しましたコインランドリーのような特殊な施設でも、これまでの経験とノウハウを活かしてスムーズに対応もち…', '4958', '0', '3416', '2025-03-25 12:31:23', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('99', '福岡市博多区【居酒屋】排煙ダクト工事', '福岡市博多区【居酒屋】排煙ダクト工事', '<h3>施工内容</h3>\n<p>福岡市博多区の居酒屋様にて、炭火焼き台専用の排煙設備工事が完了しました✨</p>\n<p>今回の焼き台は、通常よりも1.5倍の強い火力で調理するため、排煙量も大幅アップ！<br>そこで「炭火用」の特別な排煙設計を実施。吸引力抜群な『シロッコファン』を導入し、煙をしっかりとキャッチして快適な厨房環境を実現しました</p>\n<p>✅ 煙や臭いをパワフルに排出！ ✅ 厨房の空気環境改善＆作業効率アップ ✅ 焼肉店や炭火を使う居酒屋様にも最適！</p>', '福岡市博多区', '2025-03-17', 'published', '福岡市博多区【居酒屋】排煙ダクト工事｜施工事例【株式会社野田】', '福岡市博多区の居酒屋様にて、炭火焼き台専用の排煙設備工事が完了しました✨今回の焼き台は、通常よりも1.5倍の強い火力で調理するため、排煙量も大幅アップ！そこで「炭火用」の特別な排煙設計を実施。吸引力抜群な『シロ…', '4964', '0', '3426', '2025-03-25 12:34:29', '2026-10-22 06:08:01');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('100', '福岡市中央区【焼き鳥店】排煙ダクト工事', '福岡市中央区【焼き鳥店】排煙ダクト工事', '<h3>施工内容</h3>\n<p>福岡市中央区、高層マンションが密集するエリアで焼き鳥店の排煙ダクト工事が完了✨<br>今回は有名焼き鳥店ご出身のお客様のこだわりで、煙対策はもちろんのこと、「静かな店内環境」も徹底的に追求しました！</p>\n<p>✅ 強力な排煙設備＆消煙機で煙を徹底除去！ ✅ 特別な静音設計ファンを導入、騒音トラブルを未然に防止！ ✅ 高層マンション密集地でも安心して営業できる環境を実現しました！</p>', '福岡市中央区', '2025-04-07', 'published', '福岡市中央区【焼き鳥店】排煙ダクト工事｜施工事例【株式会社野田】', '福岡市中央区、高層マンションが密集するエリアで焼き鳥店の排煙ダクト工事が完了✨今回は有名焼き鳥店ご出身のお客様のこだわりで、煙対策はもちろんのこと、「静かな店内環境」も徹底的に追求しました！✅強力な排煙設備＆消煙機で煙…', '4968', '0', '3496', '2025-04-07 12:32:40', '2026-10-21 12:30:06');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('101', '福岡市南区【鉄板焼き店】排煙ダクト工事', '福岡市南区【鉄板焼き店】排煙ダクト工事', '<h3>施工内容</h3>\n<p>博多名物の鉄板焼き店にて、店内と厨房の排煙・換気設備工事を行いました✨<br>今回は中華鍋を使用し、肉や野菜を豪快に炒めるため煙の発生量は通常の2倍！<br>そこで、排煙能力も2倍のパワフル設計に</p>\n<p>✅ 厨房内の大量の煙を瞬時にキャッチ！ ✅ 客席前の鉄板から漂う煙もしっかり吸引し、快適な店内を実現✨ ✅ 飲食店特有の臭い問題や油煙問題を完全にクリアしました!</p>', '福岡市南区', '2025-04-10', 'published', '福岡市南区【鉄板焼き店】排煙ダクト工事｜施工事例【株式会社野田】', '博多名物の鉄板焼き店にて、店内と厨房の排煙・換気設備工事を行いました✨今回は中華鍋を使用し、肉や野菜を豪快に炒めるため煙の発生量は通常の2倍！そこで、排煙能力も2倍のパワフル設計に✅厨房内の大量の煙を瞬時にキャッチ！✅…', '4983', '0', '3572', '2025-04-10 00:10:20', '2026-10-21 12:30:07');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('102', '糸島の人気焼肉店・2号店の排煙設備工事が完了し', '糸島の人気焼肉店・2号店の排煙設備工事が完了しました！', '<h3>施工内容</h3>\n<p>糸島市で話題の焼肉店様が、新たに2号店をオープン！<br>ありがたいことに、1号店に続いて再び当社に工事をご依頼いただきました✨</p>\n<p>今回も、メンテナンスが簡単で好評な『上引きフード』を採用。<br>快適な店内空間を実現し、お客様がゆっくりと焼肉を楽しめるよう、しっかりと煙を吸引しています！</p>', '福岡県糸島市', '2025-04-16', 'published', '糸島の人気焼肉店・2号店の排煙設備工事が完了しました！｜施工事例【株式会社野田】', '糸島市で話題の焼肉店様が、新たに2号店をオープン！ありがたいことに、1号店に続いて再び当社に工事をご依頼いただきました✨今回も、メンテナンスが簡単で好評な『上引きフード』を採用。快適な店内空間を実現し、お客様がゆっくり…', '4994', '0', '3602', '2025-04-16 00:04:48', '2026-10-21 12:30:07');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('103', '有名弁当チェーン様の静音＆排煙ダクト工事が完', '有名弁当チェーン様の静音＆排煙ダクト工事が完了しました！', '<h3>施工内容</h3>\n<p>超有名弁当チェーン店『○っと○っと』様より、排煙設備工事のご依頼をいただきました。<br>建物の2階以上が住居という環境のため、店舗から発生する音や煙の配慮してほしいとご依頼いただき対策を万全に実施✨</p>\n<p>✅『静音ボックス』を2台設置し、騒音問題を徹底的に防止！ ✅排気口を屋上に設置し、煙・臭いのトラブルを未然に回避！ ✅飲食店と住宅が共存できる、快適な環境を実現しました！</p>', '福岡県大野城市', '2025-04-21', 'published', '有名弁当チェーン様の静音＆排煙ダクト工事が完了しました！｜施工事例【株式会社野田】', '超有名弁当チェーン店『○っと○っと』様より、排煙設備工事のご依頼をいただきました。建物の2階以上が住居という環境のため、店舗から発生する音や煙の配慮してほしいとご依頼いただき対策を万全に実施✨✅『静音ボックス』を2台設…', '4999', '0', '3620', '2025-04-21 15:23:53', '2026-10-21 12:30:08');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('104', '中洲川端・商店街での厨房排煙ダクト＆断熱工事', '中洲川端・商店街での厨房排煙ダクト＆断熱工事が完了しました！', '<h3>施工内容</h3>\n<p>福岡市の人気エリア・中洲川端のレストラン様より、厨房排煙設備の工事をご依頼いただきました。<br>店舗が商店街内に位置しているため、火災などの安全対策を重視し、徹底した断熱工事を行っています。</p>\n<p>✅ 熱・油の安全対策に「グリスフィルター」を完備！ ✅ 密集地域ならではの高水準の断熱施工で安全性も抜群！ ✅ 周囲環境に配慮した万全の設計施工で安心営業！</p>', '福岡市博多区', '2025-04-29', 'published', '中洲川端・商店街での厨房排煙ダクト＆断熱工事が完了しました！｜施工事例【株式会社野田】', '福岡市の人気エリア・中洲川端のレストラン様より、厨房排煙設備の工事をご依頼いただきました。店舗が商店街内に位置しているため、火災などの安全対策を重視し、徹底した断熱工事を行っています。✅熱・油の安全対策に「グリスフィル…', '5005', '0', '3642', '2025-04-29 11:53:17', '2026-10-21 12:30:08');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('105', '大型スーパーの防火施工を実施しました。', '大型スーパーの防火施工を実施しました。', '<h3>施工内容</h3>\n<p>今回の現場は、大型スーパー。<br>火災時に天井から自動開放する「排煙口」を設置いたしました。<br>通常よりも分厚い断熱材＆太めの排煙ダクトで、煙をしっかり外へ誘導。</p>\n<p>火の多い現場、煙の多い厨房。<br>その対策、「なんとなく」で済ませてませんか？</p>\n<p>消防法に適した排煙口の設置も当社にお任せください。</p>', '長崎県', '2025-05-06', 'published', '大型スーパーの防火施工を実施しました。｜施工事例【株式会社野田】', '今回の現場は、大型スーパー。火災時に天井から自動開放する「排煙口」を設置いたしました。通常よりも分厚い断熱材＆太めの排煙ダクトで、煙をしっかり外へ誘導。火の多い現場、煙の多い厨房。その対策、「なんとなく」で済ませてませ…', '5017', '0', '3654', '2025-05-06 15:43:22', '2026-10-21 12:30:08');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('106', '【福岡・春吉】オーナー様のご要望に応える埋', '【福岡・春吉】オーナー様のご要望に応える“埋め込み型フード”施工完了', '<h3>施工内容</h3>\n<p>通常は露出設置される厨房フード。<br>しかし今回は「空間デザインを優先したい」というご要望にお応えし、<br>天井にすっきり埋め込むスタイルで施工しました。</p>\n<p>✅煙の多い業態でもデザイン性を犠牲にしない<br>✅排煙性能はそのままに、見た目すっきり<br>✅断熱材でしっかりと安全対策も強化</p>\n<p>「目立たせたくない」「空間を洗練させたい」そんな声にもしっかり対応できます。</p>\n<p>福岡市中央区春吉の飲食店様、ありがとうございました！<br>福岡・近県はもちろん、全国出張施工も承ります。</p>', '福岡市中央区', '2025-05-13', 'published', '【福岡・春吉】オーナー様のご要望に応える“埋め込み型フード”施工完了｜施工事例【株式会社野田】', '通常は露出設置される厨房フード。しかし今回は「空間デザインを優先したい」というご要望にお応えし、天井にすっきり埋め込むスタイルで施工しました。✅煙の多い業態でもデザイン性を犠牲にしない✅排煙性能はそのままに、見た目すっ…', '5022', '0', '3672', '2025-05-13 14:02:12', '2026-10-21 12:30:09');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('107', '某有名食堂チェーン様の天井内ダクト工事完了し', '某有名食堂チェーン様の天井内ダクト工事完了しました。', '<h3>施工内容</h3>\n<p>今回は厨房上部にダクトを通す大規模工事。<br>天井内はエアコン配管との干渉が多く、<br>エアコン事業者さまとしっかり打ち合わせを行いながら進めました。</p>', '福岡県久留米市', '2025-05-18', 'published', '某有名食堂チェーン様の天井内ダクト工事完了しました。｜施工事例【株式会社野田】', '今回は厨房上部にダクトを通す大規模工事。天井内はエアコン配管との干渉が多く、エアコン事業者さまとしっかり打ち合わせを行いながら進めました。', '5033', '0', '3689', '2025-05-18 09:17:38', '2026-10-21 12:30:09');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('108', 'ベーカリーレストランの厨房フード設置完了しま', 'ベーカリーレストランの厨房フード設置完了しました。', '<h3>施工内容</h3>\n<p>今回のご依頼は、あらかじめ「フードサイズ指定あり」。<br>見栄え・機能・寸法のバランスを見ながら、しっかりご提案・施工いたしました！</p>\n<p>電気工事・厨房機器業者さまとの密なコミュニケーションで、<br>配線・設置位置・煙の抜けまでスムーズに連携できました。</p>', '福岡県久留米市', '2025-05-25', 'published', 'ベーカリーレストランの厨房フード設置完了しました。｜施工事例【株式会社野田】', '今回のご依頼は、あらかじめ「フードサイズ指定あり」。見栄え・機能・寸法のバランスを見ながら、しっかりご提案・施工いたしました！電気工事・厨房機器業者さまとの密なコミュニケーションで、配線・設置位置・煙の抜けまでスムーズ…', '5042', '0', '3706', '2025-05-25 18:59:17', '2026-10-21 12:30:09');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('109', '福岡市中央区｜居酒屋様の店内排煙機器設置工事', '福岡市中央区｜居酒屋様の店内排煙機器設置工事完了', '<h3>施工内容</h3>\n<p>今回の現場は、ビルが密集する中央区の繁華街で施工しました。<br>本来は屋外に設置する「煙を処理する機械」を、スペースの都合で店内に収める設計に！</p>\n<p>こんなケースに対応：<br>✔︎ 外に機械を置けない<br>✔︎ 周囲への煙の配慮が必要<br>✔︎ 窓を開ける季節でクレームが心配</p>\n<p>お店の構造や立地条件に合わせて、現場ごとに最適な排煙対策をご提案します。</p>', '福岡市中央区', '2025-05-27', 'published', '福岡市中央区｜居酒屋様の店内排煙機器設置工事完了｜施工事例【株式会社野田】', '今回の現場は、ビルが密集する中央区の繁華街で施工しました。本来は屋外に設置する「煙を処理する機械」を、スペースの都合で店内に収める設計に！こんなケースに対応：✔︎外に機械を置けない✔︎周囲への煙の配慮が必要✔︎窓を開け…', '5049', '0', '3724', '2025-05-27 16:18:37', '2026-10-22 02:04:19');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('110', '介護施設様新築工事における換気設備工事（佐賀', '介護施設様新築工事における換気設備工事（佐賀県）', '<h3>施工内容</h3>\n<p>佐賀県内にて新築施工中の介護施設様における、換気設備工事を担当させていただいております。</p>\n<p>建物完成後には目に見えなくなる「仕込み工事」ですが、当社ではこの初期工程こそ最も重要と捉え、精密かつ丁寧な施工を徹底しております。</p>\n<p>例えば、壁内に設置される黒い筒状の部材「スリーブ」は、ダクト配管を正確に通すために不可欠な要素であり、完成後にダクトを確実に接続するため、ミリ単位の精度で設置を行います。この精度が、換気性能の最大化と、快適な空気環境の実現に直結するのです。</p>\n<p>介護施設においては、高水準な空気管理が求められます。当社では、飲食店舗（焼肉店・居酒屋等）やオフィスビル、医療・福祉施設に至るまで、幅広い現場での実績を持ち、環境に応じた最適な排気・換気システムのご提案・施工が可能です。</p>', '佐賀県有田市', '2025-06-09', 'published', '介護施設様新築工事における換気設備工事（佐賀県）｜施工事例【株式会社野田】', '佐賀県内にて新築施工中の介護施設様における、換気設備工事を担当させていただいております。建物完成後には目に見えなくなる「仕込み工事」ですが、当社ではこの初期工程こそ最も重要と捉え、精密かつ丁寧な施工を徹底しております。…', '5061', '0', '3746', '2025-06-09 15:16:27', '2026-10-21 12:30:11');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('111', '福岡市中央区のうなぎ店リニューアル工事', '福岡市中央区のうなぎ店リニューアル工事', '<h3>施工内容</h3>\n<p>今回は、福岡市中央区でリニューアルオープンされる鰻屋様の、とってもユニークな排煙ダクト工事をご紹介します！</p>\n<p>なんとこちらのお店、お客様自身が七輪で鰻を”しゃぶしゃぶ”のように焼いて楽しむ『うなしゃぶ』が名物なんです！</p>\n<p>その新しい食体験と、オーナー様の「うなしゃぶ愛」を広めるお手伝いをするべく、各テーブルの真上に煙を強力に吸い込む「上引きフード」を設置させていただきました。</p>\n<p>和の趣（おもむき）ある店内デザインを邪魔しないよう、見た目にもこだわっています。<br>もちろん、外の排気設備もバッチリです！<br>強力なファンで、お客様が煙を気にすることなく食事と会話に集中できる快適な空間をつくります。</p>', '福岡市中央区', '2025-06-19', 'published', '福岡市中央区のうなぎ店リニューアル工事｜施工事例【株式会社野田】', '今回は、福岡市中央区でリニューアルオープンされる鰻屋様の、とってもユニークな排煙ダクト工事をご紹介します！なんとこちらのお店、お客様自身が七輪で鰻を”しゃぶしゃぶ”のように焼いて楽しむ『うなしゃぶ』が名物なんです！その…', '5074', '0', '3771', '2025-06-19 01:12:39', '2026-10-21 12:30:11');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('112', '糸島市の焼肉店様の結露防止対策工事', '糸島市の焼肉店様の結露防止対策工事', '<h3>施工内容</h3>\n<p>今回は、糸島市にある焼肉店様からご依頼いただいた結露防止対策工事の様子をご紹介します。</p>\n<p>【原因は…エアコンの冷風！】<br>キンキンに冷えたエアコンの風が、排煙ダクトに直接当たっていました。<br>夏場など、室内の熱い空気とダクト表面の温度差で空気中の水分が水滴になり、結露が発生していたんです。</p>\n<p>【対策は…ダクトにしっかりお化粧直し！】<br>そこで、ダクトに専用の断熱材をきっちり巻き付け、結露をシャットアウト！<br>これで、お客様のお料理や服に水滴が落ちる心配もなくなり、カビなどの衛生的な問題も防げます◎</p>', '福岡県糸島市', '2025-06-19', 'published', '糸島市の焼肉店様の結露防止対策工事｜施工事例【株式会社野田】', '今回は、糸島市にある焼肉店様からご依頼いただいた結露防止対策工事の様子をご紹介します。【原因は…エアコンの冷風！】キンキンに冷えたエアコンの風が、排煙ダクトに直接当たっていました。夏場など、室内の熱い空気とダクト表面の…', '5077', '0', '3775', '2025-06-19 01:15:28', '2026-10-21 12:30:11');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('113', '福岡県糟屋郡の焼き鳥店様の排煙ダクト工事', '福岡県糟屋郡の焼き鳥店様の排煙ダクト工事', '<h3>施工内容</h3>\n<p>民家を改装して新規開業された焼き鳥店様の排煙ダクト工事を担当させていただきました！</p>\n<p>住宅地にある店舗様にとって、ご近所への煙対策はとっても重要な課題ですよね。<br>弊社では、豊富な経験と専門知識を活かし、排煙口の向きやダクトの経路を綿密に設計。 煙が周囲に拡散しにくい、最適な排煙計画をご提案・実現いたします！</p>', '福岡県糟屋郡', '2025-06-27', 'published', '福岡県糟屋郡の焼き鳥店様の排煙ダクト工事｜施工事例【株式会社野田】', '民家を改装して新規開業された焼き鳥店様の排煙ダクト工事を担当させていただきました！住宅地にある店舗様にとって、ご近所への煙対策はとっても重要な課題ですよね。弊社では、豊富な経験と専門知識を活かし、排煙口の向きやダクトの…', '5088', '0', '3799', '2025-06-27 17:21:57', '2026-10-21 12:30:11');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('114', '天井下露出ダクト工事かんりょうしました。', '天井下露出ダクト工事完了しました。', '<h3>施工内容</h3>\n<p>天井裏にスペースがない店舗様での排煙ダクト工事事例をご紹介します！<br>天井内に入れられない…そんな時こそ「天井下露出ダクト」の出番です！</p>\n<p>通常、天井裏にダクトを隠す場合、天井高を確保したり、複雑な工事が必要になることがありますが、天井下露出ダクトならその心配もなし！<br>この施工方法を逆手にとることで、工事費用や工期のコスト削減を実現しました。</p>\n<p>さらに、露出ダクトはインダストリアルな雰囲気やモダンな空間演出にも一役買います。磨かれたステンレスのダクトが天井のデザインアクセントにもなっていますね！</p>', '福岡県久留米市', '2025-06-27', 'published', '天井下露出ダクト工事完了しました。｜施工事例【株式会社野田】', '天井裏にスペースがない店舗様での排煙ダクト工事事例をご紹介します！天井内に入れられない…そんな時こそ「天井下露出ダクト」の出番です！通常、天井裏にダクトを隠す場合、天井高を確保したり、複雑な工事が必要になることがありま…', '5093', '0', '3801', '2025-06-27 17:24:13', '2026-10-21 12:30:12');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('115', '天井が低くても大丈夫！-快適な厨房空間を実現', '天井が低くても大丈夫！ 快適な厨房空間を実現', '<h3>施工内容</h3>\n<p>山口県岩国市での施工事例をご紹介します！<br>「天井が低くて、排煙フードの設置は難しいかも…」そんなお悩み、ありませんか？</p>\n<p>ご安心ください！弊社では、天井の低い厨房でも、料理人さんの作業の邪魔にならず、頭が当たらないようにフードを綿密に設計・施工いたします。<br>写真1枚目のように、人の身長と比較しても、その工夫がお分かりいただけるかと思います！</p>\n<p>さらに、今回は排煙効果を最大限に高めるため、近くに給気口も設置しました。<br>これで、煙の排出だけでなく、新鮮な空気の循環もバッチリです！<br>（フード上の隙間は大工工事でしっかり塞ぎ、美観と機能性を両立させます）</p>', '山口県岩国市', '2025-06-27', 'published', '天井が低くても大丈夫！ 快適な厨房空間を実現｜施工事例【株式会社野田】', '山口県岩国市での施工事例をご紹介します！「天井が低くて、排煙フードの設置は難しいかも…」そんなお悩み、ありませんか？ご安心ください！弊社では、天井の低い厨房でも、料理人さんの作業の邪魔にならず、頭が当たらないようにフー…', '5101', '1', '3804', '2025-06-27 17:27:10', '2026-10-21 12:30:12');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('116', '焼肉店での上引きフード総入替施工', '焼肉店での上引きフード総入替施工', '<h3>施工内容</h3>\n<p>長年使われていた鉄工所製造の「うわ引きフード」を、この度、ステンレス製フィルター付き上引きフードへ全取っ替えさせていただきました！</p>\n<p>ご覧いただくと一目瞭然！</p>\n<p>新しいフードは、見た目もスタイリッシュなだけでなく、機能性も格段にアップしています。</p>\n<p>排煙効率の大幅アップ！：お客様もスタッフさんも煙を気にせず、快適にお食事や作業ができる空間に。</p>\n<p>ダクト内への油の流入防止！：フィルターが油をしっかりキャッチ！ダクト内部の汚れを軽減し、メンテナンスの手間とコストを削減します。</p>', '広島県福山市', '2025-07-06', 'published', '焼肉店での上引きフード総入替施工｜施工事例【株式会社野田】', '長年使われていた鉄工所製造の「うわ引きフード」を、この度、ステンレス製フィルター付き上引きフードへ全取っ替えさせていただきました！ご覧いただくと一目瞭然！新しいフードは、見た目もスタイリッシュなだけでなく、機能…', '5103', '0', '3834', '2025-07-06 11:53:19', '2026-10-22 02:04:19');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('117', '世界の●ちゃん様-厨房フード・排煙ファン設置工', '世界の●ちゃん様 厨房フード・排煙ファン設置工事、完了！', '<h3>施工内容</h3>\n<p>あの手羽先で有名な「世界の●ちゃん」様の厨房フード新設工事と、強力な排煙ファンの設置工事が完了しました！</p>\n<p>今回のプロジェクトでは、排煙ファン（写真1枚目）のモーター横にあるVベルトを囲むカバーに、当社の特注品を採用いただきました。</p>\n<p>純正品ではなく特注カバーを新設したのは、雨や強い日差しによるベルトの劣化を防ぐため。Vベルトが劣化して切れてしまうと、営業がストップしてしまうという大きなリスクがあります。そこで、当社独自の調査で通常の3倍の強度（当社調べ）を持つ特注カバーで対策を行いました。</p>\n<p>このような細部へのこだわりと、長年の経験に裏打ちされた設計力が当社の強みです。お客様の大切な厨房設備が、長く安全に稼働できるよう、細部にわたる配慮を惜しみません。</p>', '福岡県北九州市', '2025-07-15', 'published', '世界の●ちゃん様 厨房フード・排煙ファン設置工事、完了！｜施工事例【株式会社野田】', 'あの手羽先で有名な「世界の●ちゃん」様の厨房フード新設工事と、強力な排煙ファンの設置工事が完了しました！今回のプロジェクトでは、排煙ファン（写真1枚目）のモーター横にあるVベルトを囲むカバーに、当社の特注品を採用いただ…', '5120', '0', '3857', '2025-07-15 11:03:42', '2026-10-21 12:30:13');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('118', '唐人町商店街テナント様-ダクト工事', '唐人町商店街テナント様 ダクト工事', '<h3>施工内容</h3>\n<p>今回は、唐人町商店街内のテナント様で実施したダクト工事の様子をご紹介します！</p>\n<p>集合店舗という特性上、完璧な防火対策が必須となる天井内のダクト。<br>弊社では、お客様の安全を第一に考え、断熱材を隙間なくしっかりと施工しています</p>\n<p>実は今回の工事では、ダクトの壁貫通部に制約があり、適切なダクト径を確保することが難しいという課題がありました。しかし、ご安心ください！</p>\n<p>そこで活躍したのが「高風量フィルター」です！ 見た目は同じように見えても、その性能は段違い。「見た目が同じでも出来が違うんです。」の言葉通り、このフィルターを導入することで、限られたスペースでも十分な換気能力を確保し、課題を解決することができました。</p>', '福岡市中央区', '2025-07-15', 'published', '唐人町商店街テナント様 ダクト工事｜施工事例【株式会社野田】', '今回は、唐人町商店街内のテナント様で実施したダクト工事の様子をご紹介します！集合店舗という特性上、完璧な防火対策が必須となる天井内のダクト。弊社では、お客様の安全を第一に考え、断熱材を隙間なくしっかりと施工しています実…', '5125', '0', '3859', '2025-07-15 11:06:26', '2026-10-21 12:30:13');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('119', '火災リスクを徹底排除！究極の防火装置「グリス', '火災リスクを徹底排除！究極の防火装置「グリスセパレーター」設置工事', '<h3>施工内容</h3>\n<p>今回は、西中洲の集合ビルにある都城の名店、地鶏焼き店様にご依頼いただき、防火対策の最前線となる「グリスセパレーター」の取り付け工事を行いました！</p>\n<p>「グリスセパレーター」とは、「安全装置の最高峰」と呼ぶにふさわしい、消防法上でも最高の防火装置とされる優れものです。</p>\n<p>通常の油取りフィルターに常時水を噴霧することで、フィルター内の温度を常に低く保ちます。万が一、火の粉が上がったとしても瞬時に鎮火する機能を持っており、厨房火災のリスクを大幅に軽減します！</p>\n<p>特に、火力の強い料理を提供する焼き鳥屋さん、中華料理店さん、薪料理屋さんなど、火を扱う機会の多い飲食店様には、ぜひ導入をご検討いただきたい設備です。</p>\n<p>オープン前の設計段階から、プロの目線で最適なダクトプランをご提案し、あらゆる業態での施工実績を活かし、店舗の特性に合わせた確かな設計・施工をお約束します。</p>', '福岡市中央区', '2025-07-22', 'published', '火災リスクを徹底排除！究極の防火装置「グリスセパレーター」設置工事｜施工事例【株式会社野田】', '今回は、西中洲の集合ビルにある都城の名店、地鶏焼き店様にご依頼いただき、防火対策の最前線となる「グリスセパレーター」の取り付け工事を行いました！「グリスセパレーター」とは、「安全装置の最高峰」と呼ぶにふさわしい、消防法…', '5129', '0', '3870', '2025-07-22 09:06:07', '2026-10-21 12:30:13');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('120', 'ダクト交換で排煙能力と安全性を劇的改善', 'ダクト交換で排煙能力と安全性を劇的改善', '<h3>施工内容</h3>\n<p>今回は、排煙不足のご相談で訪問させていただいた飲食店様のダクト交換事例です。</p>\n<p>現地調査の結果、油汚れがひどく、ダクト自体の劣化も進行していることを確認。そこで、配管の取り替えをご提案させていただきました。</p>\n<p>ダクトを開けてみると…<br>やはり想像以上に油汚れがべっとりと付着していました。「たいへんだ！」という声が聞こえてきそうなくらいの状況でした。</p>\n<p>このような状態では、排煙能力が著しく低下するだけでなく、ダクト内に溜まった油が火種となり、火災のリスクが非常に高まります。</p>\n<p>今回のダクト交換により、排煙能力が劇的に向上したのはもちろんのこと、火災防止においても適切な時期に工事ができて本当によかったと感じています。</p>', '福岡市中央区', '2025-07-28', 'published', 'ダクト交換で排煙能力と安全性を劇的改善｜施工事例【株式会社野田】', '今回は、排煙不足のご相談で訪問させていただいた飲食店様のダクト交換事例です。現地調査の結果、油汚れがひどく、ダクト自体の劣化も進行していることを確認。そこで、配管の取り替えをご提案させていただきました。ダクトを開けてみ…', '5131', '0', '3891', '2025-07-28 09:36:27', '2026-10-21 12:30:13');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('121', 'うどん屋さん改修工事！快適厨房へリニューアル', 'うどん屋さん改修工事！快適厨房へリニューアル', '<h3>施工内容</h3>\n<p>うどん屋さんにて改修工事を行い、厨房フードの新設工事が完了しました！</p>\n<p>今回の改修では、特に「メンテナンスのしやすさ」を重視し、耐火耐熱フード専用ライトを設置いたしました。</p>\n<p>この専用ライトは、熱や油に強く、日々の清掃や電球交換といったメンテナンスが非常に簡単に行える設計になっています。忙しい厨房環境において、こういった細かな配慮が作業効率の向上に繋がると考えています。</p>\n<p>見た目の美しさはもちろんのこと、機能性と安全性、そして長期的な運用コストまで見据えた最適な厨房設備をご提案しています。</p>', '福岡市中央区', '2025-08-02', 'published', 'うどん屋さん改修工事！快適厨房へリニューアル｜施工事例【株式会社野田】', 'うどん屋さんにて改修工事を行い、厨房フードの新設工事が完了しました！今回の改修では、特に「メンテナンスのしやすさ」を重視し、耐火耐熱フード専用ライトを設置いたしました。この専用ライトは、熱や油に強く、日々の清掃や電球交…', '5145', '0', '3923', '2025-08-02 22:13:34', '2026-10-21 12:30:14');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('122', '大手回転寿司チェーン様のダクト工事を担当しま', '大手回転寿司チェーン様のダクト工事を担当しました', '<h3>施工内容</h3>\n<p>さすが大手チェーン様、その吸排気計画はまさに完璧✨ 現場監督様との密な連携と協力のもと、安全かつ迅速な施工を行うことができました。バッチリ仕上げましたよ！</p>\n<p>大規模なプロジェクトにおいても、計画段階から施工まで、お客様と一体となって最高の環境を作り上げます。飲食店にとって、厨房の吸排気は美味しさや快適さだけでなく、安全面においても非常に重要です。</p>', '福岡市中央区', '2025-08-18', 'published', '大手回転寿司チェーン様のダクト工事を担当しました｜施工事例【株式会社野田】', 'さすが大手チェーン様、その吸排気計画はまさに完璧✨現場監督様との密な連携と協力のもと、安全かつ迅速な施工を行うことができました。バッチリ仕上げましたよ！大規模なプロジェクトにおいても、計画段階から施工まで、お客様と一体…', '5152', '0', '3961', '2025-08-18 10:50:12', '2026-10-21 12:30:14');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('123', '行橋市テイクアウト唐揚げ店！プレハブ改修で快', '行橋市テイクアウト唐揚げ店！プレハブ改修で快適厨房が完成', '<h3>施工内容</h3>\n<p>今回は、行橋市の住宅地にあるプレハブを利用した、唐揚げテイクアウト専門店の厨房改修工事をご紹介します！</p>\n<p>限られたスペースを最大限に活かし、フライヤーフードの設置を行いました。</p>\n<p>【当社の強み！】<br>電気工事は、電気工事士の資格を持つ自社社員が2次側施工を担当しました。これにより、外部への発注費用を抑えつつ、安全で迅速な施工を実現！お客様のコスト削減にも貢献できました（写真1枚目）</p>\n<p>プレハブの特性に合わせた最適な排気計画で、唐揚げの美味しい香りはそのままに、煙や油をしっかり排出します。</p>\n<p>テイクアウト専門店はもちろん、煙の多い焼肉店様や居酒屋様など、あらゆる飲食店の厨房設備のご相談を承っております。</p>', '福岡県行橋市', '2025-08-18', 'published', '行橋市テイクアウト唐揚げ店！プレハブ改修で快適厨房が完成｜施工事例【株式会社野田】', '今回は、行橋市の住宅地にあるプレハブを利用した、唐揚げテイクアウト専門店の厨房改修工事をご紹介します！限られたスペースを最大限に活かし、フライヤーフードの設置を行いました。【当社の強み！】電気工事は、電気工事士の資格を…', '5163', '0', '3964', '2025-08-18 10:53:23', '2026-10-22 02:04:19');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('124', '近隣トラブル解消！焼き鳥屋さんに消煙機導入！', '近隣トラブル解消！焼き鳥屋さんに消煙機導入！', '<h3>施工内容</h3>\n<p>今回は、近隣のマンションからの煙の苦情にお悩みだった焼き鳥店様での解決事例をご紹介します！</p>\n<p>ご相談当初、管理会社様からは排煙口の向きを変えるご提案があったそうです。しかし私たちは、煙の吹き出し方を変えるだけでなく、煙そのものを少なくする根本的な解決策として「消煙機」の設置をご提案しました。</p>\n<p>建物にぴったりと寄り添うように設置された消煙機。これにより、排出される煙が大幅に削減され、周囲の環境に配慮したクリーンな排気が可能になりました！</p>\n<p>結果、見事、近隣からのクレームは一切無くなりました！</p>', '福岡市早良区', '2025-08-18', 'published', '近隣トラブル解消！焼き鳥屋さんに消煙機導入！｜施工事例【株式会社野田】', '今回は、近隣のマンションからの煙の苦情にお悩みだった焼き鳥店様での解決事例をご紹介します！ご相談当初、管理会社様からは排煙口の向きを変えるご提案があったそうです。しかし私たちは、煙の吹き出し方を変えるだけでなく、煙その…', '5168', '0', '3967', '2025-08-18 10:56:28', '2026-10-21 12:30:14');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('125', '人気スーパー内に新店舗！テナント増設の排煙工', '人気スーパー内に新店舗！テナント増設の排煙工事', '<h3>施工内容</h3>\n<p>今回は、テレビでもお馴染みのスーパー「ダイキョーバリュー」様のテナント増設に伴う、パン屋さんのフード設置工事を担当させていただきました！</p>\n<p>「お惣菜のチャンピオン」として地域に愛されるスーパー内に、新しいパン屋さんができるなんて、どんな美味しいパンが味わえるか今から楽しみです！</p>\n<p>厨房内に新たに設置されたピカピカのフードと、屋外に設置された吸排気ファン。</p>\n<p>テナントの増設や業態変更に伴う排煙設備の設置は、既存の建物の構造や環境に合わせた綿密な計画が必要です。</p>\n<p>私たちは、飲食店の特性に合わせた最適な排煙システムをご提案。パン屋さんのオーブンから出る熱や蒸気を効率よく排出し、快適な厨房環境と店内の空気質を保つお手伝いをいたします。</p>', '福岡県糟屋郡', '2025-08-18', 'published', '人気スーパー内に新店舗！テナント増設の排煙工事｜施工事例【株式会社野田】', '今回は、テレビでもお馴染みのスーパー「ダイキョーバリュー」様のテナント増設に伴う、パン屋さんのフード設置工事を担当させていただきました！「お惣菜のチャンピオン」として地域に愛されるスーパー内に、新しいパン屋さんができる…', '5174', '0', '3969', '2025-08-18 10:58:53', '2026-10-21 12:30:14');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('126', '焼肉店の命を守る！床下ダクト点検口と二重の防', '焼肉店の命を守る！床下ダクト点検口と二重の防火対策', '<h3>施工内容</h3>\n<p>今回は、中洲焼肉店様の「無煙ロースター【仕込】」の様子をご紹介します！</p>\n<p>（写真１枚目をご覧ください！）</p>\n<p>特に注目いただきたいのが、写真の青い円で囲んだ部分！</p>\n<p>これは、床下内ダクト点検口です！</p>\n<p>「なんでこんなところに？」と思われた方もいらっしゃるかもしれませんね。実はこれ、焼肉店様にとって、とっても大切な「安心」を守るための設備なんです！</p>\n<p>この点検口の主な目的は、大きく２つ！</p>\n<p>定期的なダクト内廃油清掃を円滑に！：数年に一度の清掃作業をスムーズに行い、排煙効率を維持します。</p>\n<p>万が一の火災時、消火作業を迅速に！：ダクト内部で火災が発生した場合に、ここから消火活動を効率的に進めることができます。</p>\n<p>さらに、オレンジの円で囲んだ2本の筒は「防火ダンパー」です。ロースター内の防火ダンパーで火災予防はバッチリですが、<strong>「念には念を入れて」</strong>の床下内点検口設置なんです。</p>\n<p>この細やかな配慮と、リスク管理への徹底したこだわりこそが、私たちの焼肉設備20年の技術と経験が光るポイントです！</p>', '福岡市博多区', '2025-09-01', 'published', '焼肉店の命を守る！床下ダクト点検口と二重の防火対策｜施工事例【株式会社野田】', '今回は、中洲焼肉店様の「無煙ロースター【仕込】」の様子をご紹介します！（写真１枚目をご覧ください！）特に注目いただきたいのが、写真の青い円で囲んだ部分！これは、床下内ダクト点検口です！「なんでこんなところに？」と思われ…', '5178', '0', '4022', '2025-09-01 09:16:16', '2026-10-22 02:05:35');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('127', '北九州市の老舗の味はそのままに！-店内の煙もリ', '北九州市の老舗の味はそのままに！ 店内の煙もリニューアル工事で改善！', '<h3>施工内容</h3>\n<p>「最近、店内に煙がこもるようになってきた…」「排煙の効きが悪くて困っている…」</p>\n<p>そんなお悩み、ありませんか？</p>\n<p>今回は、北九州の老舗餃子屋様からファンの経年劣化に関するお問い合わせをいただき、排気ファンの交換工事を実施しました！</p>\n<p>長年、美味しい餃子を提供されてきた厨房も、やはり排気ファンは経年とともに性能が低下してしまいます。 店内に煙が充満し、お客様にもご迷惑がかかってしまっていたそうです。</p>\n<p>そこで私たち「野田」は、まず既存のフードの大きさから必要な排煙量を綿密に計算し、お店の規模と使用状況に最適な新しい排気ファンを選定！</p>\n<p>既存ダクトへの接続もスムーズに行い、効率的な排気システムを再構築しました。</p>\n<p>新しいファンに交換したことで、店内の煙は劇的に改善！</p>\n<p>お客様にはこれまでと変わらず、快適な空間で老舗の絶品餃子を味わっていただけるようになりました！</p>', '北九州市八幡西区', '2025-09-01', 'published', '北九州市の老舗の味はそのままに！ 店内の煙もリニューアル工事で改善！｜施工事例【株式会社野田】', '「最近、店内に煙がこもるようになってきた…」「排煙の効きが悪くて困っている…」そんなお悩み、ありませんか？今回は、北九州の老舗餃子屋様からファンの経年劣化に関するお問い合わせをいただき、排気ファンの交換工事を実施しまし…', '5200', '0', '4025', '2025-09-01 09:19:34', '2026-10-22 02:04:19');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('128', '安全性と静音性を両立！人気焼き鳥チェーン排煙', '安全性と静音性を両立！人気焼き鳥チェーン排煙工事完了', '<h3>施工内容</h3>\n<p>今回は、北九州・小倉魚町で人気焼き鳥チェーン「鳥貴族」様の外部ダクト工事事例をご紹介します！</p>\n<p>お客様からのご要望で、角ダクトの強度指定がありました。<br>そこで私たちは、写真にあるように、ダクトに「リブ（強度が増す線）」を入れて制作しました！</p>\n<p>このリブ入りダクトのメリットは、ただ頑丈になるだけではありません。</p>\n<p>安全性の向上：強度が格段に増すことで、外部設置における安全対策がバッチリになります。</p>\n<p>騒音対策：ダクト特有のファンからの微振動が軽減され、周辺への騒音トラブルを防ぐ一助になります。</p>\n<p>人気焼き鳥店だからこそ、お客様の食の安全と、近隣住民への配慮は欠かせません。<br>私たちは、単に煙を排出するだけでなく、このような細かな部分にまでこだわって施工しています！</p>', '北九州市小倉北区', '2025-09-09', 'published', '安全性と静音性を両立！人気焼き鳥チェーン排煙工事完了｜施工事例【株式会社野田】', '今回は、北九州・小倉魚町で人気焼き鳥チェーン「鳥貴族」様の外部ダクト工事事例をご紹介します！お客様からのご要望で、角ダクトの強度指定がありました。そこで私たちは、写真にあるように、ダクトに「リブ（強度が増す線）」を入れ…', '5208', '0', '4043', '2025-09-09 22:58:28', '2026-10-21 12:30:15');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('129', '福岡の人気ラーメン店！大風量対応の巨大フード', '福岡の人気ラーメン店！大風量対応の巨大フードを設置しました。', '<h3>施工内容</h3>\n<p>今回は、福岡を代表する人気ラーメン店「いちむじん」様での排煙ダクト工事事例をご紹介します！</p>\n<p>ラーメン店と言えども、厨房から出る熱気や蒸気はかなりのもの。特に人気店では、より高い排煙効率が求められます。</p>\n<p>そのため、今回は通常のラーメン店より一回り大きい「巨大フード」を設置しました！<br>さらに、この巨大フードに合わせて、より大風量に対応したファンとグリースフィルターを選定し、快適な厨房環境をサポートします。</p>', '福岡市中央区', '2025-09-22', 'published', '福岡の人気ラーメン店！大風量対応の巨大フードを設置しました。｜施工事例【株式会社野田】', '今回は、福岡を代表する人気ラーメン店「いちむじん」様での排煙ダクト工事事例をご紹介します！ラーメン店と言えども、厨房から出る熱気や蒸気はかなりのもの。特に人気店では、より高い排煙効率が求められます。そのため、今回は通常…', '5213', '0', '4061', '2025-09-22 18:43:12', '2026-10-21 12:30:16');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('130', 'シックな店内をより美しく！-デザインにもこだわ', 'シックな店内をより美しく！ デザインにもこだわった排煙フードを設置', '<h3>施工内容</h3>\n<p>今回は、内装デザインにこだわりのある店舗様での施工事例をご紹介します。<br>「お店の雰囲気を壊さずに、機能的な排煙設備をつけたい…」そんな想いに応えるべく、デザイン性を重視したフードを制作しました！</p>\n<p>お客様のご要望で、シックな店内に合うよう、カラー鋼板でフードを制作。<br>さらに、吸気口もフードと統一感のある黒を選定しました。<br>機能はもちろんのこと、内装に溶け込むようなスタイリッシュなデザインに仕上がっています。</p>\n<p>黒で統一されたフードと吸気口が、店内の洗練された雰囲気をさらに引き立てています。まるで最初からそこにあったかのような美しい仕上がりです。</p>\n<p>排煙ダクトは、煙を吸うだけでなく、お店の雰囲気を左右する「インテリア」の一部でもあります。<br>特に、焼肉店や居酒屋、焼き鳥店など、煙の多い業態でも、デザイン性を妥協する必要はありません。</p>', '福岡市博多区', '2025-10-06', 'published', 'シックな店内をより美しく！ デザインにもこだわった排煙フードを設置｜施工事例【株式会社野田】', '今回は、内装デザインにこだわりのある店舗様での施工事例をご紹介します。「お店の雰囲気を壊さずに、機能的な排煙設備をつけたい…」そんな想いに応えるべく、デザイン性を重視したフードを制作しました！お客様のご要望で、シックな…', '5221', '0', '4081', '2025-10-06 14:31:00', '2026-10-21 12:30:16');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('131', '落語カフェの換気工事！新鮮な外気を取り入れ、', '落語カフェの換気工事！新鮮な外気を取り入れ、快適な空間を創造しました。', '<h3>施工内容</h3>\n<p>今回は、ユニークな業態の「落語カフェ」様での換気工事事例をご紹介します！</p>\n<p>換気というと、店内の空気を外に「吐き出す」ことに注目されがちですよね。ですが、今回は収容人数が多くなることを考慮し、外から新鮮な空気を取り入れるために、吸気用の機械ファンを導入しました！</p>\n<p>天井に設置された吸気口から外のきれいな空気を効率よく取り込むことで、お客様はいつでも快適に落語やカフェタイムを楽しめます。</p>\n<p>私たちの仕事は、単に煙や臭いを外に出すことだけではありません。<br>お店のコンセプトや利用状況に合わせて、お客様が心からくつろげる「空気環境」を設計することも、重要な役割だと考えています。</p>', '福岡市博多区', '2025-10-06', 'published', '落語カフェの換気工事！新鮮な外気を取り入れ、快適な空間を創造しました。｜施工事例【株式会社野田】', '今回は、ユニークな業態の「落語カフェ」様での換気工事事例をご紹介します！換気というと、店内の空気を外に「吐き出す」ことに注目されがちですよね。ですが、今回は収容人数が多くなることを考慮し、外から新鮮な空気を取り入れるた…', '5226', '0', '4083', '2025-10-06 14:32:44', '2026-10-21 12:30:16');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('132', 'お弁当チェーン様ファン定期交換', 'お弁当チェーン様ファン定期交換', '<h3>施工内容</h3>\n<p>排気ファンは、お店の「心臓部」と言っても過言ではありません。<br>排煙機能が低下したり、急にファンが動かなくなってしまうと、営業停止の危機に直面してしまいます。</p>\n<p>定期的に排煙ファンを交換することで、「突然動かなくなった！」という緊急事態の対策を講じています。さすが、日本を代表する「ほっと」な会社様の徹底したリスクマネジメントです！施設完備もばっちりくお弁当がとても美味しいので、「もっと」食べたくなります！</p>\n<p>ファンが完全に故障する前に交換することは、結果的に長期的なコスト削減と安定した店舗運営につながります。</p>\n<p>「最近、排煙の効きが悪い気がする…」<br>「うちのファン、何年交換してないかな…」<br>そんなお悩みをお持ちの飲食店オーナー様、ぜひ私たちにご相談ください！</p>', '福岡県粕屋郡', '2025-10-21', 'published', 'お弁当チェーン様ファン定期交換｜施工事例【株式会社野田】', '排気ファンは、お店の「心臓部」と言っても過言ではありません。排煙機能が低下したり、急にファンが動かなくなってしまうと、営業停止の危機に直面してしまいます。定期的に排煙ファンを交換することで、「突然動かなくなった！」とい…', '5233', '0', '4110', '2025-10-21 13:09:22', '2026-10-22 02:04:19');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('133', '大規模工場様の清潔と安全を極めた特注排煙シス', '大規模工場様の清潔と安全を極めた特注排煙システムを導入', '<h3>施工内容</h3>\n<p>今回は、業務拡張で焼き物製造を始められるOEM食品会社様にご依頼いただいた排煙システム構築です！</p>\n<p>食品工場において、清潔と安全は最重要課題。私たちは、以下の3つのこだわり対策を実現しました！</p>\n<p>【毎日の洗浄対策】<br>フード内を毎日洗浄できるよう、二重天井（勾配つき）構造で設計。さらに、清掃時の水飛散を防ぐためのビニールカーテンも合わせて設置しました！</p>\n<p>【吸排気の完璧バランス】<br>厨房の空気環境を最適化するため、吸排気のバランスを徹底的に調整。強力な循環力で、調理場の熱気や煙を瞬時に捕集します。</p>\n<p>【安心の強度設計】<br>吸気フィルター清掃のためにフード上に乗ることを想定し、吊り強度を5倍に強化し、振れ留めを設置しました。これで「　　人乗っても大丈夫！」な、高い安全性を確保しています！</p>\n<p>衛生管理が厳しく、長時間稼働が求められる食品製造工場様の排煙設備こそ、当社の卓越した設計力と技術力が活きます。</p>\n<p>飲食店だけでなく、食品工場やOEM製造会社のオーナー様、衛生管理と生産性向上を実現する排煙システムは私たちにお任せください！</p>', '広島県福山市', '2025-10-21', 'published', '大規模工場様の清潔と安全を極めた特注排煙システムを導入｜施工事例【株式会社野田】', '今回は、業務拡張で焼き物製造を始められるOEM食品会社様にご依頼いただいた排煙システム構築です！食品工場において、清潔と安全は最重要課題。私たちは、以下の3つのこだわり対策を実現しました！【毎日の洗浄対策】フード内を毎…', '5237', '0', '4112', '2025-10-21 13:11:41', '2026-10-21 12:30:17');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('134', '焼肉もカレーも提供する都心ビルの密集地のハイ', '焼肉もカレーも提供する都心ビルの密集地のハイブリット店舗', '<h3>施工内容</h3>\n<p>福岡・赤坂の名店が清川に別邸として誕生！昼はカレー、夜は焼肉を営むハイブリッド店舗様の排煙工事事例です。</p>\n<p>都心部のビル密集地では、隣の建物との境界の幅（スペース）が非常に小さいという、排煙ダクト工事の大きな課題があります。<br>本来、排気口には丸ダクトを使いたいところですが、今回はその狭さゆえに、当社の独自の角排気口が参上しました！</p>\n<p>狭いスペースでも効率よく排気できるように設計・設置することで、近隣への配慮と高い排煙能力を両立させます。</p>', '福岡市中央区', '2025-11-06', 'published', '焼肉もカレーも提供する都心ビルの密集地のハイブリット店舗｜施工事例【株式会社野田】', '福岡・赤坂の名店が清川に別邸として誕生！昼はカレー、夜は焼肉を営むハイブリッド店舗様の排煙工事事例です。都心部のビル密集地では、隣の建物との境界の幅（スペース）が非常に小さいという、排煙ダクト工事の大きな課題があります…', '5247', '0', '4144', '2025-11-06 10:40:37', '2026-10-22 02:05:35');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('135', '海沿いの店舗も安心！強力ファン交換と塩害対策', '海沿いの店舗も安心！強力ファン交換と塩害対策カバー設置', '<h3>施工内容</h3>\n<p>今回は、ファンの老朽化に伴い、ファン交換工事を実施した事例をご紹介します。<br>特に今回は、海に近い立地（下関）ということで、塩害対策も万全に行いました！</p>\n<p>たくさんのお客様が訪れる餃子の王将様の古いファンから、とにかく煙を吸い込むことを最優先に考えた新しいファンに交換し、排煙能力を大幅にアップさせました。さらに、海からの潮風による腐食を防ぐため、塩害対策カバーを設置！</p>\n<p>海沿いの店舗では、排気ファンやダクトは塩分によって想像以上に早く劣化・腐食が進んでしまいます。そのまま放置すると、急な故障につながり、営業に大きな影響が出かねません。当社は、単にファンを交換するだけでなく、立地環境（海沿い、ビル密集地など）を考慮した最適な設備保護対策をご提案します。</p>', '山口県下関市', '2025-11-06', 'published', '海沿いの店舗も安心！強力ファン交換と塩害対策カバー設置｜施工事例【株式会社野田】', '今回は、ファンの老朽化に伴い、ファン交換工事を実施した事例をご紹介します。特に今回は、海に近い立地（下関）ということで、塩害対策も万全に行いました！たくさんのお客様が訪れる餃子の王将様の古いファンから、とにかく煙を吸い…', '5254', '0', '4146', '2025-11-06 10:42:58', '2026-10-21 12:30:17');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('136', 'オールステンレスの2代目消煙機を設置完了！', 'オールステンレスの2代目消煙機を設置完了！', '<h3>施工内容</h3>\n<p>今回は、飲食店様の排煙ダクト工事で、2代目消煙機（排煙脱臭装置）の設置が完了した事例をご紹介します！</p>\n<p>ご覧ください、このオールステンレスの輝き！<br>機能性はもちろん、外観のかっこよさも抜群です。オールステンレス製は耐久性にも優れており、長期間にわたってお店の排煙を強力にサポートします。</p>\n<p>消煙機は、排気される煙や臭いを大幅に軽減し、特に住宅地やビル密集地にある店舗の近隣対策に欠かせない設備です。<br>周辺住民の方々とのトラブルを未然に防ぎ、お店の評判を守る「守護神」と言えます。</p>', '福岡市中央区', '2025-11-06', 'published', 'オールステンレスの2代目消煙機を設置完了！｜施工事例【株式会社野田】', '今回は、飲食店様の排煙ダクト工事で、2代目消煙機（排煙脱臭装置）の設置が完了した事例をご紹介します！ご覧ください、このオールステンレスの輝き！機能性はもちろん、外観のかっこよさも抜群です。オールステンレス製は耐久性にも…', '5260', '0', '4148', '2025-11-06 10:44:37', '2026-10-21 12:30:17');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('137', '北九州黒崎に新店！鳥貴族様の大型角ダクト設計', '北九州黒崎に新店！鳥貴族様の大型角ダクト設計事例！', '<h3>施工内容</h3>\n<p>今回は、お馴染みの鳥貴族様（北九州黒崎の新店）の排煙ダクト工事事例をご紹介します！</p>\n<p>大型飲食店である鳥貴族様のような店舗では、非常に大きな大排煙量に対応する必要があります。そのため、私たちは大型の角ダクトを設計・施工しました！</p>\n<p>大型角ダクトのメリットはたくさんあります！</p>\n<p>騒音の低減: 小さいダクトと比べて空気抵抗が少ないため、静かな環境づくりに貢献します。</p>\n<p>ファンの負担低減: 抵抗が減ることで、ファンに負荷がかかりにくく、設備の寿命を延ばします。</p>\n<p>将来的な拡張性: 将来メニューが増えてフードが必要になった場合でも、追加が容易になります。</p>\n<p>排煙ダクトは、初期投資だけでなく、長期的な店舗運営コストとお客様の快適性に大きく関わります。</p>', '北九州市八幡西区', '2025-11-25', 'published', '北九州黒崎に新店！鳥貴族様の大型角ダクト設計事例！｜施工事例【株式会社野田】', '今回は、お馴染みの鳥貴族様（北九州黒崎の新店）の排煙ダクト工事事例をご紹介します！大型飲食店である鳥貴族様のような店舗では、非常に大きな大排煙量に対応する必要があります。そのため、私たちは大型の角ダクトを設計・施工しま…', '5266', '0', '4186', '2025-11-25 11:51:53', '2026-10-21 12:30:18');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('138', '排煙フードも内装の一部に！高級感あふれる上引', '排煙フードも内装の一部に！高級感あふれる上引きフードの特注塗装！', '<h3>施工内容</h3>\n<p>今回は、「上引きフードにも高級感を」というオーナー様の強いご要望にお応えした特注事例をご紹介します！ 排煙設備にも、お店のコンセプトを反映させる。これこそ、新たな名店の予感です。</p>\n<p>画像をご覧ください。通常のシルバーのダクトではなく、本体をシックで重厚感のあるゴールデンブラウンに特殊塗装しました。 さらに、ただ色を塗るだけでなく、<strong>梨地仕上げ（ナシジ処理）</strong>という表面加工を施すことで、質感まで追求。照明に映える高級感のある仕上がりとなりました。</p>\n<p>お客様のこだわりは、お皿から料理まで細部にわたり徹底されています。 私たちもその想いを共有し、排煙ダクトという設備を、お店の「顔」となる内装の一部としてデザインしました。</p>', '福岡市中央区', '2025-11-25', 'published', '排煙フードも内装の一部に！高級感あふれる上引きフードの特注塗装！｜施工事例【株式会社野田】', '今回は、「上引きフードにも高級感を」というオーナー様の強いご要望にお応えした特注事例をご紹介します！排煙設備にも、お店のコンセプトを反映させる。これこそ、新たな名店の予感です。画像をご覧ください。通常のシルバーのダクト…', '5277', '0', '4188', '2025-11-25 11:53:50', '2026-10-22 02:05:35');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('139', '大分の新進気鋭の焼肉店様から「煙をどうにか」', '大分の新進気鋭の焼肉店様から「煙をどうにか」とご相談！', '<h3>施工内容</h3>\n<p>大分で話題の新進気鋭の焼肉店様より、「店内の煙をどうにかしてほしい」というご相談をいただきました。 当社は一言、「御意！」とお応えし、即座に最適な排煙システムをご提案・施工いたしました。</p>\n<p>画像をご覧ください。お客様のテーブルごとに設置された上引きフードが、発生した煙を強力に吸引し、店内の空気をクリーンに保ちます。 これにより、お客様には最高の食事体験を、スタッフ様には快適な作業環境を提供します。</p>\n<p>焼肉店にとって、煙対策は顧客満足度を大きく左右する重要な要素です。 当店は内装にも細部にまでこだわりが感じられる素敵な空間です。その雰囲気を台無しにしないよう、機能性はもちろん、デザインにも配慮した美しいダクト設置を実現しました。</p>', '大分県豊後高田市', '2025-12-19', 'published', '大分の新進気鋭の焼肉店様から「煙をどうにか」とご相談！｜施工事例【株式会社野田】', '大分で話題の新進気鋭の焼肉店様より、「店内の煙をどうにかしてほしい」というご相談をいただきました。当社は一言、「御意！」とお応えし、即座に最適な排煙システムをご提案・施工いたしました。画像をご覧ください。お客様のテーブ…', '5293', '0', '4229', '2025-12-19 17:11:57', '2026-10-21 12:30:19');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('140', '西区野方に『大衆焼肉-かばろ』様の工事完了しま', '西区野方に『大衆焼肉 かばろ』様の工事完了しました。', '<h3>施工内容</h3>\n<p>福岡市西区野方に、地元密着かつ本格派の焼肉店『大衆焼肉 かばろ』様がオープンしました！ 今回はこちらの店舗様の排煙ダクト工事・換気設備施工を担当させていただきました。<br><br> 施工のポイント 焼肉店といえば、やはり「煙」との戦いです。 美味しいお肉を快適な空間で楽しんでいただくため、店内の吸気・排気のバランスを緻密に計算し、強力かつ効率的な排煙システムを構築しました。<br><br> お店の魅力 「リーズナブルで質の良いお肉」をコンセプトにされており、壱岐団地エリアの方はもちろん、遠方から足を運ぶ価値大のアドレスです。</p>', '福岡市西区', '2025-12-19', 'published', '西区野方に『大衆焼肉 かばろ』様の工事完了しました。｜施工事例【株式会社野田】', '福岡市西区野方に、地元密着かつ本格派の焼肉店『大衆焼肉かばろ』様がオープンしました！今回はこちらの店舗様の排煙ダクト工事・換気設備施工を担当させていただきました。施工のポイント焼肉店といえば、やはり「煙」との戦いです。…', '5301', '0', '4232', '2025-12-19 17:15:59', '2026-10-21 12:30:19');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('141', '志免町に現れた話題店！『手作りハンバーグ-きり', '志免町に現れた話題店！『手作りハンバーグ きりん』様 施工', '<h3>施工内容</h3>\n<p>福岡のグルメシーンを賑わすビッグニュース！ 中洲川端の某有名ラーメン店がプロデュースするハンバーグ専門店『手作りハンバーグ きりん』様（きりんのハンバーグ）が志免町にオープンされました！</p>\n<p> 凄まじい集客力！ オープン日の11/21から、連日大行列とのこと！私もチャレンジしましたが、大盛況で断念…！これは福岡に来たら、件の天ぷらやうどんの前にまず訪問すべき超人気店になりそうです！全国の食通の皆様、要チェックです！</p>\n<p>私たちの仕事（厨房排気ダクト工事） ハンバーグの調理も、大量の肉を焼くため、煙や油煙、そして熱気が多く発生します。 今回は、厨房内の高出力な熱源に対応するため、大型のステンレス製厨房フードと大口径の排気ダクトを一式施工させていただきました。</p>', '福岡県粕屋郡', '2025-12-19', 'published', '志免町に現れた話題店！『手作りハンバーグ きりん』様 施工｜施工事例【株式会社野田】', '福岡のグルメシーンを賑わすビッグニュース！中洲川端の某有名ラーメン店がプロデュースするハンバーグ専門店『手作りハンバーグきりん』様（きりんのハンバーグ）が志免町にオープンされました！凄まじい集客力！オープン日の11/2…', '5313', '0', '4235', '2025-12-19 17:17:56', '2026-10-22 02:04:19');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('142', '【解決事例】都心部の煙・油煙問題に終止符！「', '【解決事例】都心部の煙・油煙問題に終止符！「野田の消煙機」設置', '<h3>施工内容</h3>\n<p>今回は、福岡の鳥料理の名店『ももや精肉堂 薬院本店』様にて、高性能な「消煙機」の設置工事を担当いたしました！</p>\n<p>立地の課題と対策 薬院本店様は、都心のビルが密集したエリアに位置しています。 このような立地では、近隣への排気による「煙の匂い」や「油の飛散」への配慮が非常に重要になります。</p>\n<p> 導入したソリューション ご要望に応じ、「野田の消煙機」を導入。 この消煙機は、煙を軽減するだけでなく、特に油煙を強力に吸着し、外部への油の飛散を大幅に軽減する効果があります。</p>\n<p> 施工のプロ技 都心部のビルイン物件特有の「設置場所がない」という制約をクリアするため、店内の限られたスペースを最大限に活用し、消煙機を組み込みました。 ビル間の狭いスペースに効率よく排気ダクトを立ち上げ、周辺環境に配慮したクリーンな排気を実現しています。</p>\n<p>「美味しい料理を提供する責任」と「地域住民への配慮」。この二律背反の課題を、私たちは確かな技術力でサポートいたします。</p>', '福岡市中央区', '2025-12-19', 'published', '【解決事例】都心部の煙・油煙問題に終止符！「野田の消煙機」設置｜施工事例【株式会社野田】', '今回は、福岡の鳥料理の名店『ももや精肉堂薬院本店』様にて、高性能な「消煙機」の設置工事を担当いたしました！立地の課題と対策薬院本店様は、都心のビルが密集したエリアに位置しています。このような立地では、近隣への排気による…', '5318', '0', '4238', '2025-12-19 17:21:04', '2026-10-21 12:30:19');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('143', 'かわ屋の大量煙対策で特注排煙システム導入しま', 'かわ屋の大量煙対策で特注排煙システム導入しました。', '<h3>施工内容</h3>\n<p>今回は、有名なあの名店シリーズ、特に一番油が出る鶏皮を何度も繰り返し焼くため、通常の店の何倍もの煙が出るという課題に挑戦しました！</p>\n<p>大量の煙を確実に吸い込むための対策は以下の通りです！</p>\n<p>フードフィルター選定: 油分の多い煙に特化した最適なフィルターを選定し、初期段階で油を捕集。</p>\n<p>ダクトの変更: 抵抗を減らし、強力な排煙を可能にするため、丸ダクトから角ダクトへ変更しました。</p>\n<p>ファン選定: 排煙計算に基づき、この大量の煙を確実に処理できる大風量ファンをバッチリ選定！</p>\n<p>これで、煙もぐるぐるぐる吸い込んじゃいます！大量の煙や油分が発生するお店の排煙設計こそ、私たちプロの腕の見せ所です。</p>', '福岡市中央区', '2026-01-05', 'published', 'かわ屋の大量煙対策で特注排煙システム導入しました。｜施工事例【株式会社野田】', '今回は、有名なあの名店シリーズ、特に一番油が出る鶏皮を何度も繰り返し焼くため、通常の店の何倍もの煙が出るという課題に挑戦しました！大量の煙を確実に吸い込むための対策は以下の通りです！フードフィルター選定:油分の多い煙に…', '5324', '0', '4265', '2026-01-05 12:40:29', '2026-10-21 12:30:20');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('144', '飲食店の技術を活かして。コインランドリーのダ', '飲食店の技術を活かして。コインランドリーのダクト工事もお任せ！', '<h3>施工内容</h3>\n<p>「排煙ダクトのプロ」としてのこだわりは、飲食店だけにとどまりません！ 今回は、福岡市東区香椎宮前エリアにオープンの『コインランドリー』様のダクト施工を担当いたしました。</p>\n<p>専門業者ならではの「使い分け」施工<br>コインランドリーの排気システムは、実はとても繊細。<br> 洗濯機・乾燥機の違い:<br>それぞれの排気特性に合わせて、最適な工法を使い分けています。 ガスの種類に対応:<br>使用されるガスの種類に応じて、配管の材質を厳選。安全性と耐久性を両立させます。</p>', '福岡市東区', '2026-02-17', 'published', '飲食店の技術を活かして。コインランドリーのダクト工事もお任せ！｜施工事例【株式会社野田】', '「排煙ダクトのプロ」としてのこだわりは、飲食店だけにとどまりません！今回は、福岡市東区香椎宮前エリアにオープンの『コインランドリー』様のダクト施工を担当いたしました。専門業者ならではの「使い分け」施工コインラ…', '5334', '0', '4353', '2026-02-17 23:21:30', '2026-10-22 02:04:19');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('145', 'ダクトもデザインする。シックな「黒」の吸気グ', 'ダクトもデザインする。シックな「黒」の吸気グリル施工', '<h3>施工内容</h3>\n<p>「内装にはこだわりたい。でも、換気口のシルバーが浮いてしまう…」 そんなお悩み、ありませんか？</p>\n<p>今回は、飲食店の排煙設備に欠かせない「吸気グリル」に、シックな黒の【焼付塗装】を施した事例をご紹介します。</p>\n<p>焼肉店や居酒屋など、煙の多い店舗にとって排煙・吸気は命。 しかし、一般的な既製品では、せっかくの洗練された空間に馴染まないことも。</p>\n<p>当社では、店舗のコンセプトに合わせてグリルのカスタマイズが可能です。 焼付塗装を施すことで、見た目の美しさはもちろん、耐久性もアップ。 油汚れがつきやすい環境でも、長くその質感を保ちます。</p>\n<p>もちろん、フード本体と吸排気効率の高さは、専門業者ならではの仕上がりです。</p>', '北九州市小倉北区', '2026-02-17', 'published', 'ダクトもデザインする。シックな「黒」の吸気グリル施工｜施工事例【株式会社野田】', '「内装にはこだわりたい。でも、換気口のシルバーが浮いてしまう…」そんなお悩み、ありませんか？今回は、飲食店の排煙設備に欠かせない「吸気グリル」に、シックな黒の【焼付塗装】を施した事例をご紹介します。焼肉店や居酒屋など、…', '5353', '0', '4355', '2026-02-17 23:25:12', '2026-10-21 12:30:21');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('146', '社会福祉施設の大型厨房ダクト工事プロジェクト', '社会福祉施設の大型厨房ダクト工事プロジェクト', '<h3>施工内容</h3>\n<p>今回は、社会福祉施設の大型厨房におけるダクト改修工事を担当させていただきました</p>\n<p>工事は天井内部に及ぶため、まずは天井の開口作業からスタートします。普段は見えない場所だからこそ、プロの技術と確かな経験が試される現場です。</p>\n<p>日中の作業中、大きな音が出てしまう場面もありましたが、入居されているおじいちゃんやおばあちゃんたちが興味津々で「視察」に来てくださいました。</p>\n<p>「何を作ってるの？」「頑張ってね！」と温かい叱咤激励をいただき、現場スタッフ一同、より一層身の引き締まる思いで作業にあたりました。皆様の応援のおかげで、無事に完工することができました。</p>\n<p>私たちの仕事の先には、厨房で作られる美味しい食事と、それを楽しみに待っている方々の笑顔があります。</p>\n<p>おじいちゃん、おばあちゃん、美味しいごはんをたくさん食べて、これからも元気にお過ごしください。</p>', '福岡県遠賀郡', '2026-03-16', 'published', '社会福祉施設の大型厨房ダクト工事プロジェクト｜施工事例【株式会社野田】', '今回は、社会福祉施設の大型厨房におけるダクト改修工事を担当させていただきました工事は天井内部に及ぶため、まずは天井の開口作業からスタートします。普段は見えない場所だからこそ、プロの技術と確かな経験が試される現…', '5364', '0', '4404', '2026-03-16 14:49:41', '2026-10-22 02:04:19');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('147', '焼肉の名店を支える、メンテナンス性抜群のダク', '焼肉の名店を支える、メンテナンス性抜群のダクト施工', '<h3>施工内容</h3>\n<p>今回は、中間市にある焼肉の名店にて、上引きフードのダクト工事を担当させていただきました。</p>\n<p>焼肉店、特に脂の乗ったお肉が自慢の人気店様にとって、避けて通れないのが「ダクト内部の油汚れ」です。放っておくと吸い込みが悪くなるだけでなく、火災のリスクにもつながります。</p>\n<p>そこで私たちは、単に設置するだけでなく「未来のメンテナンス」を徹底的に考慮した設計・施工を行いました。</p>\n<p>写真にある通り、ダクトの要所に「蓋を開けて直接清掃できる仕様」の点検口を設置。 数年後のダクト清掃工事の際、手間とコストを大幅に抑えられる、オーナー様想いの特別仕様です。</p>\n<p>「作って終わり」ではなく、長く、安全に、美味しいお肉を提供し続けていただけるように。それが、排煙ダクトのプロとしてのこだわりです。</p>', '福岡県中間市', '2026-03-16', 'published', '焼肉の名店を支える、メンテナンス性抜群のダクト施工｜施工事例【株式会社野田】', '今回は、中間市にある焼肉の名店にて、上引きフードのダクト工事を担当させていただきました。焼肉店、特に脂の乗ったお肉が自慢の人気店様にとって、避けて通れないのが「ダクト内部の油汚れ」です。放っておくと吸い込みが悪くなるだ…', '5371', '0', '4406', '2026-03-16 14:51:58', '2026-10-21 12:30:21');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('148', 'お肉屋さんxイートイン。次世代の焼肉スタイル', 'お肉屋さん×イートイン。次世代の焼肉スタイルを支えるダクト施工！', '<h3>施工内容</h3>\n<p>お肉屋さん×イートイン。 次世代の焼肉スタイルを支えるダクト施工！</p>\n<p>最近、街の精肉店の中に「その場で焼いて食べられる」イートインスペースを併設する店舗様が増えています。</p>\n<p>お肉のプロが選ぶ鮮度抜群の肉を、最高の状態で楽しむ。そんな新しい食のスタイルが、これから大きなトレンドになる予感がしています。</p>\n<p>今回は、そんなお肉屋さんの店内に「上引きフード」の設置工事を施工させていただきました。</p>\n<p>限られたスペースでも、強力な排煙能力で煙をシャットアウト！お客様が快適にお食事を楽しめる環境を整えるのはもちろん、お肉の陳列棚や店内の清潔感を守るためにも、高性能なダクト設備は欠かせません。</p>\n<p>さらに、私たちのこだわりは店内だけではありません。 建物の外観に馴染むよう、外部のガラリ（換気口）もシックな色調で焼付塗装を施しました。</p>', '福岡県糸島市', '2026-03-16', 'published', 'お肉屋さん×イートイン。次世代の焼肉スタイルを支えるダクト施工！｜施工事例【株式会社野田】', 'お肉屋さん×イートイン。次世代の焼肉スタイルを支えるダクト施工！最近、街の精肉店の中に「その場で焼いて食べられる」イートインスペースを併設する店舗様が増えています。お肉のプロが選ぶ鮮度抜群の肉を、最高の状態で楽しむ。そ…', '5374', '0', '4408', '2026-03-16 14:53:51', '2026-10-21 12:30:22');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('149', 'プロが教えるダクトの知恵袋！「キャンパス」と', 'プロが教えるダクトの知恵袋！「キャンパス」と「防振」の重要性', '<h3>施工内容</h3>\n<p>今日は少し専門的な「ダクトの授業」の時間です。舞台は現場という名のキャンパス！</p>\n<p>飲食店、特に焼肉店や居酒屋の命ともいえる排煙ファン。実は、設置した時がゴールではありません。ファンは長年使い続けるうちに、どうしても軸がぶれてきたり、振動が発生したりすることがあります。</p>\n<p>その振動がダクトを伝わって建物全体に響いてしまうと、騒音トラブルや設備の劣化の原因に…。</p>\n<p>そこで私たちが徹底しているのが「事前の振動対策」です。</p>\n<p>写真にある「キャンパス（キャンバス）」と呼ばれる継手は、ファンからダクトへ振動を伝えないためのクッションの役割を果たします。さらに、防振ゴムを併用することで、建物への負担を最小限に抑えます。</p>\n<p>「長く、安心して商売を楽しんでいただきたい」 そんな想いから、数年後の状態まで見越して、目に見えない部分まで丁寧に施工するのが私たちのスタイルです</p>', '福岡市中央区', '2026-03-16', 'published', 'プロが教えるダクトの知恵袋！「キャンパス」と「防振」の重要性｜施工事例【株式会社野田】', '今日は少し専門的な「ダクトの授業」の時間です。舞台は現場という名のキャンパス！飲食店、特に焼肉店や居酒屋の命ともいえる排煙ファン。実は、設置した時がゴールではありません。ファンは長年使い続けるうちに、どうしても…', '5380', '0', '4411', '2026-03-16 14:56:55', '2026-10-22 02:04:19');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('150', 'テンプレ教会の厨房ダクト施工', '教会の厨房ダクト施工', '<h3>施工内容</h3>\n<p>今回は、多くの人々が集い祈りを捧げる「教会」の厨房フード設置工事を担当させていただきました。</p>\n<p>教会という場所柄、周囲には住宅も多く、何より静かな環境が大切にされます。そこで今回のダクト工事では、近隣の方々への配慮を最優先した「徹底的な防音・防振対策」を取り入れています</p>\n<p>まず、音の漏れを防ぐために「防音ダクト」を採用。排気音が外に響くのを最小限に抑えます。</p>\n<p>さらに、今日の重要なポイントは「防振金具」の使用ですファンの振動が建物の構造に伝わると、それが騒音となって周囲に伝わってしまいます。それを防振金具でしっかり受け止めることで、物理的な振動もシャットアウトしました。</p>\n<p>「人が集まる場所だからこそ、周囲への優しさを忘れない」 これは、住宅街にある焼肉店や居酒屋のオーナー様にとっても非常に大切なポイントではないでしょうか。</p>\n<p>私たちプロの技術で、美味しい料理の香りは残しつつ、騒音トラブルとは無縁の快適な環境をお約束します</p>', '福岡市城南区', '2026-04-27', 'published', '教会の厨房ダクト施工｜施工事例【株式会社野田】', '今回は、多くの人々が集い祈りを捧げる「教会」の厨房フード設置工事を担当させていただきました。教会という場所柄、周囲には住宅も多く、何より静かな環境が大切にされます。そこで今回のダクト工事では、近隣の方々への配慮を最優先…', '5396', '0', '4434', '2026-04-27 15:01:52', '2026-10-22 02:04:19');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('151', '古木の梁をかわす大蛇のダクト施工', '古木の梁をかわす”大蛇”のダクト施工', '<h3>施工内容</h3>\n<p>いま福岡で最も勢いのある焼肉店様にて、排煙ダクト工事を施工させていただきました。</p>\n<p>店内に一歩入ると、古木の梁が織りなす重厚な空間。 このノスタルジックな雰囲気を一切壊すことなく、梁を一本一本かわしながら、まるで大蛇が天井を這うようにダクトを敷設しました。</p>\n<p>古い建物や複雑な構造の店舗ほど、私たちの腕が鳴ります。</p>\n<p>今回の上引きフードはメーカー様からの支給品。 メーカー様からは豊富な経験に裏打ちされた的確なアドバイスをいただき、その設計意図を忠実に再現する施工で仕上げました。</p>\n<p>結果── 煙はスネークのようにシャーシャーと吸い込まれ、客席には快適な空気だけが残ります。</p>\n<p>「古い物件で排煙が取れるか不安…」 「梁や柱が多くてダクトを通せるか心配…」 「煙がこもって客足に影響している…」</p>\n<p>そんなお悩み、野田にご一報ください。 現地調査からご相談まで対応いたします。</p>\n<p>ちなみに、写真に映っている炭火焼用の炉も当社オリジナル製品です。 焼肉店・居酒屋の開業や改装をお考えの方、絶賛販売中ですのでお気軽にお問い合わせを。</p>', '福岡市中央区', '2026-04-27', 'published', '古木の梁をかわす”大蛇”のダクト施工｜施工事例【株式会社野田】', 'いま福岡で最も勢いのある焼肉店様にて、排煙ダクト工事を施工させていただきました。店内に一歩入ると、古木の梁が織りなす重厚な空間。このノスタルジックな雰囲気を一切壊すことなく、梁を一本一本かわしながら、まるで大蛇が天井を…', '5404', '0', '4529', '2026-04-27 15:03:59', '2026-10-21 12:30:24');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('152', 'テンプレ化学臭もお任せ！アクリル制作の現場を', '化学臭もお任せ！アクリル制作の現場を支える脱臭ダクト工事', '<h3>施工内容</h3>\n<p>今回は飲食店を飛び出し、アクリルノベルティ制作会社様の工場にて脱臭ダクト工事を施工させていただきました</p>\n<p>可愛いキャラクターやグッズが作られるアクリル加工の現場。実は、加工の過程で独特な「化学臭」が発生してしまいます。</p>\n<p>スタッフの皆様が健やかに、そして集中して作業に打ち込めるよう、強力な脱臭・排気システムを構築しました。</p>\n<p>素敵なノベルティ制作の裏側には、私たち「空気の環境作り」のプロが、縁の下の力持ちとしてしっかり支えています。</p>\n<p>私たちは、焼肉店や居酒屋の強力な油煙だけでなく、こうした繊細な排気・脱臭対策も得意分野です。</p>\n<p>「店舗の隣が住宅で匂いが心配…」 「特殊な機材を使うので、排気のアドバイスが欲しい」そんなお悩みをお持ちのオーナー様や内装設計者様、ぜひ一度ご相談ください。</p>', '福岡市南区', '2026-04-27', 'published', '化学臭もお任せ！アクリル制作の現場を支える脱臭ダクト工事｜施工事例【株式会社野田】', '今回は飲食店を飛び出し、アクリルノベルティ制作会社様の工場にて脱臭ダクト工事を施工させていただきました可愛いキャラクターやグッズが作られるアクリル加工の現場。実は、加工の過程で独特な「化学臭」が発生して…', '5434', '0', '4531', '2026-04-27 15:06:51', '2026-10-22 02:04:19');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('153', '博多区に移転オープン！炭火料理を支える大型フ', '博多区に移転オープン！炭火料理を支える大型フード施工', '<h3>施工内容</h3>\n<p>今回は、福岡市博多区に移転オープンされた小料理屋様の排煙ダクト工事を担当させていただきました。新天地での新たな門出、誠におめでとうございます！</p>\n<p>こちらの店舗様では炭火を使用したこだわりの料理を提供されるとのこと。炭火料理は香ばしい香りが魅力ですが、その分「煙」と「熱」への対策が非常に重要になります。</p>\n<p>お客様が快適に、そして静かにお食事を楽しめる空間を作るため、今回は通常よりも「大きめのフード」を設計・設置いたしました。</p>\n<p>吸い込み口を広く確保することで、炭火から立ち上がる煙を逃さずキャッチ。店内に煙がこもるのを防ぎ、内装の美しさも長く保つことができます。</p>\n<p>さらに、外壁側の排気口も建物の雰囲気を損なわないよう丁寧に仕上げました。</p>\n<p>博多という飲食店激戦区で、オーナー様のこだわりが詰まった料理を最高の環境で提供できるよう、私たちは「空気の通り道」から全力でサポートいたします。</p>', '福岡市博多区', '2026-04-27', 'published', '博多区に移転オープン！炭火料理を支える大型フード施工｜施工事例【株式会社野田】', '今回は、福岡市博多区に移転オープンされた小料理屋様の排煙ダクト工事を担当させていただきました。新天地での新たな門出、誠におめでとうございます！こちらの店舗様では炭火を使用したこだわりの料理を提供されるとのこと。…', '5438', '0', '4535', '2026-04-27 15:10:15', '2026-10-22 02:04:19');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('154', '古美の風格、されど新品──焼付塗装フードの', '“古美”の風格、されど新品──焼付塗装フードの真骨頂', '<h3>施工内容</h3>\n<p>一見すると、年月を重ねた骨董品のような重厚感を放っていますが、これは最新の技術によって生み出された新品の排気フードです。</p>\n<p>本製品は、高度な焼き付け塗装に繊細なグラデーション仕上げを施した逸品です。長年使い込まれたような深みと風格を、新品の段階から空間に纏わせることが可能となりました。</p>\n<p>焼き付け塗装がもたらす圧倒的な質感</p>\n<p>一般的なペンキ塗装とは一線を画す、焼き付け塗装ならではの質感を追求しています。</p>\n<p>触感： 手に馴染むような滑らかさ</p>\n<p>視覚： 光の加減によって表情を変える奥行きのある色彩</p>\n<p>調和： 店舗のコンセプトを象徴する圧倒的な存在感</p>\n<p>「設備」から「空間を構成する意匠」へ</p>\n<p>カウンター越しに見える排気フードは、お客様の視線に最も触れる設備の一つです。私たちは、フードを単なる「排気のための道具」とは考えておりません。</p>\n<p>空間の世界観を壊すことなく、むしろその格を引き上げる。</p>\n<p>このレベルの塗装仕上げをフードとして提供できるのは、当社の熟練した技術力があってこそと自負しております。</p>\n<p>導入をご検討の皆様へ</p>\n<p>焼肉店、鉄板焼き、炉端焼き、割烹など、煙と向き合う業態だからこそ、フードの「美学」にもこだわりたい。</p>\n<p>店舗のアイデンティティをより強固にしたいオーナー様、および設計士の皆様、ぜひ一度ご相談ください。</p>', '福岡市中央区', '2026-04-27', 'published', '“古美”の風格、されど新品──焼付塗装フードの真骨頂｜施工事例【株式会社野田】', '一見すると、年月を重ねた骨董品のような重厚感を放っていますが、これは最新の技術によって生み出された新品の排気フードです。本製品は、高度な焼き付け塗装に繊細なグラデーション仕上げを施した逸品です。長年使い込まれたような深…', '5447', '0', '4537', '2026-04-27 15:13:36', '2026-10-21 12:30:24');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('155', '【有名ラーメン店の心臓部】セントラルキッチ', '【有名ラーメン店の”心臓部”】セントラルキッチンの排煙設備、丸ごと施工', '<h3>施工内容</h3>\n<p>有名ラーメン店「いちむじん」様のセントラルキッチンにて、排煙設備の施工を担当させていただきました。</p>\n<p>セントラルキッチン── それは全店舗の味を支える、いわば”心臓部”。</p>\n<p>覗き込めばわかるこのフードの数。 大量の寸胴が並ぶ仕込みラインの上に、ずらりとフードが連なります。 ステンレスの鏡面に映り込む厨房の風景が、仕上がりの精度を物語っています。</p>\n<p>天井を見上げれば、角ダクト・丸ダクト・送風機が所狭しと走る圧巻の配管群。 限られた天井スペースの中で、排気・給気・空調のルートを整理し、効率的に煙と熱を逃がす設計を実現しました。</p>\n<p>セントラルキッチンは通常の店舗とは比べものにならない排煙量を求められます。 フードの数、ダクト径の選定、ファンの能力計算── すべてを一括で対応できるのが、排煙ダクト専門業者である私たちの強みです。</p>\n<p>「多店舗展開に向けてセントラルキッチンを構えたい」 「既存のセントラルキッチンの排煙が追いついていない」 「新規出店のスピードに施工が間に合わない」</p>\n<p>そんなお悩みをお持ちのオーナー様、設計事務所様、施工会社様。 規模の大小を問わず、まずはお気軽にご相談ください。</p>', '福岡市中央区', '2026-04-27', 'published', '【有名ラーメン店の”心臓部”】セントラルキッチンの排煙設備、丸ごと施工｜施工事例【株式会社野田】', '有名ラーメン店「いちむじん」様のセントラルキッチンにて、排煙設備の施工を担当させていただきました。セントラルキッチン──それは全店舗の味を支える、いわば”心臓部”。覗き込めばわかるこのフードの数。大量の寸胴が並ぶ仕込み…', '5455', '0', '4539', '2026-04-27 15:15:47', '2026-10-21 12:30:25');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('156', '【久留米・焼き鳥激戦区】屋上まで駆け上がるダ', '【久留米・焼き鳥激戦区】屋上まで駆け上がるダクトと鏡面ステンレスフード', '<h3>施工内容</h3>\n<p>この街で新たに勝負を挑む焼き鳥店様にて、ステンレスフードの設置工事と外部ダクトの立ち上げ工事を施工させていただきました。</p>\n<p>まず店内に目を向けると、鏡面仕上げのステンレスフード。 天井も照明も、すべてが映り込むほどの美しい光沢。 焼き鳥屋さんは客席からカウンター越しに厨房が見える店づくりが多いからこそ、フードの”見た目”は店の印象を左右します。</p>\n<p>そして今回のもうひとつのポイントが、外部ダクトの屋上立ち上げです。</p>\n<p>焼き鳥店の排煙は、炭火の煙とタレが焼ける香ばしい煙が大量に出ます。 旨そうな匂いも、近隣にとっては毎日となると話が変わってくる。 だからこそ、ダクトをキリンの首のようにビルの屋上までまっすぐ立ち上げ、高所で排気することで近隣への煙・臭気を最大限配慮しました。</p>\n<p>開業してから「近隣からクレームが…」では遅いんです。 排煙計画は、出店の段階で勝負が決まります。</p>\n<p>「激戦区で新規出店を考えている」 「近隣との関係が心配で排煙ルートに悩んでいる」 「ビルの上階まで立ち上げる工事ができる業者を探している」</p>\n<p>そんなオーナー様、設計士様、施工会社様。 煙の”出口戦略”は、野田にお任せください。</p>', '福岡県久留米市', '2026-04-27', 'published', '【久留米・焼き鳥激戦区】屋上まで駆け上がるダクトと鏡面ステンレスフード｜施工事例【株式会社野田】', 'この街で新たに勝負を挑む焼き鳥店様にて、ステンレスフードの設置工事と外部ダクトの立ち上げ工事を施工させていただきました。まず店内に目を向けると、鏡面仕上げのステンレスフード。天井も照明も、すべてが映り込むほどの美しい光…', '5462', '0', '4542', '2026-04-27 15:17:54', '2026-10-21 12:30:25');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('157', 'キッチンに大型アイランドフード設置', 'キッチンに大型アイランドフード設置', '<h3>施工内容</h3>\n<p>この度、キッチンの中心設備となる、大規模な排気フードの設置工事が完了いたしました。</p>\n<p>今回の現場は、あらゆる角度からの調理に対応するアイランドキッチン仕様。それに合わせ、四方から効率的に吸気を行う大型サイズを導入しております。ステンレス特有の硬質な輝きと、機能美に裏打ちされた圧倒的なボリューム感は、まさにプロフェッショナルな厨房を象徴する仕上がりとなりました。</p>\n<p>現場の最適化を追求する設計・施工</p>\n<p>当社では、設置場所の条件や調理負荷に応じ、大規模から小規模まで柔軟な設計・施工を展開しております。</p>\n<p>緻密な吸排気計画： 高度な換気能力が求められる現場でも、最適な風量計算に基づいた施工を行います。</p>\n<p>特殊レイアウトへの対応： アイランドキッチンをはじめ、建物の構造や動線に合わせた特殊な設置形態にも対応可能です。</p>\n<p>大規模な厨房設備の新設や、複雑な吸排気計画を必要とするプロジェクトも、確かな実績を持つ当社へ安心してお任せください。オーナー様および設計担当者様の理想を、確かな技術で形にいたします。</p>', '福岡市中央区', '2026-04-27', 'published', 'キッチンに大型アイランドフード設置｜施工事例【株式会社野田】', 'この度、キッチンの中心設備となる、大規模な排気フードの設置工事が完了いたしました。今回の現場は、あらゆる角度からの調理に対応するアイランドキッチン仕様。それに合わせ、四方から効率的に吸気を行う大型サイズを導入しておりま…', '5473', '0', '4544', '2026-04-27 15:25:52', '2026-10-21 12:30:26');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('158', '「煙を出さない」焼肉店！消煙機導入工事完了', '「煙を出さない」焼肉店！消煙機導入工事完了', '<h3>施工内容</h3>\n<p>歓楽街・中洲のど真ん中に位置する人気店「焼肉ここから」様にて、高性能消煙機の導入工事をさせていただきました！<br>飲食店が密集し、どこからともなく煙が漂う中洲エリア。<br>そんな場所であっても、近隣環境への配慮を忘れず「煙を除去する」という選択をされたオーナー様の素晴らしいお心遣いに、心から感服いたしました。</p>\n<p>焼肉は「ここから」始まりますが、煙はどこからも出ていきません！（笑）<br>最新の消煙システムによって、クリーンな排気を実現しています。</p>\n<p>「煙やニオイが原因で近隣からクレームが来ている…」<br>「立地条件のせいで重飲食の出店を諦めている…」<br>そんなお悩みを持つオーナー様、消煙機という選択肢を検討してみませんか？</p>', '福岡市博多区', '2026-06-02', 'published', '「煙を出さない」焼肉店！消煙機導入工事完了｜施工事例【株式会社野田】', '歓楽街・中洲のど真ん中に位置する人気店「焼肉ここから」様にて、高性能消煙機の導入工事をさせていただきました！飲食店が密集し、どこからともなく煙が漂う中洲エリア。そんな場所であっても、近隣環境への配慮を忘れず「煙を除去す…', '5479', '0', '4568', '2026-06-02 21:50:26', '2026-10-21 12:30:26');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('159', '漆黒の美学。鶏焼肉店のダクト施工が完了！', '漆黒の美学。鶏焼肉店のダクト施工が完了！', '<h3>施工内容</h3>\n<p>鶏焼肉、鶏焼肉、鶏焼肉！<br>こだわりの詰まった鶏焼肉店様のダクト・フード設置工事を担当させていただきました。</p>\n<p>今回のポイントは、何と言ってもこの「色」。<br>洗練されたモダンな内装に合わせて、フードもダクトもすべて「漆黒」で統一。<br>空間の雰囲気を壊すことなく、むしろインテリアの一部として店舗を引き立てるシックな仕上がりになりました。</p>\n<p>もちろん、見た目だけではありません。<br>吸い込みの良さは折り紙付き！煙をグングン吸い込み、お客様が快適にお食事を楽しめるクリーンな空間を実現しています。</p>\n<p>デザイン性にこだわりたいオーナー様や内装設計事業者様。<br>「機能性とデザインを両立させたい」というワガママ、ぜひ私たちにぶつけてください！</p>', '大分県', '2026-06-02', 'published', '漆黒の美学。鶏焼肉店のダクト施工が完了！｜施工事例【株式会社野田】', '鶏焼肉、鶏焼肉、鶏焼肉！こだわりの詰まった鶏焼肉店様のダクト・フード設置工事を担当させていただきました。今回のポイントは、何と言ってもこの「色」。洗練されたモダンな内装に合わせて、フードもダクトもすべて「漆黒」で統一。…', '5487', '0', '4570', '2026-06-02 21:52:05', '2026-10-21 12:30:26');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('160', '平尾の人気店に消煙機を設置しました！', '平尾の人気店に消煙機を設置しました！', '<h3>施工内容</h3>\n<p>こちらは、宮崎の有名ブランド地鶏「八幸鶏」が福岡で唯一食べられる大人気店！オーナー様こだわりの絶品炭火焼き鳥と、私どもも大好物な宮崎の20度焼酎の相性はまさにゼッコー鳥（鳥）です！</p>\n<p>そんな美味しいお料理で活気あふれる名店だからこそ、外に出る煙や臭いへの配慮はさすがの一言。<br>おしゃれな街の景観を損なわないよう、すっきりと機能的に消煙機を配置し、周辺環境へのエチケットも万全に仕上げました。</p>\n<p>おしゃれなエリアや住宅街が近い立地では、どんなに美味しいお店でも煙や臭いの近隣対策が店舗運営の大きな鍵になります。</p>\n<p>「うちのこだわり炭火焼きや焼肉の煙、ご近所迷惑になっていないかな…」<br>「新しくオープンするお店のイメージを崩さずに、しっかり脱臭対策をしたい！」<br>そんなお悩みをお持ちの<strong>焼き鳥店</strong>、<strong>焼肉店</strong>、<strong>居酒屋</strong>のオーナー様、ぜひ一度私たちにご相談ください！</p>', '福岡市中央区', '2026-06-25', 'published', '平尾の人気店に消煙機を設置しました！｜施工事例【株式会社野田】', 'こちらは、宮崎の有名ブランド地鶏「八幸鶏」が福岡で唯一食べられる大人気店！オーナー様こだわりの絶品炭火焼き鳥と、私どもも大好物な宮崎の20度焼酎の相性はまさにゼッコー鳥（鳥）です！そんな美味しいお料理で活気あふれる名店…', '5495', '0', '4601', '2026-06-25 09:45:44', '2026-10-22 02:05:35');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('161', '大容量の特注「大型山型フード」が誕生！', '大容量の特注「大型山型フード」が誕生！', '<h3>施工内容</h3>\n<p>厨房に設置したのは、存在感抜群の黒い特注「大型山型フード」！<br>焼き鳥から出る大量の煙や油をグングン吸い込む頼もしい設計で高い捕集能力を誇ります。</p>\n<p>もちろん、こだわりの内装やおしゃれな店舗イメージを崩さないスタイリッシュな外観にもこだわりました。さらに、屋外には高性能な消煙機（排煙脱臭装置）もしっかりと連結配置！周辺の環境や、近隣住民の方々へのクリーンな空気の配慮も100点満点！絶好調な仕上がりです！</p>\n<p>美味しい焼き鳥の煙や臭い対策は、お店のクリーンなイメージを守り、長く地域に愛されるために必要不可欠な要素です。</p>\n<p>「新しくオープンするお店にピッタリの特注フードを作りたい」<br>「煙の多い業態だけど、厨房も客席もすっきり快適に保ちたい！」<br>そんなお悩みをお持ちの焼き鳥店、焼肉店、居酒屋のオーナー様、ぜひ私たち排煙のプロにご相談ください！</p>', '北九州市小倉北区', '2026-06-25', 'published', '大容量の特注「大型山型フード」が誕生！｜施工事例【株式会社野田】', '厨房に設置したのは、存在感抜群の黒い特注「大型山型フード」！焼き鳥から出る大量の煙や油をグングン吸い込む頼もしい設計で高い捕集能力を誇ります。もちろん、こだわりの内装やおしゃれな店舗イメージを崩さないスタイリッシュな外…', '5505', '0', '4603', '2026-06-25 09:48:14', '2026-10-21 12:30:27');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('162', '広島のオシャレなパン屋さん！天井の低い難所を', '広島のオシャレなパン屋さん！天井の低い難所をクリアした特注ダクト工事', '<h3>施工内容</h3>\n<p>パン屋さんのスチコン（スチームコンベクションオーブン）用フードの設置だったのですが、写真の通りとにかく天井が低かったため、ルートの確保が大変な現場でした。</p>\n<p>梁（はり）や既存の配管を絶妙にかわしながら、ミリ単位でルートを計算。綺麗に丸ダクトを配管していきました。狭い室内から屋外の排気口まで、職人の高い技術力でスムーズな空気の流れをガッチリ確保しています！</p>\n<p>焼き立ての美味しいパンの香りはそのままに、厨房の熱気や蒸気をしっかり外へ逃がす最高の排気システムが完成しました。</p>\n<p>排煙ダクトやスチコンの換気設備は、建物の構造に合わせてオーダーメイドで設計・施工するのが私たちの強みです。「天井が低くて設備が入らないかもしれない…」とお悩みの店舗オーナー様、諦める前にぜひ一度私たちプロにご相談ください！</p>', '広島市西区', '2026-06-25', 'published', '広島のオシャレなパン屋さん！天井の低い難所をクリアした特注ダクト工事｜施工事例【株式会社野田】', 'パン屋さんのスチコン（スチームコンベクションオーブン）用フードの設置だったのですが、写真の通りとにかく天井が低かったため、ルートの確保が大変な現場でした。梁（はり）や既存の配管を絶妙にかわしながら、ミリ単位でルートを計…', '5510', '0', '4605', '2026-06-25 09:53:16', '2026-10-21 12:30:27');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('163', 'お家で本格焼肉！お酒も進む「最終形態」のリビ', 'お家で本格焼肉！お酒も進む「最終形態」のリビングが完成！', '<h3>施工内容</h3>\n<p>「家でもお店みたいな本格的な焼肉を楽しみたい！」<br>「煙や臭いを気にせず、お肉とお酒を心ゆくまで堪能して、食べたらすぐ寝たい！」<br>そんな誰もが一度は夢見る願望を、私たちの排煙技術で形にいたしました！</p>\n<p>今回は一般のご家庭向けに、どんな内装にも馴染んで高級感を醸し出す、ブロンズ色の上引きフードをご提案・設置いたしました。<br>完成後、お世辞抜きでリビングがものすごくスタイリッシュでかっこいい空間に仕上がっています！</p>\n<p>これまで外食のたびにお父さんとお母さんの間で繰り広げられていた「今日はどちらが運転してお酒を飲むか」という終わりなき紛争も、このお家焼肉システムがあれば完全に終止符です。これからはご夫婦揃って、自宅で最高の焼肉時間を楽しんでいただけます。</p>\n<p>外の排気口やファンの設置まで、私たちは店舗クオリティの確かな計算のもと施工を行っています。お酒好きのご夫婦仲の平和、そして世界平和の第一歩は、ぜひ私たち野田におまかせください！</p>', '北九州市八幡西区', '2026-07-20', 'published', 'お家で本格焼肉！お酒も進む「最終形態」のリビングが完成！｜施工事例【株式会社野田】', '「家でもお店みたいな本格的な焼肉を楽しみたい！」「煙や臭いを気にせず、お肉とお酒を心ゆくまで堪能して、食べたらすぐ寝たい！」そんな誰もが一度は夢見る願望を、私たちの排煙技術で形にいたしました！今回は一般のご家庭向けに、…', '5516', '0', '4669', '2026-07-20 22:12:23', '2026-10-21 12:30:27');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('164', 'みんな大好き！「すき家」様の厨房フード工事を', 'みんな大好き！「すき家」様の厨房フード工事を施工いたしました！', '<h3>施工内容</h3>\n<p>今回は、誰もがお世話になっている大人気牛丼チェーン「すき家」様での厨房フード設置工事の事例をご紹介します！</p>\n<p>もちろん、実際の施工は一切の妥協なし！<br>ご覧の通り、ピカピカに美しく磨き上げられたオールステンレスの特注厨房フードを隙間なくきっちりと設置いたしました。</p>\n<p>毎日多くの注文が飛び交う大手チェーン店様の厨房だからこそ、確実な排気能力と高い衛生管理を維持できる頑丈なフード設計が求められます。ダクトだけでなく、排気効率や吸気のバランス、そして働くスタッフの皆様が快適に過ごせる環境づくりまでプロの目線でバッチリ仕上げています。</p>', '大分県大分市', '2026-08-31', 'published', 'みんな大好き！「すき家」様の厨房フード工事を施工いたしました！｜施工事例【株式会社野田】', '今回は、誰もがお世話になっている大人気牛丼チェーン「すき家」様での厨房フード設置工事の事例をご紹介します！もちろん、実際の施工は一切の妥協なし！ご覧の通り、ピカピカに美しく磨き上げられたオールステンレスの特注厨房フード…', '5522', '0', '4671', '2026-08-31 10:57:12', '2026-10-21 12:30:29');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('165', '梁（はり）があっても諦めない！梁干渉をクリア', '梁（はり）があっても諦めない！梁干渉をクリアする特注変形フードの施工事例！', '<h3>施工内容</h3>\n<p>「厨房内の天井にある大きな梁が邪魔をして、既製品のフードが設置できない…」<br>そんな店舗設計の難所も、私たち排煙のプロにおまかせあれ！</p>\n<p>今回は、厨房内の梁が干渉してしまう現場に合わせて、形状をぴったりと合わせた特注変形フードを自社制作して取り付けいたしました。現場の構造にミリ単位で合わせることで、スペースを無駄にせず美しい厨房環境を実現しています。</p>\n<p>ここで排煙のプロが教える「今日の豆知識」！<br>厨房のフードを選ぶ際、ついつい縦横の「大きさ」ばかりに目がいきがちですが、実は「深さ」が特に大事なんです。<br>フードに十分な深さがないと、せっかく一度中に入った煙が外へ逃げ出してしまいます。だからこそ、現場ごとの排気量や構造計算をしっかり行わないと、店内に煙が漏れ出して大変なことになってしまうのです。以上、今日の豆知識でした。かしこ。</p>\n<p>特に煙の多い焼肉店や居酒屋では、この絶妙なフードの深さと構造計算が店舗環境を左右します。</p>', '福岡市博多区', '2026-08-31', 'published', '梁（はり）があっても諦めない！梁干渉をクリアする特注変形フードの施工事例！｜施工事例【株式会社野田】', '「厨房内の天井にある大きな梁が邪魔をして、既製品のフードが設置できない…」そんな店舗設計の難所も、私たち排煙のプロにおまかせあれ！今回は、厨房内の梁が干渉してしまう現場に合わせて、形状をぴったりと合わせた特注変形フード…', '5561', '0', '4753', '2026-08-31 11:00:46', '2026-10-21 12:30:30');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('166', 'ビルの壁面高くにダクトを配管する大型施工事例', 'ビルの壁面高くにダクトを配管する大型施工事例', '<h3>施工内容</h3>\n<p>もちろん、高い場所だけでなく、屋上の大型ファン設置から厨房内のピカピカな特注フード工事まで、上下左右どこであっても徹底的な構造計算のもと、煙漏れのない完璧な排気システムを作り上げます。</p>\n<p>「ビルの上の階にある店舗だから、排気ダクトの工事が難しそう…」<br>「煙や臭いの効率的なルート設計に悩んでいる」<br>そんなお悩みをお持ちの飲食店オーナー様やビルオーナー様、どのような高所・難所であっても私たちプロに安心しておまかせください！</p>', '大分県別府市', '2026-08-31', 'published', 'ビルの壁面高くにダクトを配管する大型施工事例｜施工事例【株式会社野田】', 'もちろん、高い場所だけでなく、屋上の大型ファン設置から厨房内のピカピカな特注フード工事まで、上下左右どこであっても徹底的な構造計算のもと、煙漏れのない完璧な排気システムを作り上げます。「ビルの上の階にある店舗だから、排…', '5570', '0', '4755', '2026-08-31 11:02:45', '2026-10-21 12:30:30');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('167', '広島一番の酒どころ西条！古民家再生ビル「b工事', '広島一番の酒どころ西条！古民家再生ビル「B工事」施工事例', '<h3>施工内容</h3>\n<p>今回は、広島一番の酒どころとして知られる東広島市西条の「酒蔵通り」にある古民家再生複合施設での施工事例をご紹介します！<br>建物オーナー様からの「激烈なご指名」をいただき、なんと全6店舗分のメインダクト工事を弊社が一手に担わせていただきました！<br><br>古民家の良さを活かした複雑な構造の中でも、6店舗分すべての排気をスムーズに外へ逃がす完璧なメインダクト＆排気ファンシステムを構築しています。<br>排煙ダクトの「B工事（ビルオーナー指定の業者が施工する工事）」でお困りの建築業者様、オーナー様！<br>複雑な店舗ビルや複合施設のダクト計画も、確かな計算と実績を誇る私たちにおまかせください！</p>', '広島県東広島市', '2026-08-31', 'published', '広島一番の酒どころ西条！古民家再生ビル「B工事」施工事例｜施工事例【株式会社野田】', '今回は、広島一番の酒どころとして知られる東広島市西条の「酒蔵通り」にある古民家再生複合施設での施工事例をご紹介します！建物オーナー様からの「激烈なご指名」をいただき、なんと全6店舗分のメインダクト工事を弊社が一手に担わ…', '5590', '0', '4757', '2026-08-31 11:04:50', '2026-10-22 02:04:19');
INSERT INTO `cases` (`id`, `slug`, `title`, `body_html`, `location`, `published_at`, `status`, `seo_title`, `seo_description`, `thumbnail_image_id`, `needs_review`, `wp_id`, `created_at`, `updated_at`) VALUES ('168', '福岡を代表する老舗旅館様！おもてなしの舞台裏', '福岡を代表する老舗旅館様！おもてなしの舞台裏を支える厨房ダクト施工事例', '<h3>施工内容</h3>\n<p>今回は、福岡が誇る老舗旅館様の厨房ダクト工事をご依頼いただきました！</p>\n<p>建物の複雑な外壁に沿って描かれた、この流れるような配管ルート。<br>滑らかな流線型を帯びたフォルムと、空へ向かってちょっぴり哀愁を漂わせる吹き出し口…思わず見惚れてしまうほど美しく機能的な仕上がりです。</p>\n<p>お客様へ最高のお料理とおもてなしを提供する「舞台裏」を、私たちの技術でしっかりとサポートいたします。</p>\n<p>老舗旅館や歴史ある店舗の建物は、配管の取り回しが難しいケースも少なくありません。</p>\n<p>「建物の雰囲気を損ねずに、強力な排気システムを作りたい」<br>「複雑な外壁だけど、綺麗にダクトを通せるだろうか…」<br>そんなお悩みをお持ちの旅館・飲食店オーナー様、ぜひ私たちにおまかせください！</p>', '福岡県筑紫野市', '2026-08-31', 'published', '福岡を代表する老舗旅館様！おもてなしの舞台裏を支える厨房ダクト施工事例｜施工事例【株式会社野田】', '今回は、福岡が誇る老舗旅館様の厨房ダクト工事をご依頼いただきました！建物の複雑な外壁に沿って描かれた、この流れるような配管ルート。滑らかな流線型を帯びたフォルムと、空へ向かってちょっぴり哀愁を漂わせる吹き出し口…思わず…', '5638', '0', '4759', '2026-08-31 11:07:10', '2026-10-21 12:30:32');
